INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2760fdac-a7d8-5cf0-a890-c8c8d29db13a', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '43e8346a-35b0-518c-aec9-ad1c5bf4e193', 2, 2, 'እርሱ ግን መልሶ እንዲህ አላቸው “በመሸ ጊዜ ‘ሰማዩ ቀልቶአልና ብራ ይሆናል’ ትላላችሁ።'),
  ('5dfd3244-453e-5248-a3ca-231351963c0d', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '43e8346a-35b0-518c-aec9-ad1c5bf4e193', 3, 3, 'ማለዳም ‘ሰማዩ ደምኖ ቀልቶአልና ዛሬ ይዘንባል’ ትላላችሁ። የሰማዩን ፊትማ መለየት ታውቃላችሁ፤ የዘመኑንስ ምልክት መለየት አትችሉምን?'),
  ('f5806a37-5c64-5245-a02d-1da24f29ee10', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '43e8346a-35b0-518c-aec9-ad1c5bf4e193', 4, 4, 'ክፉና አመንዝራ ትውልድ ምልክት ይሻል፤ ከነቢዩም ከዮናስ ምልክት በቀር ምልክት አይሰጠውም።” ትቶአቸውም ሄደ።'),
  ('efa3a866-d410-571a-ab43-0650e416abca', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', 'e34bdcf8-e5e6-5b30-a184-416a33f48982', 1, 5, 'ደቀ መዛሙርቱም ወደ ማዶ በመጡ ጊዜ እንጀራ መያዝን ረሱ።'),
  ('b955255d-6c70-5ebb-ae68-f6b5ca632716', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', 'e34bdcf8-e5e6-5b30-a184-416a33f48982', 2, 6, 'ኢየሱስም “ከፈሪሳውያንና ከሰዱቃውያን እርሾ ተጠንቀቁና ተጠበቁ፤” አላቸው።'),
  ('79847525-7e39-5c73-a873-98ed24433841', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', 'e34bdcf8-e5e6-5b30-a184-416a33f48982', 3, 7, 'እነርሱም “እንጀራ ባንይዝ ነው፤” ብለው እርስ በርሳቸው ተነጋገሩ።'),
  ('aa7243d3-b9e8-5837-ac4c-7b553359eb04', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', 'e34bdcf8-e5e6-5b30-a184-416a33f48982', 4, 8, 'ኢየሱስም አውቆ እንዲህ አላቸው “እናንተ እምነት የጐደላችሁ፥ እንጀራ ስለ ሌላችሁ ስለ ምን እርስ በርሳችሁ ትነጋገራላችሁ? ገና አታስተውሉምን?'),
  ('df16d0a5-04bd-5f9a-a26d-80ffd6a280dc', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', 'e34bdcf8-e5e6-5b30-a184-416a33f48982', 5, 9, 'ለአምስቱ ሺህ አምስቱ እንጀራ፥ ስንት መሶብም እንዳነሣችሁ ትዝ አይላችሁምን?'),
  ('ba221ab3-8786-549b-a145-375b9ed78d24', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', 'e34bdcf8-e5e6-5b30-a184-416a33f48982', 6, 10, 'ወይስ ለአራቱ ሺህ ሰባቱ እንጀራ፥ ስንት ቅርጫትም እንዳነሣችሁ ትዝ አይላችሁምን?'),
  ('0adc72b2-1b78-5cf3-a072-b0bc2cedd0b8', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', 'e34bdcf8-e5e6-5b30-a184-416a33f48982', 7, 11, 'ከፈሪሳውያንና ከሰዱቃውያን እርሾ እንድትጠበቁ ብዬ ስለ እንጀራ እንዳልተናገርኋችሁ እንዴት አታስተውሉም?”'),
  ('f1f982b8-12d1-54c6-af3d-d3f796a57074', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', 'e34bdcf8-e5e6-5b30-a184-416a33f48982', 8, 12, 'እነርሱም ከፈሪሳውያንና ከሰዱቃውያን ትምህርት እንጂ ከእንጀራ እርሾ እንዲጠበቁ እንዳላላቸው ያን ጊዜ አስተዋሉ።'),
  ('462ca67b-8c84-5e15-ae50-88f7b4d92ad4', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '3fc7aacc-7afa-5570-a26c-ef507a5c0afa', 1, 13, 'ኢየሱስም ወደ ፊልጶስ ቂሣርያ አገር በደረሰ ጊዜ ደቀ መዛሙርቱን “ሰዎች የሰውን ልጅ ማን እንደ ሆነ ይሉታል?” ብሎ ጠየቀ።'),
  ('23225c35-5174-57cf-a147-485e179e5b3b', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '3fc7aacc-7afa-5570-a26c-ef507a5c0afa', 2, 14, 'እነርሱም “አንዳንዱ መጥምቁ ዮሐንስ፥ ሌሎችም ኤልያስ፥ ሌሎችም ኤርምያስ ወይም ከነቢያት አንዱ ነው፤” ይላሉ አሉት።'),
  ('f035760a-e628-5eb9-aad0-00d9f98a3fac', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '3fc7aacc-7afa-5570-a26c-ef507a5c0afa', 3, 15, 'እርሱም “እናንተስ እኔን ማን እንደ ሆንሁ ትላላችሁ?” አላቸው።'),
  ('08d6d932-85ec-5d39-ab80-a5215a0d3966', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '3fc7aacc-7afa-5570-a26c-ef507a5c0afa', 4, 16, 'ስምዖን ጴጥሮስም መልሶ “አንተ ክርስቶስ የሕያው እግዚአብሔር ልጅ ነህ፤” አለ።'),
  ('022c4c5a-3bd3-5169-a8cb-14b083e8638d', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '3fc7aacc-7afa-5570-a26c-ef507a5c0afa', 5, 17, 'ኢየሱስም መልሶ እንዲህ አለው “የዮና ልጅ ስምዖን ሆይ! በሰማያት ያለው አባቴ እንጂ ሥጋና ደም ይህን አልገለጠልህምና ብፁዕ ነህ።'),
  ('3e493a62-5180-5ef1-a5ac-e087c413feeb', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '3fc7aacc-7afa-5570-a26c-ef507a5c0afa', 6, 18, 'እኔም እልሃለሁ፤ አንተ ጴጥሮስ ነህ፤ በዚችም ዐለት ላይ ቤተ ክርስቲያኔን እሠራለሁ፤ የገሃነም ደጆችም አይችሉአትም።'),
  ('9c9a8145-e010-52ad-ae9e-bcdc0db46c64', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '3fc7aacc-7afa-5570-a26c-ef507a5c0afa', 7, 19, 'የመንግሥተ ሰማያትንም መክፈቻዎች እሰጥሃለሁ፤ በምድር የምታስረው ሁሉ በሰማያት የታሰረ ይሆናል፤ በምድርም የምትፈታው ሁሉ በሰማያት የተፈታ ይሆናል።”'),
  ('0bcecd3c-c84f-57b3-aaa1-e9c668538d8e', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '3fc7aacc-7afa-5570-a26c-ef507a5c0afa', 8, 20, 'ያን ጊዜም እርሱ ክርስቶስ እንደ ሆነ ለማንም እንዳይነግሩ ደቀ መዛሙርቱን አዘዛቸው።'),
  ('a4ad7f1c-e671-546c-a10c-4b673a7be559', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '4c1d8020-d175-5dec-adfa-acbbea180295', 1, 21, 'ከዚያን ቀን ጀምሮ ኢየሱስ ወደ ኢየሩሳሌም ይሄድ ዘንድ ከሽማግሎችና ከካህናት አለቆች ከጻፎችም ብዙ መከራ ይቀበልና ይገደል ዘንድ በሦስተኛውም ቀን ይነሣ ዘንድ እንዲገባው ለደቀ መዛሙርቱ ይገልጥላቸው ጀመር።'),
  ('64f60f20-2bf0-5ac5-ae01-379bda80422c', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '4c1d8020-d175-5dec-adfa-acbbea180295', 2, 22, 'ጴጥሮስም ወደ እርሱ ወስዶ “አይሁንብህ ጌታ ሆይ! ይህ ከቶ አይደርስብህም፤” ብሎ ሊገሥጸው ጀመረ።'),
  ('befdd697-fd9c-5140-ae47-4cca0c9bfb9d', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '4c1d8020-d175-5dec-adfa-acbbea180295', 3, 23, 'እርሱ ግን ዘወር ብሎ ጴጥሮስን “ወደ ኋላዬ ሂድ፤ አንተ ሰይጣን! የሰውን እንጂ የእግዚአብሔርን አታስብምና፥ ዕንቅፋት ሆነህብኛል፤” አለው።'),
  ('fce9ce25-252d-5493-ad2b-22d6a86bd191', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '4c1d8020-d175-5dec-adfa-acbbea180295', 4, 24, 'በዚያን ጊዜ ኢየሱስ ለደቀ መዛሙርቱ እንዲህ አለ “እኔን መከተል የሚወድ ቢኖር፥ ራሱን ይካድ፤ መስቀሉንም ተሸክሞ ይከተለኝ።'),
  ('eb58dedc-b100-5168-a5e8-20f9bb29f587', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '4c1d8020-d175-5dec-adfa-acbbea180295', 5, 25, 'ነፍሱን ሊያድን የሚወድ ሁሉ ያጠፋታል፤ ስለ እኔ ግን ነፍሱን የሚያጠፋ ሁሉ ያገኛታል።'),
  ('a5c77d7f-a199-5f54-a512-77679106d4d0', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '4c1d8020-d175-5dec-adfa-acbbea180295', 6, 26, 'ሰው ዓለሙን ሁሉ ቢያተርፍ ነፍሱንም ቢያጐድል ምን ይጠቅመዋል? ወይስ ሰው ስለ ነፍሱ ቤዛ ምን ይሰጣል?'),
  ('3f1549bb-f766-5894-afc7-caf0813032ea', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '4c1d8020-d175-5dec-adfa-acbbea180295', 7, 27, 'የሰው ልጅ ከመላእክቱ ጋር በአባቱ ክብር ይመጣ ዘንድ አለውና፤ ያን ጊዜም ለሁሉ እንደ ሥራው ያስረክበዋል።'),
  ('7a61b926-3ed9-5b3f-ac0f-3a72b161d79c', '9326056b-c25e-57a1-a4b4-5ba2c2e10f67', '4c1d8020-d175-5dec-adfa-acbbea180295', 8, 28, 'እውነት እላችኋለሁ፥ የሰው ልጅ በመንግሥቱ ሲመጣ እስኪያዩ ድረስ እዚህ ከሚቆሙት ሞትን የማይቀምሱ አንዳንድ አሉ።”'),
  ('93e341ad-ebdb-59cc-ac34-c97de10ca1c0', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 1, 1, 'ከስድስት ቀንም በኋላ ኢየሱስ ጴጥሮስንና ያዕቆብን ወንድሙንም ዮሐንስን ይዞ ወደ ረጅም ተራራ ብቻቸውን አወጣቸው።'),
  ('3f84df6d-243b-51ea-a92e-f39e16891012', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 2, 2, 'በፊታቸውም ተለወጠ፤ ፊቱም እንደ ፀሐይ በራ፤ ልብሱም እንደ ብርሃን ነጭ ሆነ።'),
  ('826eb150-07a5-59e4-ade5-d16ebb3e9e3e', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 3, 3, 'እነሆም፥ ሙሴና ኤልያስ ከእርሱ ጋር ሲነጋገሩ ታዩአቸው።'),
  ('233795d3-7e6a-5931-a89d-68e11516a64f', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 4, 4, 'ጴጥሮስም መልሶ ኢየሱስን፦ “ጌታ ሆይ! በዚህ መሆን ለእኛ መልካም ነው፤ ብትወድስ፥ በዚህ ሦስት ዳስ አንዱን ለአንተ አንዱንም ለሙሴ አንዱንም ለኤልያስ እንሥራ፤” አለ።'),
  ('8860887b-d02c-54b0-a232-e90cb8ee9d93', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 5, 5, 'እርሱም ገና ሲናገር፥ እነሆ፥ ብሩህ ደመና ጋረዳቸው፤ እነሆም፥ ከደመናው “በእርሱ ደስ የሚለኝ የምወደው ልጄ ይህ ነው፤ እርሱን ስሙት፤” የሚል ድምፅ መጣ።'),
  ('e18e5818-85a7-5955-add1-cf8191844489', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 6, 6, 'ደቀ መዛሙርቱም ሰምተው በፊታቸው ወደቁ፤ እጅግም ፈርተው ነበር።'),
  ('40353953-058f-5ffb-a9d3-f7b60e587375', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 7, 7, 'ኢየሱስም ቀርቦ ዳሰሳቸውና “ተነሡ፤ አትፍሩም፤” አላቸው።'),
  ('443319e5-b314-5052-a1be-f01193d16dbb', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 8, 8, 'ዐይናቸውንም አቅንተው ሲያዩ ከኢየሱስ ብቻ በቀር ማንንም አላዩም።'),
  ('8a8ada84-8274-5b12-ade9-c9843e37807a', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 9, 9, 'ከተራራውም በወረዱ ጊዜ ኢየሱስ “የሰው ልጅ ከሙታን እስኪነሣ ድረስ ያያችሁትን ለማንም አትንገሩ፤” ብሎ አዘዛቸው።'),
  ('2e7da467-d844-55e0-a350-23b01e4b88e6', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 10, 10, 'ደቀ መዛሙርቱም “እንግዲህ ጻፎች ‘ኤልያስ አስቀድሞ ሊመጣ ይገባዋል፤’ ስለ ምን ይላሉ?” ብለው ጠየቁት።'),
  ('5c44edfe-f7ca-5b77-a27e-cead34ca65bf', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 11, 11, 'ኢየሱስም መልሶ “ኤልያስማ አስቀድሞ ይመጣል፤ ሁሉንም ያቀናል፤'),
  ('9934bfac-e9bc-51e7-ac21-b48b1df0d1f7', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 12, 12, 'ነገር ግን እላችኋለሁ፥ ኤልያስ ከዚህ በፊት መጣ፤ የወደዱትንም ሁሉ አደረጉበት እንጂ አላወቁትም፤ እንዲሁም ደግሞ የሰው ልጅ ከእነርሱ መከራ ይቀበል ዘንድ አለው፤” አላቸው።'),
  ('bb349b30-dcf5-525a-aee1-98b5b30fd5af', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'a8119462-327c-5cd1-af9b-cbf4cc101c47', 13, 13, 'በዚያን ጊዜ ደቀ መዛሙርቱ ስለ መጥምቁ ስለ ዮሐንስ እንደ ነገራቸው አስተዋሉ።'),
  ('9bed7c85-605f-5138-aa45-479a1bcc8635', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '2d9c92c2-8d5c-529a-aa82-9e72e8c32433', 1, 14, 'ወደ ሕዝቡም ሲደርሱ አንድ ሰው ወደ እርሱ ቀረበና ተንበርክኮ'),
  ('51bc514e-4f78-5ed0-a469-c0f088774d67', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '2d9c92c2-8d5c-529a-aa82-9e72e8c32433', 2, 15, '“ጌታ ሆይ! ልጄን ማርልኝ፥ በጨረቃ እየተነሣበትክፉኛ ይሣቀያልና፤ ብዙ ጊዜ በእሳት ብዙ ጊዜም በውሃ ይወድቃልና።'),
  ('457e28d0-83eb-571b-a525-da73ae75eb12', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '2d9c92c2-8d5c-529a-aa82-9e72e8c32433', 3, 16, 'ወደ ደቀ መዛሙርትህም አመጣሁት ሊፈውሱትም አቃታቸው፤” አለው።'),
  ('3a5ee3e8-30b6-5959-aff9-69d926516e4b', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '2d9c92c2-8d5c-529a-aa82-9e72e8c32433', 4, 17, 'ኢየሱስም መልሶ “የማታምን ጠማማ ትውልድ ሆይ! እስከ መቼ ከእናንተ ጋር እኖራለሁ? እስከ መቼስ እታገሣችኋለሁ? ወደዚህ ወደ እኔ አምጡት፤” አለ።'),
  ('e1a03514-a905-5278-aca2-d10dacb3e61b', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '2d9c92c2-8d5c-529a-aa82-9e72e8c32433', 5, 18, 'ኢየሱስም ገሠጸው፤ ጋኔኑም ከእርሱ ወጣ፤ ብላቴናውም ከዚያች ሰዓት ጀምሮ ተፈወሰ።'),
  ('024b75de-428d-53f1-a51d-0d2a7b886f84', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '2d9c92c2-8d5c-529a-aa82-9e72e8c32433', 6, 19, 'ከዚህ በኋላ ደቀ መዛሙርቱ ብቻቸውን ወደ ኢየሱስ ቀረቡና “እኛ ልናወጣው ያልቻልን ስለ ምን ነው?” አሉት።'),
  ('c5f57320-50f4-548a-a77e-112a64125798', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '2d9c92c2-8d5c-529a-aa82-9e72e8c32433', 7, 20, 'ኢየሱስም “ስለ እምነታችሁ ማነስ ነው፤ እውነት እላችኋለሁ፥ የሰናፍጭ ቅንጣት የሚያህል እምነት ቢኖራችሁ፥ ይህን ተራራ ‘ከዚህ ወደዚያ እለፍ፤’ ብትሉት ያልፋል፤ የሚሳናችሁም ነገር የለም።'),
  ('04d90cc0-1aba-56f0-a20f-350f0352dfe4', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '2d9c92c2-8d5c-529a-aa82-9e72e8c32433', 8, 21, 'ይህ ዐይነት ግን ከጸሎትና ከጦም በቀር አይወጣም፤” አላቸው።'),
  ('d1c3b363-1a88-58db-aff1-0bb916a4bb02', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '0db96e1d-2edd-501a-a4b6-8106126f683e', 1, 22, 'በገሊላም ሲመላለሱ ኢየሱስ “የሰው ልጅ በሰዎች እጅ አልፎ ይሰጥ ዘንድ አለው፤ ይገድሉትማል፤'),
  ('d70de6d5-0a38-5d8a-aaa6-0de87f5bc72f', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', '0db96e1d-2edd-501a-a4b6-8106126f683e', 2, 23, 'በሦስተኛውም ቀን ይነሣል፤” አላቸው። እጅግም አዘኑ።'),
  ('8fd18824-d249-5157-a90f-5a846eaaa7ef', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'ed198e23-8c97-507b-a65c-85d91a081be1', 1, 24, 'ወደ ቅፍርናሆምም በመጡ ጊዜ ግብር የሚቀበሉ ሰዎች ወደ ጴጥሮስ ቀረቡና “መምህራችሁ ሁለቱን ዲናር አይገብርምን?” አሉት።'),
  ('46c2d913-34e6-5979-a126-8974d25621c9', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'ed198e23-8c97-507b-a65c-85d91a081be1', 2, 25, '“አዎን ይገብራል” አለ። ወደ ቤትም በገባ ጊዜ ኢየሱስ አስቀድሞ “ስምዖን ሆይ! ምን ይመስልሃል? የምድር ነገሥታት ቀረጥና ግብር ከማን ይቀበላሉ? ከልጆቻቸው? ወይስ ከእንግዶች?” አለው።'),
  ('00fc9e2a-1b94-5658-adb7-e41ff2a3663f', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'ed198e23-8c97-507b-a65c-85d91a081be1', 3, 26, 'ጴጥሮስም “ከእንግዶች” ባለው ጊዜ ኢየሱስ “እንኪያስ ልጆቻቸው ነጻ ናቸው።'),
  ('b1d49f3c-97c3-5213-a8c6-e5533306179d', '4bfa95a9-f33a-5a52-a642-05ca70f117d7', 'ed198e23-8c97-507b-a65c-85d91a081be1', 4, 27, 'ነገር ግን እንዳናሰናክላቸው፥ ወደ ባሕር ሂድና መቃጥን ጣል፤ መጀመሪያም የሚወጣውን ዓሣ ውሰድና አፉን ስትከፍት እስታቴር ታገኛለህ፤ ያን ወስደህ ስለ እኔና ስለ አንተ ስጣቸው፤” አለው።'),
  ('72e57ddd-da4a-52fa-ac2a-3e76e6e543d5', '780ef5e1-0dc9-54af-a681-ff087692c606', 'cc28664d-bb0b-594e-abeb-d72509c16ca2', 1, 1, 'በዚያች ሰዓት ደቀ መዛሙርቱ ወደ ኢየሱስ ቀርበው “በመንግሥተ ሰማያት ከሁሉ የሚበልጥ ማን ይሆን?” አሉት።'),
  ('ae3e088a-2052-5a78-a655-ab5c0469ecd8', '780ef5e1-0dc9-54af-a681-ff087692c606', 'cc28664d-bb0b-594e-abeb-d72509c16ca2', 2, 2, 'ሕፃንም ጠርቶ በመካከላቸው አቆመ፤'),
  ('0d9f7046-af3b-5193-a6e0-0897c99cc805', '780ef5e1-0dc9-54af-a681-ff087692c606', 'cc28664d-bb0b-594e-abeb-d72509c16ca2', 3, 3, 'እንዲህም አለ “እውነት እላችኋለሁ፥ ካልተመለሳችሁ እንደ ሕፃናትም ካልሆናችሁ፥ ወደ መንግሥተ ሰማያት ከቶ አትገቡም።'),
  ('ae063e55-6f5a-5e35-acb0-3701c8be52d8', '780ef5e1-0dc9-54af-a681-ff087692c606', 'cc28664d-bb0b-594e-abeb-d72509c16ca2', 4, 4, 'እንግዲህ እንደዚህ ሕፃን ራሱን የሚያዋርድ ሁሉ፥ በመንግሥተ ሰማያት የሚበልጥ እርሱ ነው።'),
  ('333c51a5-08e2-5a58-a6de-66ca2273c795', '780ef5e1-0dc9-54af-a681-ff087692c606', 'cc28664d-bb0b-594e-abeb-d72509c16ca2', 5, 5, '“እንደዚህም ያለውን አንድ ሕፃን በስሜ የሚቀበል ሁሉ እኔን ይቀበላል፤'),
  ('8e1542e0-ce5a-500f-a639-48afda6194be', '780ef5e1-0dc9-54af-a681-ff087692c606', 'cc28664d-bb0b-594e-abeb-d72509c16ca2', 6, 6, 'በእኔም ከሚያምኑ ከነዚህ ከታናናሾቹ አንዱን የሚያሰናክል ሁሉ፥ የወፍጮ ድንጋይ በአንገቱ ታስሮ ወደ ጥልቅ ባሕር መስጠም ይሻለው ነበር።'),
  ('c069bf4f-a516-5c17-aa58-df8bc7e5928b', '780ef5e1-0dc9-54af-a681-ff087692c606', '758db8b2-0e40-5c3b-a0ab-17e4347199d5', 1, 7, '“ወዮ ለዓለም ስለ ማሰናከያ፤ ማሰናከያ ሳይመጣ አይቀርምና፤ ነገር ግን በእርሱ ጠንቅ ማሰናከያ ለሚመጣበት ለዚያ ሰው ወዮለት!'),
  ('1b1ce9f1-5ad0-5397-a86f-062cb09ec62f', '780ef5e1-0dc9-54af-a681-ff087692c606', '758db8b2-0e40-5c3b-a0ab-17e4347199d5', 2, 8, 'እጅህ ወይም እግርህ ብታሰናክልህ፥ ቈርጠህ ከአንተ ጣላት፤ ሁለት እጅ ወይም ሁለት እግር ኖሮህ ወደ ዘላለም እሳት ከምትጣል ይልቅ አንካሳ ወይም ጕንድሽ ሆነህ ወደ ሕይወት መግባት ይሻልሀል።'),
  ('69a71c36-dc67-5249-a910-b194edfa90c4', '780ef5e1-0dc9-54af-a681-ff087692c606', '758db8b2-0e40-5c3b-a0ab-17e4347199d5', 3, 9, 'ዐይንህ ብታሰናክልህ አውጥተህ ከአንተ ጣላት፤ ሁለት ዐይን ኖሮህ ወደ ገሃነመ እሳት ከምትጣል ይልቅ አንዲት ዐይን ኖራህ ወደ ሕይወት መግባት ይሻልሃል።'),
  ('2851d970-3951-520e-a4cb-5a80e38e761e', '780ef5e1-0dc9-54af-a681-ff087692c606', '758db8b2-0e40-5c3b-a0ab-17e4347199d5', 4, 10, '“ከነዚህ ከታናናሾቹ አንዱን እንዳትንቁ ተጠንቀቁ፤ መላእክቶቻቸው በሰማያት ዘወትር በሰማያት ያለውን የአባቴን ፊት ያያሉ እላችኋለሁና።'),
  ('0b6b8519-9587-5427-afb8-5081e31076b9', '780ef5e1-0dc9-54af-a681-ff087692c606', '758db8b2-0e40-5c3b-a0ab-17e4347199d5', 5, 11, 'የሰው ልጅ የጠፋውን ለማዳን መጥቶአልና።'),
  ('0063f50e-3e9d-5a27-ad6f-391358144700', '780ef5e1-0dc9-54af-a681-ff087692c606', 'bde980e0-fedb-5087-abca-f5a055aba717', 1, 12, '“ምን ይመስላችኋል? ለአንድ ሰው መቶ በጎች ቢኖሩት ከእነርሱም አንዱ ቢባዝን፥ ዘጠና ዘጠኙን በተራራ ትቶ ሄዶም የባዘነውን አይፈልግምን?'),
  ('93016807-cada-564c-ac15-b2d4b1fcfdb0', '780ef5e1-0dc9-54af-a681-ff087692c606', 'bde980e0-fedb-5087-abca-f5a055aba717', 2, 13, 'ቢያገኘውም፥ እውነት እላችኋለሁ፥ ካልባዘኑቱ ከዘጠና ዘጠኙ ይልቅ በእርሱ ደስ ይለዋል።'),
  ('a3e22342-364a-5e01-ae44-dc5927ef5e63', '780ef5e1-0dc9-54af-a681-ff087692c606', 'bde980e0-fedb-5087-abca-f5a055aba717', 3, 14, 'እንደዚሁ ከእነዚህ ከታናናሾቹ አንዱ እንዲጠፋ በሰማያት ያለው አባታችሁ ፈቃድ አይደለም።'),
  ('7afc840b-2728-56eb-a80c-41bb487f4603', '780ef5e1-0dc9-54af-a681-ff087692c606', '16a20062-06f0-53b9-a37c-dcc9fbc16b3f', 1, 15, '“ወንድምህም ቢበድልህ፥ ሄደህ አንተና እርሱ ብቻችሁን ሆናችሁ ውቀሰው። ቢሰማህ፥ ወንድምህን ገንዘብ አደረግኸው፤'),
  ('bb7dd0f7-5df4-57c5-a7dc-4029d2e38715', '780ef5e1-0dc9-54af-a681-ff087692c606', '16a20062-06f0-53b9-a37c-dcc9fbc16b3f', 2, 16, 'ባይሰማህ ግን፥ በሁለት ወይም በሦስት ምስክር አፍ ነገር ሁሉ እንዲጸና፥ ዳግመኛ አንድ ወይም ሁለት ከአንተ ጋር ውሰድ፤'),
  ('ed4b9d26-7db3-58ec-a0f0-dab576e50136', '780ef5e1-0dc9-54af-a681-ff087692c606', '16a20062-06f0-53b9-a37c-dcc9fbc16b3f', 3, 17, 'እነርሱንም ባይሰማ፥ ለቤተ ክርስቲያን ንገራት፤ ደግሞም ቤተ ክርስቲያንን ባይሰማት፥ እንደ አረመኔና እንደ ቀራጭ ይሁንልህ።'),
  ('a6caf311-c839-599a-ab2e-a793f97f82f0', '780ef5e1-0dc9-54af-a681-ff087692c606', '16a20062-06f0-53b9-a37c-dcc9fbc16b3f', 4, 18, 'እውነት እላችኋለሁ፥ በምድር የምታስሩት ሁሉ በሰማይ የታሰረ ይሆናል፤ በምድርም የምትፈቱት ሁሉ በሰማይ የተፈታ ይሆናል።'),
  ('09374030-b86a-5201-a381-07a363156afb', '780ef5e1-0dc9-54af-a681-ff087692c606', '16a20062-06f0-53b9-a37c-dcc9fbc16b3f', 5, 19, 'ደግሞ እላችኋለሁ፥ ከእናንተ ሁለቱ በምድር በማናቸውም በሚለምኑት ነገር ሁሉ ቢስማሙ፥ በሰማያት ካለው ከአባቴ ዘንድ ይደረግላቸዋል።'),
  ('490f064f-fee8-56ce-a9ea-ad8e015de735', '780ef5e1-0dc9-54af-a681-ff087692c606', '16a20062-06f0-53b9-a37c-dcc9fbc16b3f', 6, 20, 'ሁለት ወይም ሦስት በስሜ በሚሰበሰቡበት በዚያ በመካከላቸው እሆናለሁና።”'),
  ('86dac3a3-5c75-524e-a985-a95ab03eaf0d', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 1, 21, 'በዚያን ጊዜ ጴጥሮስ ወደ እርሱ ቀርቦ “ጌታ ሆይ! ወንድሜ ቢበድለኝ ስንት ጊዜ ልተውለት? እስከ ሰባት ጊዜን?” አለው።'),
  ('160fc6a0-86f4-5650-abfa-8b58056e8284', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 2, 22, 'ኢየሱስ እንዲህ አለው “እስከ ሰባ ጊዜ ሰባት እንጂ እስከ ሰባት ጊዜ አልልህም።'),
  ('09f04a51-e0fb-5960-ace7-4f110eb70a37', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 3, 23, '“ስለዚህ መንግሥተ ሰማያት ባሮቹን ሊቈጣጠር የወደደን ንጉሥ ትመስላለች።'),
  ('bc7dd4f8-279f-54fd-a83e-20fd6d75bc70', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 4, 24, 'መቈጣጠርም በጀመረ ጊዜ፥ እልፍ መክሊት ዕዳ ያለበትን አንድ ሰው ወደ እርሱ አመጡ።'),
  ('a265662f-6f28-59a1-ad54-72ad552d53cb', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 5, 25, 'የሚከፍለውም ቢያጣ፥ እርሱና ሚስቱ ልጆቹም ያለውም ሁሉ እንዲሸጥና ዕዳው እንዲከፈል ጌታው አዘዘ።'),
  ('d113f035-905a-5dff-aed8-f05401c930f7', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 6, 26, 'ስለዚህ ባሪያው ወድቆ ሰገደለትና ‘ጌታ ሆይ! ታገሠኝ፤ ሁሉንም እከፍልሃለሁ፤’ አለው።'),
  ('8ef4e644-4c4c-5aff-ae47-8111de9005b9', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 7, 27, 'የዚያም ባሪያ ጌታ አዘነለትና ለቀቀው፤ ዕዳውንም ተወለት።'),
  ('44926987-915f-5e93-a615-3c75d488539b', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 8, 28, 'ነገር ግን ያ ባሪያ ወጥቶ ከባልንጀሮቹ ከባሮቹ መቶ ዲናር ዕዳ ያለበትን አንዱን አገኘና ‘ዕዳህን ክፈለኝ’ ብሎ ያዘና አነቀው።'),
  ('f896409e-901d-553c-a3e4-c64d1027c284', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 9, 29, 'ስለዚህ ባልንጀራው ባሪያ ወድቆ ‘ታገሠኝ፤ ሁሉንም እከፍልሃለሁ፤’ ብሎ ለመነው።'),
  ('582af8e6-d164-5cb9-af64-2585ac461b01', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 10, 30, 'እርሱም አልወደደም፤ ግን ሄዶ ዕዳውን እስኪከፍል ድረስ በወኅኒ አኖረው።'),
  ('be3b6b3a-4f82-5dd3-afc8-5924903588e8', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 11, 31, 'ባልንጀሮቹ የሆኑ ባሮችም ያደረገውን አይተው እጅግ አዘኑ፤ መጥተውም የሆነውን ሁሉ ለጌታቸው ገለጡ።'),
  ('f4bed5d6-cd12-548e-ae93-5c506af1aa73', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 12, 32, 'ከዚያ ወዲያ ጌታው ጠርቶ ‘አንተ ክፉ ባሪያ፥ ስለ ለመንኸኝ ያን ዕዳ ሁሉ ተውሁልህ፤'),
  ('3cdad7c1-55b6-5d40-a9f2-9ba53c4f3b3a', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 13, 33, 'እኔ እንደ ማርሁህ ባልንጀራህ የሆነውን ያን ባሪያ ልትምረው ለአንተስ አይገባህምን?’ አለው።'),
  ('98f41f9a-a114-517d-a945-425b934fd13d', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 14, 34, 'ጌታውም ተቈጣና ዕዳውን ሁሉ እስኪከፍለው ድረስ ለሚሣቅዩት አሳልፎ ሰጠው።'),
  ('62f3b195-6c63-58aa-a5a1-874487ed4d3a', '780ef5e1-0dc9-54af-a681-ff087692c606', '403347c3-5b6f-5708-a08f-2d8afc6a93fd', 15, 35, 'ከእናንተ እያንዳንዱ ወንድሙን ከልቡ ይቅር ካላለ፥ እንዲሁ ደግሞ የሰማዩ አባቴ ያደርግባችኋል።”'),
  ('4d640124-f3ea-5300-ac51-1c1bae7dfd46', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 1, 1, 'ኢየሱስም ይህን ነገር ከፈጸመ በኋላ፥ ከገሊላ ሄዶ ወደ ይሁዳ አውራጃ ወደ ዮርዳኖስ ማዶ መጣ።'),
  ('25b033a0-51fd-5471-aab9-b438d5e59368', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 2, 2, 'ብዙ ሕዝብም ተከተሉት፤ በዚያም ፈወሳቸው።'),
  ('74f3b22f-cea4-5384-ae8e-4a513a5c70b4', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 3, 3, 'ፈሪሳውያንም ወደ እርሱ ቀረቡና ሲፈትኑት “ሰው በሆነው ምክንያት ሁሉ ሚስቱን ሊፈታ ተፈቅዶለታልን?” አሉት።'),
  ('9fba41bb-cfe3-54e3-a213-3baf60afd029', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 4, 4, 'እርሱ ግን መልሶ እንዲህ አለ “ፈጣሪ በመጀመሪያ ወንድና ሴት አደረጋቸው፤'),
  ('41c1a540-c95c-5178-adca-c04734b307db', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 5, 5, 'አለም ‘ስለዚህ ሰው አባቱንና እናቱን ይተዋል፤ ከሚስቱም ጋር ይተባበራል፤ ሁለቱም አንድ ሥጋ ይሆናሉ፤’ የሚለውን ቃል አላነበባችሁምን?'),
  ('637f919f-c3d8-5249-a9fd-1205a0bb93b3', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 6, 6, 'ስለዚህ አንድ ሥጋ ናቸው እንጂ ወደ ፊት ሁለት አይደሉም። እግዚአብሔር ያጣመረውን እንግዲህ ሰው አይለየው።”'),
  ('86ee00e8-66f2-5f11-a11f-4ef5b35e3119', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 7, 7, 'እነርሱም “እንኪያስ ሙሴ የፍችዋን ጽሕፈት ሰጥተው እንዲፈቱአት ስለ ምን አዘዘ?” አሉት።'),
  ('b9785d46-426b-5ce6-a65c-659ed1efadcd', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 8, 8, 'እርሱም “ሙሴስ ስለ ልባችሁ ጥንካሬ ሚስቶቻችሁን ትፈቱ ዘንድ ፈቀደላችሁ፤ ከጥንት ግን እንዲህ አልነበረም።'),
  ('9e0ab063-4e5a-5b73-a765-3b335219c670', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 9, 9, 'እኔ ግን እላችኋለሁ፤ ያለ ዝሙት ምክንያት ሚስቱን ፈትቶ ሌላዪቱን የሚያገባ ሁሉ ያመነዝራል፤ የተፈታችውንም የሚያገባ ያመነዝራል፤” አላቸው።'),
  ('09f4d9af-931e-5305-a682-0d1e54fe4fca', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 10, 10, 'ደቀ መዛሙርቱም “የባልና የሚስት ሥርዐት እንዲህ ከሆነ መጋባት አይጠቅምም፤” አሉት።'),
  ('b443083e-3a7a-5781-a747-90d8b6fcfc38', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 11, 11, 'እርሱ ግን “ይህ ነገር ለተሰጣቸው ነው እንጂ ለሁሉ አይደለም፤'),
  ('77a6b12e-c975-546b-addb-11cd499854e6', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', 'c4166ceb-c921-5c56-afd7-6edd8f93100e', 12, 12, 'በእናት ማኅፀን ጃንደረቦች ሆነው የተወለዱ አሉ፤ ሰውም የሰለባቸው ጃንደረቦች አሉ፤ ስለ መንግሥተ ሰማያትም ራሳቸውን የሰለቡ ጃንደረቦች አሉ። ሊቀበለው የሚችል ይቀበለው አላቸው።”'),
  ('ed30ff30-cec7-5a34-a7eb-6ca9ed2fd1ec', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '747c6edc-de17-5f64-a769-03b26f51e6fb', 1, 13, 'በዚያን ጊዜ እጁን እንዲጭንባቸውና እንዲጸልይ ሕፃናትን ወደ እርሱ አመጡ፤ ደቀ መዛሙርቱም ገሠጹአቸው።'),
  ('fc2f9dd5-9150-5b3a-a283-9ab6526bdba7', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '747c6edc-de17-5f64-a769-03b26f51e6fb', 2, 14, 'ነገር ግን ኢየሱስ “ሕፃናትን ተዉአቸው፤ ወደ እኔም ይመጡ ዘንድ አትከልክሉአቸው፤ መንግሥተ ሰማያት እንደነዚህ ላሉ ናትና” አለ፤'),
  ('543fdfbf-089c-5def-a2fe-4eaf6184dcc1', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '747c6edc-de17-5f64-a769-03b26f51e6fb', 3, 15, 'እጁንም ጫነባቸውና ከዚያ ሄደ።'),
  ('6fb12a47-c5ee-5bce-a765-03c30bd396fe', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 1, 16, 'እነሆም፥ አንድ ሰው ቀርቦ “መምህር ሆይ! የዘላለምን ሕይወት እንዳገኝ ምን መልካም ነገር ላድርግ” አለው።'),
  ('c0db53d1-1b02-5240-ad4b-4ba4ef1b1512', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 2, 17, 'እርሱም “ስለ መልካም ነገር ለምን ትጠይቀኛለህ? መልካም የሆነ አንድ ነው፤ ወደ ሕይወት መግባት ብትወድ ግን ትእዛዛትን ጠብቅ፤” አለው።'),
  ('c5e51c80-59b0-5488-ae46-aa1331c8258d', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 3, 18, 'እርሱም “የትኞችን?” አለው። ኢየሱስም “አትግደል፥ አታመንዝር፥ አትስረቅ፥ በሐሰት አትመስክር፥'),
  ('f4235f43-69e3-52d6-a2ce-ed286c861dae', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 4, 19, 'አባትህንና እናትህንአክብር፥ ባልንጀራህንም እንደ ራስህ ውደድ አለው።”'),
  ('4dba45c9-8cae-5eb9-a277-1145e9f25a12', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 5, 20, 'ጐበዙም “ይህንማ ሁሉ ከሕፃንነቴ ጀምሬ ጠብቄአለሁ፤ ደግሞስ የሚጐድለኝ ምንድር ነው?” አለው።'),
  ('877b0842-c0f0-5d33-ad99-1fdccd419e8a', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 6, 21, 'ኢየሱስም “ፍጹም ልትሆን ብትወድ፥ ሂድና ያለህን ሸጠህ ለድሆች ስጥ፤ መዝገብም በሰማያት ታገኛለህ፤ መጥተህም ተከተለኝ፤” አለው።'),
  ('af724833-351f-5b06-adb5-5e1884a29c51', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 7, 22, 'ጐበዙም ይህን ቃል በሰማ ጊዜ ብዙ ንብረት ነበረውና እያዘነ ሄደ።'),
  ('8a1869b8-3d37-5cff-a602-96fc707a3a2a', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 8, 23, 'ኢየሱስም ለደቀ መዛሙርቱ “እውነት እላችኋለሁ፥ ለባለጠጋ ወደ መንግሥተ ሰማያት መግባት ጭንቅ ነው።'),
  ('d54500db-6613-5ad6-a691-4e690d96db57', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 9, 24, 'ዳግመኛም እላችኋለሁ፤ ባለጠጋ ወደ እግዚአብሔር መንግሥት ከሚገባ ግመል በመርፌ ቀዳዳ ቢገባ ይቀላል፤” አለ።'),
  ('f2763ad9-0698-5821-a686-41afaa099a7b', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 10, 25, 'ደቀ መዛሙርቱም ሰምተው እጅግ ተገረሙና “እንኪያስ ማን ሊድን ይችላል?” አሉ።'),
  ('cd48c186-15d7-5e16-ac7d-a1486b753225', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 11, 26, 'ኢየሱስም እነርሱን ተመልክቶ “ይህ በሰው ዘንድ አይቻልም፤ በእግዚአብሔር ዘንድ ግን ሁሉ ይቻላል፤” አላቸው።'),
  ('0992e691-9d8d-5b88-a1ff-212879b7f428', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 12, 27, 'በዚያን ጊዜ ጴጥሮስ መልሶ “እነሆ፥ እኛ ሁሉን ትተን ተከተልንህ፤ እንኪያስ ምን እናገኝ ይሆን?” አለው።'),
  ('483c6d9a-9edc-5b8d-afee-a51ebe4e7ddd', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 13, 28, 'ኢየሱስም እንዲህ አላቸው “እውነት እላችኋለሁ፤ እናንተስ የተከተላችሁኝ፥ በዳግመኛ ልደት የሰው ልጅ በክብሩ ዙፋን በሚቀመጥበት ጊዜ፥ እናንተ ደግሞ በዐሥራ ሁለቱ የእስራኤል ነገድ ስትፈርዱ በዐሥራ ሁለት ዙፋን ትቀመጣላችሁ።'),
  ('11ffb64d-4118-5c73-a588-7025ae88bf40', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 14, 29, 'ስለ ስሜም ቤቶችን ወይም ወንድሞችን ወይም እኅቶችን ወይም አባትን ወይም እናትን ወይም ሚስትን ወይም ልጆችን ወይም እርሻን የተወ ሁሉ መቶ እጥፍ ይቀበላል፤ የዘላለምንም ሕይወት ይወርሳል።'),
  ('aa7e0d07-fe77-5180-a70c-e33b45e72588', 'a73907aa-b6a6-5d11-a359-50503d9d14ed', '73b2a738-2ad2-596e-abe9-c01992e258e8', 15, 30, 'ነገር ግን ብዙዎቹ ፊተኞች ኋለኞች፥ ኋለኞችም ፊተኞች ይሆናሉ።'),
  ('e27db5a0-cfea-5ea2-a8e7-f3f68bfef9c3', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 1, 1, '“መንግሥተ ሰማያት ለወይኑ አትክልት ሠራተኞችን ሊቀጥር ማልዶ የወጣ ባለቤት ሰውን ትመስላለችና።'),
  ('eb458d26-a125-51f8-a3a8-fe91ea34f075', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 2, 2, 'ሠራተኞችንም በቀን አንድ ዲናር ተስማምቶ ወደ ወይኑ አትክልት ሰደዳቸው።'),
  ('3bc79b1f-827e-5915-a8a0-2a27c9d80ca0', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 3, 3, 'በሦስት ሰዓትም ወጥቶ ሥራ የፈቱ ሌሎችን በአደባባይ ቆመው አየ፤'),
  ('a757bdb0-521a-5d8e-a9c4-8622ff462ec5', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 4, 4, 'እነዚያንም ‘እናንተ ደግሞ ወደ ወይኔ አትክልት ሂዱ፤ የሚገባውንም እሰጣችኋለሁ፤’ አላቸው። እነርሱም ሄዱ።'),
  ('a8477357-edca-5839-a4cf-95be02c671a5', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 5, 5, 'ደግሞም በስድስትና በዘጠኝ ሰዓት ወጥቶ እንዲሁ አደረገ።'),
  ('20ac3b22-bc06-5ec5-a148-d2e29a8cbf67', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 6, 6, 'በአሥራ አንደኛውም ሰዓት ወጥቶ ሌሎችን ቆመው አገኘና ‘ሥራ ፈትታችሁ ቀኑን ሁሉ በዚህ ስለ ምን ትቆማላችሁ?’ አላቸው።'),
  ('a442ace5-8927-57ce-a80f-2115f6760c8a', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 7, 7, '‘የሚቀጥረን ስለ አጣን ነው፤’ አሉት። እርሱም ‘እናንተ ደግሞ ወደ ወይኔ አትክልት ሂዱ የሚገባውንም ትቀበላላችሁ፤’ አላቸው።'),
  ('c835387f-cfa3-5c20-ad14-c27fe9cad2aa', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 8, 8, 'በመሸም ጊዜ የወይኑ አትክልት ጌታ አዛዡን ‘ሠራተኞችን ጥራና ከኋለኞች ጀምረህ እስከ ፊተኞች ድረስ ደመወዝ ስጣቸው፤’ አለው።'),
  ('1daa934c-7373-55d0-ac2e-d529edb0d5fa', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 9, 9, 'በአሥራ አንደኛው ሰዓትም የገቡ መጥተው እያንዳንዳቸው አንድ ዲናር ተቀበሉ።'),
  ('b4c5530e-c3f7-52f9-a9b2-5c722795aba1', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 10, 10, 'ፊተኞችም በመጡ ጊዜ አብዝተው የሚቀበሉ መስሎአቸው ነበር፤ እነርሱም ደግሞ እያንዳንዳቸው አንድ ዲናር ተቀበሉ።'),
  ('5b649256-1b8c-5570-ae64-f9b94be5303a', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 11, 11, 'ተቀብለውም ‘እነዚህ ኋለኞች አንድ ሰዓት ሠሩ፤ የቀኑንም ድካምና ትኩሳት ከተሸከምን ከእኛ ጋር አስተካከልሃቸው፤’ ብለው በባለቤቱ ላይ አንጕኦራጕኦሩ።'),
  ('ac1df5c0-41ce-5a87-aef5-a3cc48fc0126', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 12, 13, 'እርሱ ግን መልሶ ከእነርሱ ለአንዱ እንዲህ አለው ‘ወዳጄ ሆይ! አልበደልሁህም በአንድ ዲናር አልተስማማኸኝምን?'),
  ('1398e75c-7963-5327-a0f5-bf3152e25826', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 13, 14, 'ድርሻህን ውሰድና ሂድ፤ እኔ ለዚህ ለኋለኛው እንደ አንተ ልሰጠው እወዳለሁ፤ በገንዘቤ የወደድሁትን አደርግ ዘንድ መብት የለኝምን?'),
  ('fae7e59f-4ce7-5167-aeb3-0311df2f0ed6', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 14, 15, 'ወይስ እኔ መልካም ስለ ሆንሁ ዐይንህ ምቀኛ ናትን?'),
  ('bdfde324-84b3-54e8-acee-a26d7c95d780', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'fd4000f2-cc2f-5912-a434-7648b49e1e70', 15, 16, 'እንዲሁ ኋለኞች ፊተኞች፥ ፊተኞችም ኋለኞች ይሆናሉ፤ የተጠሩ ብዙዎች፥ የተመረጡ ግን ጥቂቶች ናቸውና።’ ”'),
  ('dd31603d-7617-5829-a565-3983e6a29215', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'ffbed33b-6957-5a0b-acdd-8f4551fbed8b', 1, 17, 'ኢየሱስም ወደ ኢየሩሳሌም ሊወጣ ሳለ፥ በመንገድ ዐሥራ ሁለቱን ደቀ መዛሙርት ብቻቸውን ወደ እርሱ አቅርቦ'),
  ('7b058700-4242-5c5c-a81a-bf4836458892', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'ffbed33b-6957-5a0b-acdd-8f4551fbed8b', 2, 18, '“እነሆ፥ ወደ ኢየሩሳሌም እንወጣለን፤ የሰው ልጅም ለካህናት አለቆችና ለጻፎች ይሰጣል፤ የሞት ፍርድም ይፈርዱበታል፤'),
  ('2fb4f76f-ca24-51fc-a8b7-bb32857b0c27', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'ffbed33b-6957-5a0b-acdd-8f4551fbed8b', 3, 19, 'ሊዘባበቱበትም ሊገርፉትም ሊሰቅሉትም ለአሕዛብ አሳልፈው ይሰጡታል፤ በሦስተኛውም ቀን ይነሣል፤” አላቸው።'),
  ('81d3ea76-fc62-53bd-a812-e205ffa9c1eb', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', '4b3c940e-5412-55fa-a311-e025bdb9d671', 1, 20, 'በዚያን ጊዜ የዘብዴዎስ ልጆች እናት ከልጆችዋ ጋር እየሰገደችና አንድ ነገር እየለመነች ወደ እርሱ ቀረበች።'),
  ('7bf992ad-2e21-5e38-ade5-c0ab4cb945d8', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', '4b3c940e-5412-55fa-a311-e025bdb9d671', 2, 21, 'እርሱም “ምን ትፈልጊያለሽ?” አላት። እርስዋም “እነዚህ ሁለቱ ልጆቼ አንዱ በቀኝህ አንዱም በግራህ በመንግሥትህ እንዲቀመጡ እዘዝ፤” አለችው።'),
  ('42250831-de90-5fee-a02b-74ccd91c08b9', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', '4b3c940e-5412-55fa-a311-e025bdb9d671', 3, 22, 'ኢየሱስ ግን መልሶ “የምትለምኑትን አታውቁም። እኔ ልጠጣው ያለውን ጽዋ ልትጠጡ እኔም የምጠመቀውን ጥምቀት ልትጠመቁ ትችላላችሁን?” አለ። “እንችላለን” አሉት።'),
  ('bbe68b9d-a127-53b5-ad48-1c3991ba16de', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', '4b3c940e-5412-55fa-a311-e025bdb9d671', 4, 23, 'እርሱም “ጽዋዬንስ ትጠጣላችሁ፤ በቀኝና በግራ መቀመጥ ግን ከአባቴ ዘንድ ለተዘጋጀላቸው ነው እንጂ እኔ የምሰጥ አይደለሁም፤” አላቸው።'),
  ('0d208040-e084-5983-aa1f-5c3986d69c59', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', '4b3c940e-5412-55fa-a311-e025bdb9d671', 5, 24, 'ዐሥሩም ሰምተው በሁለቱ ወንድማማች ተቍኦጡ።'),
  ('2d83ede2-985e-528b-ac11-2bb8bd14065a', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', '4b3c940e-5412-55fa-a311-e025bdb9d671', 6, 25, 'ኢየሱስ ግን ወደ እርሱ ጠርቶ እንዲህ አላቸው “የአሕዛብ አለቆች እንዲገዙአቸው ታላላቆቹም በላያቸው እንዲሠለጥኑ ታውቃላችሁ።'),
  ('7be6b1d5-f9b9-5dac-a959-fd51adbbcfe7', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', '4b3c940e-5412-55fa-a311-e025bdb9d671', 7, 26, 'በእናንተስ እንዲህ አይደለም፤ ነገር ግን ማንም ከእናንተ ታላቅ ሊሆን የሚወድ የእናንተ አገልጋይ ይሁን፤'),
  ('7bdf515a-c8b0-5677-ab3e-0f8ebbef2f2c', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', '4b3c940e-5412-55fa-a311-e025bdb9d671', 8, 27, 'ከእናንተም ማንም ፊተኛ ሊሆን የሚወድ የእናንተ ባሪያ ይሁን፤'),
  ('9f314c6f-acb6-5d57-a1ed-95599097d3c9', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', '4b3c940e-5412-55fa-a311-e025bdb9d671', 9, 28, 'እንዲሁም የሰው ልጅ ሊያገለግል ነፍሱንም ለብዙዎች ቤዛ ሊሰጥ እንጂ እንዲያገለግሉት አልመጣም።”'),
  ('da599e3e-6a62-57b5-a9e6-8a6053a094e9', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'be336c0f-b557-5e9b-a431-77f39a35a42f', 1, 29, 'ከኢያሪኮም ሲወጡ ብዙ ሕዝብ ተከተሉት።'),
  ('c7da0e5c-b09b-5edc-a8d1-7d3389105016', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'be336c0f-b557-5e9b-a431-77f39a35a42f', 2, 30, 'እነሆም፥ ሁለት ዕውሮች በመንገድ ዳር ተቀምጠው፥ ኢየሱስ እንዲያልፍ በሰሙ ጊዜ “ጌታ ሆይ! የዳዊት ልጅ፥ ማረን” ብለው ጮኹ።'),
  ('6cfbac73-eecd-5e3d-a6b5-d4ca4225d91c', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'be336c0f-b557-5e9b-a431-77f39a35a42f', 3, 31, 'ሕዝቡም ዝም እንዲሉ ገሠጹአቸው፤ እነርሱ ግን “ጌታ ሆይ! የዳዊት ልጅ፥ ማረን” እያሉ አብዝተው ጮኹ።'),
  ('15bea426-15f6-5f27-a8c6-4b4a010d0ab1', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'be336c0f-b557-5e9b-a431-77f39a35a42f', 4, 32, 'ኢየሱስም ቆሞ ጠራቸውና “ምን ላደርግላችሁ ትወዳላችሁ?” አለ።'),
  ('e1bd5da2-bd44-5f57-ac08-2fcfe53d7a81', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'be336c0f-b557-5e9b-a431-77f39a35a42f', 5, 33, '“ጌታ ሆይ! ዐይኖቻችን ይከፈቱ ዘንድ” አሉት።'),
  ('de4b2913-b6e0-5674-af83-eec2b5d4ab56', '60d27f0e-59cb-5438-a1a7-4ba85cb6e0e2', 'be336c0f-b557-5e9b-a431-77f39a35a42f', 6, 34, 'ኢየሱስም አዘነላቸውና ዐይኖቻቸውን ዳሰሰ፤ ወዲያውም አዩና ተከተሉት።'),
  ('e0b4ccef-a4ef-5e07-a330-800dd8c51160', '27994085-b9ec-508c-a57e-40c5e780d00c', '51827584-85e0-5f33-abc7-ac3e76bb23e1', 1, 1, 'ወደ ኢየሩሳሌምም ቀርበው ወደ ደብረዘይት ወደ ቤተ ፋጌ ሲደርሱ፥ ያን ጊዜ ኢየሱስ ከደቀ መዛሙርቱ ሁለት ላከ፤'),
  ('f9405601-e5b7-5cb9-a225-a89189433c29', '27994085-b9ec-508c-a57e-40c5e780d00c', '51827584-85e0-5f33-abc7-ac3e76bb23e1', 2, 2, 'እንዲህም አላቸው “በፊታችሁ ወዳለችው መንደር ሂዱ፤ በዚያን ጊዜም የታሰረችን አህያ ውርንጫም ከእርስዋ ጋር ታገኛላችሁ፤ ፈትታችሁ አምጡልኝ።'),
  ('fea7cdc5-1809-52fb-a034-86b8d3dcdde4', '27994085-b9ec-508c-a57e-40c5e780d00c', '51827584-85e0-5f33-abc7-ac3e76bb23e1', 3, 3, 'ማንም አንዳች ቢላችሁ ‘ለጌታ ያስፈልጉታል፤’ በሉ፤ ወዲያውም ይሰዳቸዋል።”'),
  ('73880f04-23d0-5e89-a0d5-c046d17cc1c7', '27994085-b9ec-508c-a57e-40c5e780d00c', '51827584-85e0-5f33-abc7-ac3e76bb23e1', 4, 4, '“ለጽዮን ልጅ'),
  ('275acfb3-2291-50f5-a7ca-7bb6f28c5c9a', '27994085-b9ec-508c-a57e-40c5e780d00c', 'f1a88f58-7ab0-58f6-a057-33d49d465520', 1, 12, 'ኢየሱስም ወደ መቅደስ ገባና በመቅደስ የሚሸጡትንና የሚገዙትን ሁሉ አስወጣ፤ የገንዘብ ለዋጮችንም ገበታዎች የርግብ ሻጮችንም ወንበሮች ገለበጠና'),
  ('51229947-ffe2-50c9-a680-2fd50efdf5f0', '27994085-b9ec-508c-a57e-40c5e780d00c', 'f1a88f58-7ab0-58f6-a057-33d49d465520', 2, 13, '“ ‘ቤቴ የጸሎት ቤት ትባላለች፤’ ተብሎ ተጽፎአል፤ እናንተ ግን የወንበዶች ዋሻ አደረጋችኋት፤” አላቸው።'),
  ('197f06c7-e57d-51f1-af57-6aeb5dd37f4b', '27994085-b9ec-508c-a57e-40c5e780d00c', 'f1a88f58-7ab0-58f6-a057-33d49d465520', 3, 14, 'በመቅደስም ዕውሮችና አንካሶች ወደ እርሱ ቀረቡና ፈወሳቸው።'),
  ('c24e87cc-bffa-544f-a8f7-bcc83df38b66', '27994085-b9ec-508c-a57e-40c5e780d00c', 'f1a88f58-7ab0-58f6-a057-33d49d465520', 4, 15, 'ነገር ግን የካህናት አለቆችና ጻፎች ያደረገውን ድንቃ ድንቅ በመቅደስም “ሆሣዕና ለዳዊት ልጅ!” እያሉ የሚጮኹትን ልጆች ባዩ ጊዜ፥ ተቈጥተው'),
  ('04083a07-1322-55ef-a4c1-687634e9ef18', '27994085-b9ec-508c-a57e-40c5e780d00c', 'f1a88f58-7ab0-58f6-a057-33d49d465520', 5, 16, '“እነዚህ የሚሉትን አትሰማምን?” አሉት። ኢየሱስም “እሰማለሁ፤ ‘ከሕፃናትና ከሚጠቡት አፍ ምስጋናን ለራስህ አዘጋጀህ፤’ የሚለውን ቃል ከቶ አላነበባችሁምን?” አላቸው።'),
  ('13565dd6-122c-54f5-a348-be3cff7f788b', '27994085-b9ec-508c-a57e-40c5e780d00c', 'f1a88f58-7ab0-58f6-a057-33d49d465520', 6, 17, 'ትቶአቸውም ከከተማ ወደ ቢታንያ ወጣ፤ በዚያም አደረ።'),
  ('83ab922e-0295-592d-af81-148b855d5ac6', '27994085-b9ec-508c-a57e-40c5e780d00c', 'dfc862f5-ebb9-50a3-aca7-6a2008e276e3', 1, 18, 'በማለዳም ወደ ከተማ ሲመለስ ተራበ።'),
  ('aae668aa-0072-5de8-a8d2-2f335f016096', '27994085-b9ec-508c-a57e-40c5e780d00c', 'dfc862f5-ebb9-50a3-aca7-6a2008e276e3', 2, 19, 'በመንገድም አጠገብ በለስ አይቶ ወደ እርስዋ መጣ፤ ከቅጠልም ብቻ በቀር ምንም አላገኘባትምና “ለዘላለሙ ፍሬ አይገኝብሽ፤” አላት። በለሲቱም ያንጊዜውን ደረቀች።'),
  ('87666c8b-0ee7-5475-a813-ee9616f8b511', '27994085-b9ec-508c-a57e-40c5e780d00c', 'dfc862f5-ebb9-50a3-aca7-6a2008e276e3', 3, 20, 'ደቀ መዛሙርቱም ይህን አይተው “በለሲቱ ያንጊዜውን እንዴት ደረቀች?” ብለው ተደነቁ።'),
  ('324b1731-8183-599c-ac2d-88c130d165c3', '27994085-b9ec-508c-a57e-40c5e780d00c', 'dfc862f5-ebb9-50a3-aca7-6a2008e276e3', 4, 21, 'ኢየሱስም መልሶ “እውነት እላችኋለሁ፤ እምነት ቢኖራችሁ ባትጠራጠሩም፥ በበለሲቱ እንደ ሆነባት ብቻ አታደርጉም፤ ነገር ግን ይህን ተራራ እንኳ ‘ተነቅለህ ወደ ባሕር ተወርወር፤’ ብትሉት ይሆናል፤'),
  ('ce99e26e-13da-5fea-a3ee-7d62b21edcf1', '27994085-b9ec-508c-a57e-40c5e780d00c', 'dfc862f5-ebb9-50a3-aca7-6a2008e276e3', 5, 22, 'አምናችሁም በጸሎት የምትለምኑትን ሁሉ ትቀበላላችሁ፤” አላቸው።'),
  ('ac59dbfa-9311-5325-a67a-e5a6c810ab79', '27994085-b9ec-508c-a57e-40c5e780d00c', '4bf60c92-6eca-5089-acd5-d0f621736c62', 1, 23, 'ወደ መቅደስም ገብቶ ሲያስተምር የካህናት አለቆችና የሕዝብ ሽማግሎች ወደ እርሱ ቀረቡና “በምን ሥልጣን እነዚህን ታደርጋለህ? ይህንስ ሥልጣን ማን ሰጠህ?” አሉት።'),
  ('57a16a18-7537-51fd-a3ec-1a8d5f63e03b', '27994085-b9ec-508c-a57e-40c5e780d00c', '4bf60c92-6eca-5089-acd5-d0f621736c62', 2, 24, 'ኢየሱስም መልሶ “እኔ ደግሞ አንዲት ነገር እጠይቃችኋለሁ፤ እናንተም ያችን ብትነግሩኝ እኔ ደግሞ እነዚህን በምን ሥልጣን እንዳደርግ እነግራችኋለሁ፤'),
  ('58108284-5755-58af-a393-dca91cee9b90', '27994085-b9ec-508c-a57e-40c5e780d00c', '4bf60c92-6eca-5089-acd5-d0f621736c62', 3, 25, 'የዮሐንስ ጥምቀት ከወዴት ነበረች? ከሰማይ ወይስ ከሰው?” አላቸው። እነርሱም እርስ በርሳቸው ሲነጋገሩ “ ‘ከሰማይ’ ብንል ‘እንኪያስ ስለ ምን አላመናችሁበትም?’ ይለናል፤'),
  ('3f07dcef-b5ca-53a5-a9e7-74348df35a76', '27994085-b9ec-508c-a57e-40c5e780d00c', '4bf60c92-6eca-5089-acd5-d0f621736c62', 4, 26, '‘ከሰው’ ግን ብንል፥ ዮሐንስን ሁሉም እንደ ነቢይ ያዩታልና ሕዝቡን እንፈራለን” አሉ።'),
  ('2d617ccf-b050-5d39-a813-14461b502f36', '27994085-b9ec-508c-a57e-40c5e780d00c', '4bf60c92-6eca-5089-acd5-d0f621736c62', 5, 27, 'ለኢየሱስም መልሰው “አናውቅም” አሉት። እርሱም ደግሞ “እኔም በምን ሥልጣን እነዚህን እንዳደርግ አልነግራችሁም፤” አላቸው።'),
  ('be4a936b-7195-59ce-a927-111ad4873609', '27994085-b9ec-508c-a57e-40c5e780d00c', 'e65561fc-00e6-51c6-a54e-d1dbcb313d29', 1, 28, '“ነገር ግን ምን ይመስላችኋል? አንድ ሰው ሁለት ልጆች ነበሩት፤ ወደ አንደኛው ቀርቦ ‘ልጄ ሆይ! ዛሬ ሂድና በወይኔ አትክልት ሥራ፤’ አለው።'),
  ('c36b7d10-a0e9-5034-a3c6-87de34d44eeb', '27994085-b9ec-508c-a57e-40c5e780d00c', 'e65561fc-00e6-51c6-a54e-d1dbcb313d29', 2, 29, 'እርሱም መልሶ ‘አልወድም፤’ አለ፤ ኋላ ግን ተጸጸተና ሄደ።'),
  ('a4e0a530-813c-5eca-a253-5592590ccc26', '27994085-b9ec-508c-a57e-40c5e780d00c', 'e65561fc-00e6-51c6-a54e-d1dbcb313d29', 3, 30, 'ወደ ሁለተኛውም ቀርቦ እንዲሁ አለው እርሱም መልሶ ‘እሺ ጌታዬ፤’ አለ፤ ነገር ግን አልሄደም።'),
  ('fef31ae8-0bcb-5efd-a0ec-d37939a30f6b', '27994085-b9ec-508c-a57e-40c5e780d00c', 'e65561fc-00e6-51c6-a54e-d1dbcb313d29', 4, 31, 'ከሁለቱ የአባቱን ፈቃድ ያደረገ ማን ነው?” “ፊተኛው” አሉት። ኢየሱስ እንዲህ አላቸው “እውነት እላችኋለሁ፥ ቀራጮችና ጋለሞቶች ወደ እግዚአብሔር መንግሥት በመግባት ይቀድሙአችኋል።'),
  ('3e3a21b8-ddfe-50de-af5a-81e817ff4324', '27994085-b9ec-508c-a57e-40c5e780d00c', 'e65561fc-00e6-51c6-a54e-d1dbcb313d29', 5, 32, 'ዮሐንስ በጽድቅ መንገድ መጥቶላችሁ ነበርና፤ አላመናችሁበትም፤ ቀራጮችና ጋለሞቶች ግን አመኑበት፤ እናንተም ይህን አይታችሁ ታምኑበት ዘንድ በኋላ ንስሐ አልገባችሁም።'),
  ('9ad9132a-5425-53a8-a8be-ff860c3639da', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 1, 33, '“ሌላ ምሳሌ ስሙ። የወይን አትክልት የተከለ ባለቤት ሰው ነበረ፤ ቅጥርም ቀጠረለት፤ መጥመቂያም ማሰለት፤ ግንብም ሠራና ለገበሬዎች አከራይቶ ወደ ሌላ አገር ሄደ።'),
  ('d447781e-7bf2-5d15-a856-41295afdb1cb', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 2, 34, 'የሚያፈራበትም ጊዜ ሲቀርብ፥ ፍሬውን ሊቀበሉ ባሮቹን ወደ ገበሬዎች ላከ።'),
  ('9cb7e6be-929f-5085-af70-4ad53e91301b', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 3, 35, 'ገበሬዎቹም ባሮቹን ይዘው አንዱን ደበደቡት፤ አንዱንም ገደሉት፤ ሌላውንም ወገሩት።'),
  ('7f94557d-5af2-527c-a65b-86c13eb452a4', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 4, 36, 'ደግሞ ከፊተኞች የሚበዙ ሌሎች ባሮችን ላከ፤ እንዲሁም አደረጉባቸው።'),
  ('694f8107-1f86-5775-a13f-9bdc74d1907d', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 5, 37, 'በኋላ ግን ‘ልጄንስ ያፍሩታል፤’ ብሎ ልጁን ላከባቸው።'),
  ('7e82f244-4414-511b-a48e-c85b28df7465', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 6, 38, 'ገበሬዎቹ ግን ልጁን ባዩ ጊዜ እርስ በርሳቸው ‘ወራሹ ይህ ነው፤ ኑ፤ እንግደለውና ርስቱን እናግኝ፤’ ተባባሉ።'),
  ('4e5bbb0b-54f5-5fa5-a32b-d997e5739227', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 7, 39, 'ይዘውም ከወይኑ አትክልት አወጡና ገደሉት።'),
  ('9728aedd-d8dc-5cd1-acf6-f4f321e2ecad', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 8, 40, 'እንግዲህ የወይኑ አትክልት ጌታ በሚመጣ ጊዜ በእነዚህ ገበሬዎች ምን ያደርግባቸዋል?”'),
  ('e31ec503-7267-5c64-a0e8-b6b6de95d5e6', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 9, 41, 'እነርሱም “ክፉዎችን በክፉ ያጠፋቸዋል፤ የወይኑንም አትክልት ፍሬውን በየጊዜው ለሚያስረክቡ ለሌሎች ገበሬዎች ይሰጠዋል፤” አሉት።'),
  ('88328bc9-8daf-5d6f-a9f9-f3b30baf5c5f', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 10, 42, 'ኢየሱስ እንዲህ አላቸው'),
  ('c00695c0-182f-56c2-ae0a-3fc27689d517', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 11, 45, 'የካህናት አለቆችና ፈሪሳውያንም ምሳሌዎቹን ሰምተው ስለ እነርሱ እንደ ተናገረ አስተዋሉ፤'),
  ('16462cb4-1ea7-5789-a7d4-19072e593b02', '27994085-b9ec-508c-a57e-40c5e780d00c', 'a868791f-c3c6-5f7a-a544-26834ecea196', 12, 46, 'ሊይዙትም ሲፈልጉት ሳሉ ሕዝቡ እንደ ነቢይ ስላዩት ፈሩአቸው።'),
  ('37ab3233-07f4-54c4-ad2a-f4ec7f7c6a2a', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 1, 1, 'ኢየሱስም መለሰ ደግሞም በምሳሌ ነገራቸው እንዲህም አለ'),
  ('d8eb1661-0e0e-5cbe-a3a5-0466ac1bf9c7', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 2, 2, '“መንግሥተ ሰማያት ለልጁ ሰርግ ያደረገ ንጉሥን ትመስላለች።'),
  ('f0e19ab8-ec2b-554f-ad57-a44aad9385a8', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 3, 3, 'የታደሙትንም ወደ ሰርጉ ይጠሩ ዘንድ ባሮቹን ላከ፤ ሊመጡም አልወደዱም።'),
  ('d632270e-ad44-5705-a64c-41b59575ad64', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 4, 4, 'ደግሞ ሌሎችን ባሮች ልኮ ‘የታደሙትን እነሆ፥ ድግሴን አዘጋጀሁ፤ ኮርማዎቼና የሰቡት ከብቶቼ ታርደዋል፤ ሁሉም ተዘጋጅቶአል፤ ወደ ሰርጉ ኑ፤ በሉአቸው፤’ አለ።'),
  ('9a58a5d8-d400-5847-a99a-29224ebc794e', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 5, 5, 'እነርሱ ግን ቸል ብለው አንዱ ወደ እርሻው፥ ሌላውም ወደ ንግዱ ሄደ፤'),
  ('8043c7d2-9db6-5c13-ab87-8e2a1b5bd17f', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 6, 6, 'የቀሩትም ባሮቹን ይዘው አንገላቱአቸው፤ ገደሉአቸውም።'),
  ('5c4c7092-0f22-5eb1-a8f2-6b50d8b25fa4', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 7, 7, 'ንጉሡም ተቈጣ፤ ጭፍሮቹንም ልኮ እነዚያን ገዳዮች አጠፋ፤ ከተማቸውንም አቃጠለ።'),
  ('35f2cac6-3dc5-55a5-a07a-bb83b0627944', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 8, 8, 'በዚያን ጊዜ ባሮቹን ‘ሰርጉ ተዘጋጅቶአል፤ ነገር ግን የታደሙት የማይገባቸው ሆኑ፤'),
  ('35864307-e1d4-5a39-a9b0-39fcf77f1355', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 9, 9, 'እንግዲህ ወደ መንገድ መተላለፊያ ሄዳችሁ ያገኛችሁትን ሁሉ ወደ ሰርጉ ጥሩ፤’ አለ።'),
  ('d2cf705e-861b-5e98-aa70-77782dd5e9f2', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 10, 10, 'እነዚያም ባሮች ወደ መንገድ ወጥተው ያገኙትን ሁሉ ክፉዎችንም በጎዎችንም ሰበሰቡ፤ የሰርጉንም ቤት ተቀማጮች ሞሉት።'),
  ('7468dddb-e8bb-5434-aa91-0a45cd178572', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 11, 11, '“ንጉሡም የተቀመጡትን ለማየት በገባ ጊዜ በዚያ የሰርግ ልብስ ያለበሰ አንድ ሰው አየና ‘ወዳጄ ሆይ!'),
  ('43cc869e-0a62-5982-ace6-a07012d2aa10', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 12, 12, 'የሰርግ ልብስ ሳትለብስ እንዴት ወደዚህ ገባህ?’ አለው እርሱም ዝም አለ።'),
  ('d099afd6-36e5-5a74-abbb-299dcc71e4bf', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 13, 13, 'በዚያን ጊዜ ንጉሡ አገልጋዮቹን ‘እጁንና እግሩን አስራችሁ በውጭ ወዳለው ጨለማ አውጡት፤ በዚያ ልቅሶና ጥርስ ማፋጨት ይሆናል፤’ አለ።'),
  ('25a23478-1468-5c25-abf1-1937a86db68d', 'f1062302-d39e-5331-aceb-3e915262d920', '85500e27-7ebb-583d-aee2-9d6d15022fe6', 14, 14, 'የተጠሩ ብዙዎች፥ የተመረጡ ግን ጥቂቶች ናቸውና።”'),
  ('8257aa0a-7f74-5938-a474-0db79caf71ed', 'f1062302-d39e-5331-aceb-3e915262d920', '57b004f2-a44b-5498-ab2b-78400c1fc711', 1, 15, 'ስለዚህ ፈሪሳውያን ሄዱና እንዴት አድርገው በነገር እንዲያጠምዱት ተማከሩ።'),
  ('28366cf2-a257-5794-abad-2b489a9eca4f', 'f1062302-d39e-5331-aceb-3e915262d920', '57b004f2-a44b-5498-ab2b-78400c1fc711', 2, 16, 'ደቀ ዛሙርታቸውንም ከሄሮድስ ወገን ጋር ላኩበት፤ እነርሱም “መምህር ሆይ! እውነተኛ እንደ ሆንህ በእውነትም የእግዚአብሔርን መንገድ እንድታስተምር እናውቃለን፤ ለማንምም አታደላም፤ የሰውን ፊት አትመለከትምና፤'),
  ('11adb7e9-3a16-5e8c-acc1-d645d333782c', 'f1062302-d39e-5331-aceb-3e915262d920', '57b004f2-a44b-5498-ab2b-78400c1fc711', 3, 17, 'እንግዲህ ምን ይመስልሃል? ንገረን ለቄሳር ግብር መስጠት ተፈቅዶአልን ወይስ አልተፈቀደም?” አሉት።'),
  ('d08e1db2-035c-50dd-ade9-363e61737248', 'f1062302-d39e-5331-aceb-3e915262d920', '57b004f2-a44b-5498-ab2b-78400c1fc711', 4, 18, 'ኢየሱስም ክፋታቸውን አውቆ “እናንተ ግብዞች፥ ስለ ምን ትፈትኑኛላችሁ?'),
  ('626517b0-4b09-5ca0-a90f-e4d9ffd87660', 'f1062302-d39e-5331-aceb-3e915262d920', '57b004f2-a44b-5498-ab2b-78400c1fc711', 5, 19, 'የግብሩን ብር አሳዩኝ፤” አለ። እነርሱም ዲናር አመጡለት።'),
  ('e966e910-271b-5d48-a5b8-b702fc67bce2', 'f1062302-d39e-5331-aceb-3e915262d920', '57b004f2-a44b-5498-ab2b-78400c1fc711', 6, 20, 'እርሱም “ይህች መልክ ጽሕፈቲቱስ የማን ናት?” አላቸው።'),
  ('e2bff39b-684f-526f-aa5e-46387898ddb9', 'f1062302-d39e-5331-aceb-3e915262d920', '57b004f2-a44b-5498-ab2b-78400c1fc711', 7, 21, '“የቄሳር ነው፤” አሉት። በዚያን ጊዜ “እንኪያስ የቄሣርን ለቄሣር የእግዚአብሔርንም ለእግዚአብሔር አስረክቡ፤” አላቸው።'),
  ('8a083b91-4e9c-5955-a25c-c69b8cf2dabd', 'f1062302-d39e-5331-aceb-3e915262d920', '57b004f2-a44b-5498-ab2b-78400c1fc711', 8, 22, 'ይህንም ሰምተው ተደነቁ፤ ትተውትም ሄዱ።'),
  ('364edac3-ef08-5afc-af77-fbc77e115d43', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 1, 23, 'በዚያን ቀን “ትንሣኤ ሙታን የለም፤” የሚሉ ሰዱቃውያን ወደ እርሱ ቀረቡ፤'),
  ('aaf4d0c6-069d-5b33-a240-5ec2a3245e79', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 2, 24, 'እንዲህም ብለው ጠየቁት “መምህር ሆይ! ሙሴ ‘አንድ ሰው ልጅ ሳይወልድ ሲሞት ወንድሙ ሚስቱን አግብቶ ለወንድሙ ዘር ይተካ፤’ አለ።'),
  ('5cf75328-e9ca-56a5-a8c1-f2ea4c84c205', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 3, 25, 'ሰባት ወንድማማች በእኛ ዘንድ ነበሩ፤ ፊተኛውም ሚስት አግብቶ ሞተ፤ ዘርም ስለሌለው ሚስቱን ለወንድሙ ተወለት፤'),
  ('a930e41d-e567-5d02-a399-2a1d32ea2256', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 4, 26, 'እንዲሁ ደግሞ ሁለተኛው ሦስተኛውም፥ እስከ ሰባተኛው ድረስ።'),
  ('bc2a0eed-fcd0-5f49-a937-e0fa3e6f92e2', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 5, 27, 'ከሁሉም በኋላ ሴቲቱ ሞተች።'),
  ('2ad40f52-8199-5cdb-a601-cfcd468025b9', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 6, 28, 'ሁሉ አግብተዋታልና በትንሣኤ ቀን ከሰባቱ ለማናቸው ሚስት ትሆናለች?”'),
  ('4a3e1e2f-f0fc-55c4-a166-823a8237bf66', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 7, 29, 'ኢየሱስም መልሶ እንዲህ አላቸው መጻሕፍትንና የእግዚአብሔርን ኃይል አታውቁምና ትስታላችሁ።'),
  ('71a8e85b-4500-5456-af10-256b8fb4a4e1', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 8, 30, 'በትንሣኤስ እንደ እግዚአብሔር መላእክት በሰማይ ይሆናሉ እንጂ አያገቡም አይጋቡምም።'),
  ('4e0fb5be-6634-5762-ae96-9dd5e41682f6', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 9, 31, 'ስለ ትንሣኤ ሙታን ግን ‘እኔ የአብርሃም አምላክ፥ የይስሐቅም አምላክ የያዕቆብም አምላክ ነኝ፤’ የሚል ከእግዚአብሔር ዘንድ ወደ እናንተ የተባለውን አላነበባችሁምን? የሕያዋን አምላክ ነው እንጂ የሙታን አይደለም።”'),
  ('a691bd07-c6bf-54f1-ab89-632461883304', 'f1062302-d39e-5331-aceb-3e915262d920', 'd0a7b774-413f-5098-ab81-0369446dde8d', 10, 33, 'ሕዝቡም ይህን ሰምተው በትምህርቱ ተገረሙ።'),
  ('233df0ea-59bd-512c-a85f-b244486aa69f', 'f1062302-d39e-5331-aceb-3e915262d920', '056028bc-d7a6-57be-a9e3-c26ea4a9aff2', 1, 34, 'ፈሪሳውያንም ሰዱቃውያንን ዝም እንዳሰኛቸው በሰሙ ጊዜ አብረው ተሰበሰቡ።'),
  ('ea96e267-71e4-5eec-aa17-7a82ed04c2c2', 'f1062302-d39e-5331-aceb-3e915262d920', '056028bc-d7a6-57be-a9e3-c26ea4a9aff2', 2, 35, 'ከእነርሱም አንድ ሕግ አዋቂ ሊፈትነው'),
  ('51932af7-aaf9-5852-a751-acfc10517578', 'f1062302-d39e-5331-aceb-3e915262d920', '056028bc-d7a6-57be-a9e3-c26ea4a9aff2', 3, 36, '“መምህር ሆይ! ከሕግ ማናቸይቱ ትእዛዝ ታላቅ ናት?” ብሎ ጠየቀው።'),
  ('b8956b0d-2a73-53d0-acf2-156cb3567e62', 'f1062302-d39e-5331-aceb-3e915262d920', '056028bc-d7a6-57be-a9e3-c26ea4a9aff2', 4, 37, 'ኢየሱስም እንዲህ አለው “ ‘ጌታ አምላክህን በፍጹም ልብህ በፍጹም ነፍስህም በፍጹም አሳብህም ውደድ።’'),
  ('72edd488-e1cc-56c3-a2e1-e9b466fdcafe', 'f1062302-d39e-5331-aceb-3e915262d920', '056028bc-d7a6-57be-a9e3-c26ea4a9aff2', 5, 38, 'ታላቂቱና ፊተኛይቱ ትእዛዝ ይህች ናት።'),
  ('8d31cc11-28e9-5118-a18d-e4c1fc726d63', 'f1062302-d39e-5331-aceb-3e915262d920', '056028bc-d7a6-57be-a9e3-c26ea4a9aff2', 6, 39, 'ሁለተኛይቱም ይህችን ትመስላለች፥ እርስዋም ‘ባልንጀራህን እንደ ነፍስህ ውደድ፤’ የምትለው ናት።'),
  ('7ce7cefa-2b83-5089-af8d-de3bc6d43b5f', 'f1062302-d39e-5331-aceb-3e915262d920', '056028bc-d7a6-57be-a9e3-c26ea4a9aff2', 7, 40, 'በእነዚህ በሁለቱ ትእዛዛት ሕጉም ሁሉ ነቢያትም ተሰቅለዋል።”'),
  ('8df10556-aae2-540e-a7cd-3477a27eca38', 'f1062302-d39e-5331-aceb-3e915262d920', 'd6590aa8-60d2-5c20-a462-6457bcb0c251', 1, 41, 'ፈሪሳውያንም ተሰብስበው ሳሉ፥ ኢየሱስ “ስለ ክርስቶስ ምን ይመስላችኋል? የማንስ ልጅ ነው?” ብሎ ጠየቃቸው። “የዳዊት ልጅ ነው፤” አሉት።'),
  ('b1566969-4c8f-5c4c-a9fc-67b95d959043', 'f1062302-d39e-5331-aceb-3e915262d920', 'd6590aa8-60d2-5c20-a462-6457bcb0c251', 2, 43, 'እርሱም “እንኪያስ ዳዊት'),
  ('643487e2-8a0f-5647-af6d-a508437b9403', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 1, 1, 'በዚያን ጊዜ ኢየሱስ ለሕዝቡና ለደቀ መዛሙርቱ እንዲህ ብሎ ነገራቸው'),
  ('fb61c809-aa3d-5d2d-a1ad-9077cfb7207e', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 2, 2, '“ጻፎችና ፈሪሳውያን በሙሴ ወንበር ተቀምጠዋል።'),
  ('caa80632-a53e-56db-aa11-ec7735906c3a', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 3, 3, 'ስለዚህ ያዘዙአችሁን ሁሉ አድርጉ፤ ጠብቁትም፤ ነገር ግን እየተናገሩ አያደርጉትምና እንደ ሥራቸው አታድርጉ።'),
  ('f72aeac9-e5c9-5457-a347-d7439eb445b9', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 4, 4, 'ከባድና አስቸጋሪ ሸክም ተብትበው በሰው ትከሻ ይጭናሉ፤ እነርሱ ግን በጣታቸው ስንኳ ሊነኩት አይወዱም።'),
  ('42391584-2d8c-5a49-a7c2-5fc42c2bebc7', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 5, 5, 'ለሰውም እንዲታዩ ሥራቸውን ሁሉ ያደርጋሉ፤ ስለዚህ አሽንክታባቸውን ያሰፋሉ፤ ዘርፉንም ያስረዝማሉ፤'),
  ('b92c784a-02f9-51e1-ad7a-b4a2a5816711', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 6, 6, 'በግብዣም የከበሬታ ስፍራ፥ በምኵራብም የከበሬታ ወንበር፥'),
  ('8dfb6821-974f-586e-a31c-c00030e5051d', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 7, 7, 'በገበያም ሰላምታና ‘መምህር ሆይ! መምህር ሆይ!’ ተብለው እንዲጠሩ ይወዳሉ።'),
  ('2ed1d72e-fa79-5e0e-a132-19c3f07faa59', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 8, 8, 'እናንተ ግን ‘መምህር’ ተብላችሁ አትጠሩ፤ መምህራችሁ አንድ ስለ ሆነ እናንተም ሁላችሁ ወንድማማች ናችሁ።'),
  ('b633660a-7f3b-5342-a10c-47cfe5a2f904', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 9, 9, 'አባታችሁ አንዱ እርሱም የሰማዩ ነውና በምድር ላይ ማንንም ‘አባት’ ብላችሁ አትጥሩ።'),
  ('62b3fbae-807b-58bb-a239-383217ae6877', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 10, 10, 'ሊቃችሁ አንድ እርሱም ክርስቶስ ነውና ‘ሊቃውንት’ ተብላችሁ አትጠሩ።'),
  ('e26fddad-058d-5a2b-a9b8-d8de1024fb37', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 11, 11, 'ከእናንተም የሚበልጠው አገልጋያችሁ ይሆናል።'),
  ('e949104a-bc5b-5530-a6e1-1a1a652bcee1', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 12, 12, 'ራሱን ከፍ የሚያደርግ ሁሉ ይዋረዳል፤ ራሱንም የሚያዋርድ ሁሉ ከፍ ይላል።'),
  ('b56ff86e-d02a-5ab0-ac21-58d989152c62', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 13, 13, '“እናንተ ግብዞች ጻፎችና ፈሪሳውያን! መንግሥተ ሰማያትን በሰው ፊት ስለምትዘጉ ወዮላችሁ፤ እናንተ አትገቡም፤ የሚገቡትንም እንዳይገቡ ትከለክላላችሁ።'),
  ('8bd53b2c-7433-5bad-a16b-4dc78d05a47f', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 14, 14, 'እናንተ ግብዞች ጻፎችና ፈሪሳውያን! በጸሎት ርዝመት እያመካኛችሁ የመበለቶችን ቤት ስለምትበሉ፥ ወዮላችሁ፤ ስለዚህ የባሰ ፍርድ ትቀበላላችሁ።'),
  ('4c321d24-1057-5f7e-a171-c20f4811c6d1', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 15, 15, 'እናንተ ግብዞች ጻፎችና ፈሪሳውያን! አንድ ሰው ልታሳምኑ በባሕርና በደረቅ ስለምትዞሩ፥ በሆነም ጊዜ ከእናንተ ይልቅ ሁለት እጥፍ የባሰ የገሃነም ልጅ ስለምታደርጉት፥ ወዮላችሁ።'),
  ('0b80ac8a-d69c-5664-a40e-e3e26586f4a7', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 16, 16, '“እናንተ ‘ማንም በቤተ መቅደስ የሚምል ምንም የለበትም፤ ማንም በቤተ መቅደስ ወርቅ የሚምል ግን በመሐላው ይያዛል፤’ የምትሉ፥ ዕውሮች መሪዎች፥ ወዮላችሁ።'),
  ('b562bd96-7e6c-54a6-a7de-1b161124da20', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 17, 17, 'እናንተ ደንቆሮዎችና ዕውሮች! ማናቸው ይበልጣል? ወርቁ ነውን? ወይስ ወርቁን የቀደሰው ቤተ መቅደስ?'),
  ('ddaaf8dc-95b7-5cb4-a70c-f25bd64074c5', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 18, 18, 'ደግማችሁም ‘ማንም በመሠዊያው የሚምል ምንም የለበትም፤ ማንም በላዩ ባለው መባ የሚምል ግን በመሐላው ይያዛል፤’ ትላላችሁ።'),
  ('0a973580-8cb6-533d-a872-d952733151f3', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 19, 19, 'እናንተ ደንቆሮዎችና ዕውሮች! ማናቸው ይበልጣል? መባው ነውን? ወይስ መባውን የሚቀድሰው መሠዊያው?'),
  ('1db6c53a-4810-5bc2-ad19-12ff3ad11d36', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 20, 20, 'እንግዲህ በመሠዊያው የሚምለው በእርሱና በእርሱ ላይ ባለው ሁሉ ይምላል፤')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c496e367-c6f4-532a-a590-d0c36711e0ce', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 21, 21, 'በቤተ መቅደስም የሚምለው በእርሱና በእርሱ በሚኖረው ይምላል፤'),
  ('0ce99075-8b1e-5309-a93b-fe3bd1ed3a37', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 22, 22, 'በሰማይም የሚምለው በእግዚአብሔር ዙፋንና በእርሱ ላይ በተቀመጠው ይምላል።'),
  ('0f93a4e8-f108-52de-a5ed-b8cadb1df89b', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 23, 23, '“እናንተ ግብዞች ጻፎችና ፈሪሳውያን! ከአዝሙድና ከእንስላል ከከሙንም አሥራት ስለምታወጡ፥ ፍርድንና ምሕረትን ታማኝነትንም፥ በሕግ ያለውን ዋና ነገር ስለምትተዉ፥ ወዮላችሁ፤ ሌላውን ሳትተዉ ይህን ልታደርጉ ይገባችሁ ነበር።'),
  ('d971897e-29ba-5db8-a7e2-82bf0ba96a4d', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 24, 24, 'እናንተ ዕውሮች መሪዎች! ትንኝን የምታጠሩ ግመልንም የምትውጡ።'),
  ('b7755d43-9870-5abb-a11e-d2fd9d60aa3d', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 25, 25, '“እናንተ ግብዞች ጻፎችና ፈሪሳውያን! በውስጡ ቅሚያና ስስት ሞልቶ ሳለ የጽዋውንና የወጭቱን ውጭ ስለምታጠሩ፥ ወዮላችሁ።'),
  ('3dacaf97-5831-54ae-a810-2894a3e86939', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 26, 26, 'አንተ ዕውር ፈሪሳዊ! ውጭው ደግሞ ጥሩ እንዲሆን አስቀድመህ የጽዋውንና የወጭቱን ውስጡን አጥራ።'),
  ('660477ce-b33a-5f10-ad12-45f584977a29', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 27, 27, '“እናንተ ግብዞች ጻፎችና ፈሪሳውያን! በውጭ አምረው የሚታዩ በውስጡ ግን የሙታን አጥንት ርኩሰትም ሁሉ የተሞሉ በኖራ የተለሰኑ መቃብሮችን ስለምትመስሉ፥ ወዮላችሁ።'),
  ('6439b961-78ff-5e6c-a384-50579931ad1e', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 28, 28, 'እንዲሁ እናንተ ደግሞ በውጭ ለሰው እንደ ጻድቃን ትታያላችሁ፤ በውስጣችሁ ግን ግብዝነትና ዐመፀኝነት ሞልቶባችኋል።'),
  ('420a76fb-5ec0-54ef-a150-357d2a417aa5', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 29, 29, '“እናንተ ግብዞች ጻፎችና ፈሪሳውያን! የነቢያትን መቃብር ስለምትሠሩ የጻድቃንንም መቃብር ስለምታስጌጡና'),
  ('e957ab96-24cb-59f6-a75e-2e56e7db7854', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 30, 30, '‘በአባቶቻችን ዘመን ኖረን በሆነስ በነቢያት ደም ባልተባበርናቸውም ነበር፤’ ስለምትሉ፥ ወዮላችሁ።'),
  ('e7e9a768-29c9-5789-a67c-168cf7d6bd89', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 31, 31, 'እንግዲያስ የነቢያት ገዳዮች ልጆች እንደሆናችሁ በራሳችሁ ላይ ትመሰክራላችሁ።'),
  ('c7cd4530-c628-539c-af16-4ad07430c571', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 32, 32, 'እናንተ ደግሞ የአባቶቻችሁን መስፈሪያ ሙሉ።'),
  ('dd78808d-66ff-50a5-a26a-dbe7beeaa0dc', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 33, 33, 'እናንተ እባቦች! የእፉኝት ልጆች! ከገሃነም ፍርድ እንዴት ታመልጣላችሁ?'),
  ('f413b12c-8f66-5f45-a6f6-4a0e89b18940', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 34, 34, 'ስለዚህ፥ እነሆ፥ ነቢያትንና ጥበበኞችን ጻፎችንም ወደ እናንተ እልካለሁ፤ ከእነርሱም ትገድላላችሁ ትሰቅሉማላችሁ፥ ከእነርሱም በምኵራባችሁ ትገርፋላችሁ ከከተማም ወደ ከተማ ታሳድዳላችሁ፤'),
  ('d6c81c5f-4a07-59f4-af0e-79cd84281c24', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 35, 35, 'ከጻድቁ ከአቤል ደም ጀምሮ በቤተ መቅደስና በመሠዊያው መካከል እስከ ገደላችሁት እስከ በራክዩ ልጅ እስከ ዘካርያስ ደም ድረስ በምድር ላይ የፈሰሰው የጻድቅ ደም ሁሉ ይደርስባችኋል።'),
  ('12cc87a9-936d-57a7-a7ae-caad6bc64ace', '479dc9c0-9076-519e-a06d-0b799f6ffc83', '205c2580-4870-571d-a709-0cd491f489c3', 36, 36, 'እውነት እላችኋለሁ፤ ይህ ሁሉ በዚህ ትውልድ ላይ ይደርሳል።'),
  ('e559bb25-695e-5479-a1cd-943efe73d4d3', '479dc9c0-9076-519e-a06d-0b799f6ffc83', 'cf8a42a6-87c4-5d9d-a346-2af8e812a141', 1, 37, '“ኢየሩሳሌም ኢየሩሳሌም ሆይ! ነቢያትን የምትገድል ወደ እርስዋ የተላኩትንም የምትወግር፥ ዶሮ ጫጩቶችዋን ከክንፎችዋ በታች እንደምትሰበስብ ልጆችሽን እሰበስብ ዘንድ ስንት ጊዜ ወደድሁ! አልወደዳችሁምም።'),
  ('f7590d31-59d5-5588-a6c9-a3cd28a3d052', '479dc9c0-9076-519e-a06d-0b799f6ffc83', 'cf8a42a6-87c4-5d9d-a346-2af8e812a141', 2, 38, 'እነሆ፥ ቤታችሁ የተፈታ ሆኖ ይቀርላችኋል።'),
  ('7fe5b512-6297-58d6-abc9-341fe83bd18d', '479dc9c0-9076-519e-a06d-0b799f6ffc83', 'cf8a42a6-87c4-5d9d-a346-2af8e812a141', 3, 39, 'እላችኋለሁና፥ ‘በጌታ ስም የሚመጣ የተባረከ ነው፤’ እስክትሉ ድረስ ከእንግዲህ ወዲህ አታዩኝም።”'),
  ('18459165-7a40-5601-aacf-5d17b3636a0a', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 1, 1, 'ኢየሱስም ከመቅደስ ወጥቶ ሄደ፤ ደቀ መዛሙርቱም የመቅደሱን ግንቦች ሊያሳዩት ቀረቡ።'),
  ('477cc844-aa32-57f1-a481-c3eb0b8f7900', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 2, 2, 'እርሱ ግን መልሶ “ይህን ሁሉ ታያላችሁን? እውነት እላችኋለሁ፥ ድንጋይ በድንጋይ ላይ ሳይፈርስ በዚህ አይቀርም፤” አላቸው።'),
  ('4bf991ea-f744-59c6-aae4-a3a8028a06ce', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 3, 3, 'እርሱም በደብረ ዘይት ተቀምጦ ሳለ፥ ደቀ መዛሙርቱ ለብቻቸው ወደ እርሱ ቀርበው “ንገረን፤ ይህ መቼ ይሆናል? የመምጣትህና የዓለም መጨረሻ ምልክቱስ ምንድር ነው?” አሉት።'),
  ('5247f501-9d22-5965-a5f8-e3de8ed12aa5', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 4, 4, 'ኢየሱስም መልሶ እንዲህ አላቸው፤ “ማንም እንዳያስታችሁ ተጠንቀቁ።'),
  ('99f2c154-3638-5626-a4cd-e256d8148a25', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 5, 5, 'ብዙዎች ‘እኔ ክርስቶስ ነኝ፤’ እያሉ በስሜ ይመጣሉና፤ ብዙዎችንም ያስታሉ።'),
  ('c26c6ddb-7e6f-5fc4-a12a-b98828d10f70', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 6, 6, 'ጦርንም የጦርንም ወሬ ትሰሙ ዘንድ አላችሁ፤ ይህ ሊሆን ግድ ነውና ተጠበቁ፥ አትደንግጡ፤ ዳሩ ግን መጨረሻው ገና ነው።'),
  ('c902ae14-f205-56c4-ae6b-6ec931d7ef18', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 7, 7, 'ሕዝብ በሕዝብ ላይ መንግሥትም በመንግሥት ላይ ይነሣልና፤ ራብም ቸነፈርም የምድርም መናወጥ በልዩ ልዩ ስፍራ ይሆናል፤'),
  ('a251766c-d322-5a74-ad9d-cd019342e404', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 8, 8, 'እነዚህም ሁሉ የምጥ ጣር መጀመሪያ ናቸው።'),
  ('c97eb674-53aa-59b6-a5ee-59c5151c4a85', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 9, 9, '“በዚያን ጊዜ ለመከራ አሳልፈው ይሰጡአችኋል፤ ይገድሉአችሁማል፤ ስለ ስሜም በአሕዛብ ሁሉ የተጠላችሁ ትሆናላችሁ።'),
  ('277fbfd1-1324-5b6b-a7a4-9d8ba124b8ed', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 10, 10, 'በዚያን ጊዜም ብዙዎች ይሰናከላሉ፤ እርስ በርሳቸውም አሳልፈው ይሰጣጣሉ፤ እርስ በርሳቸውም ይጣላሉ፤'),
  ('fddb67c7-faf1-5c83-ab1c-7fc40aebe55c', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 11, 11, 'ብዙ ሐሰተኞች ነቢያትም ይነሣሉ፤ ብዙዎችንም ያስታሉ፤'),
  ('8f9b796a-dcb7-5f7d-a86c-d1ae467507da', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 12, 12, 'ከዐመፃም ብዛት የተነሣ የብዙ ሰዎች ፍቅር ትቀዘቅዛለች።'),
  ('5c3c4ed8-c4bf-5ca4-a7ac-17253a0f6efd', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 13, 13, 'እስከ መጨረሻ የሚጸና ግን እርሱ ይድናል።'),
  ('e89794a8-49a4-5454-a9ec-09f41cba85fb', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 14, 14, 'ለአሕዛብም ሁሉ ምስክር እንዲሆን ይህ የመንግሥት ወንጌል በዓለም ሁሉ ይሰበካል፤ በዚያን ጊዜም መጨረሻው ይመጣል።'),
  ('75054458-41c0-53ac-a22c-06f31afadbba', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 15, 15, '“እንግዲህ በነቢዩ በዳንኤል የተባለውን የጥፋትን ርኩሰት በተቀደሰችው ስፍራ ቆሞ ስታዩ፥ አንባቢው ያስተውል፤'),
  ('07c4fd6f-059c-501b-a58f-c1a5bc8012dc', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 16, 16, 'በዚያን ጊዜ በይሁዳ ያሉት ወደ ተራራዎች ይሽሹ፥'),
  ('5f363fa2-b5aa-5862-a834-cef78f9c4ced', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 17, 17, 'በሰገነትም ያለ በቤቱ ያለውን ሊወስድ አይውረድ፤'),
  ('3c3aca16-2ba7-534c-ab79-cf410a1e7d5d', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 18, 18, 'በእርሻም ያለ ልብሱን ይወስድ ዘንድ ወደ ኋላው አይመለስ።'),
  ('6aea5c92-13e7-5bb4-a2b2-939c5e4bfafc', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 19, 19, 'በዚያችም ወራት ለርጉዞችና ለሚያጠቡ ወዮላቸው።'),
  ('b14eebe3-11b7-5fab-a2d9-f3207d67a264', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 20, 20, 'ነገር ግን ሽሽታችሁ በክረምት ወይም በሰንበት እንዳይሆን ጸልዩ፤'),
  ('ec164df1-f716-50c7-a7b1-8930d7407b8d', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 21, 21, 'በዚያን ጊዜ ከዓለም መጀመሪያ ጀምሮ እስከ ዛሬ ድረስ ያልሆነ እንግዲህም ከቶ የማይሆን ታላቅ መከራ ይሆናልና።'),
  ('3f34a827-7d91-5336-a243-7455de1b55af', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 22, 22, 'እነዚያ ቀኖችስ ባያጥሩ ሥጋ የለበሰ ሁሉ ባልዳነም ነበር፤ ነገር ግን እነዚያ ቀኖች ስለ ተመረጡት ሰዎች ያጥራሉ።'),
  ('47385f45-7363-53a6-a472-003766f35d64', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 23, 23, 'በዚያን ጊዜ ማንም ‘እነሆ፥ ክርስቶስ እዚህ አለ፤’ ወይም ‘እዚያ አለ፤’ ቢላችሁ አትመኑ፤'),
  ('66d585b0-0201-559b-a0e6-71ef9ed2fa45', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 24, 24, 'ሐሰተኞች ክርስቶሶችና ሐሰተኞች ነቢያት ይነሣሉና፤ ቢቻላቸውስ የተመረጡትን እንኳ እስኪያስቱ ድረስ ታላላቅ ምልክትና ድንቅ ያሳያሉ።'),
  ('12c74ef1-0e8d-533c-a6d4-19752ff0eccb', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 25, 25, 'እነሆ፥ አስቀድሜ ነገርኋችሁ።'),
  ('06414303-b52d-5538-a40e-9521fc092fc2', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 26, 26, 'እንግዲህ ‘እነሆ፥ በበረሀ ነው፤’ ቢሉአችሁ፥ አትውጡ፤ ‘እነሆ፥ በእልፍኝ ነው፤’ ቢሉአችሁ፥ አትመኑ፤'),
  ('2d653441-b87e-585f-a77f-7b39b65ee50a', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 27, 27, 'መብረቅ ከምሥራቅ ወጥቶ እስከ ምዕራብ እንደሚታይ፥ የሰው ልጅ መምጣት እንዲሁ ይሆናልና፤'),
  ('f0f19b7a-9af3-5016-a7d7-326f083d443f', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '99d68efa-5853-575c-a2f5-13b113d1b815', 28, 28, 'በድን ወዳለበት በዚያ አሞራዎች ይሰበሰባሉ።'),
  ('52a80a56-3e88-5d56-a3b7-51f472b0b9c1', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'a33df50b-95a0-5b08-a35e-5a6552feee2e', 1, 29, '“ከዚያች ወራትም መከራ በኋላ ወዲያው ፀሐይ ይጨልማል፤ ጨረቃም ብርሃንዋን አትሰጥም፤ ከዋክብትም ከሰማይ ይወድቃሉ፤'),
  ('01c8880d-c473-55d4-ac07-afd9c7cdf411', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'a33df50b-95a0-5b08-a35e-5a6552feee2e', 2, 30, 'የሰማያትም ኃይላት ይናወጣሉ። በዚያን ጊዜም የሰው ልጅ ምልክት በሰማይ ይታያል፤ በዚያን ጊዜም የምድር ወገኖች ሁሉ ዋይ ዋይ ይላሉ፤ የሰው ልጅንም በኃይልና በብዙ ክብር በሰማይ ደመና ሲመጣ ያዩታል፤'),
  ('5009ca9b-e452-5452-a82a-b32375697e81', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'a33df50b-95a0-5b08-a35e-5a6552feee2e', 3, 31, 'መላእክቱንም ከታላቅ መለከት ድምፅ ጋር ይልካቸዋል፤ ከሰማያትም ዳርቻ እስከ ዳርቻው ከአራቱ ነፋሳት ለእርሱ የተመረጡትን ይሰበስባሉ።'),
  ('6d81bbaa-51cf-580e-aa82-af1555750b91', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'a33df50b-95a0-5b08-a35e-5a6552feee2e', 4, 32, '“ምሳሌውንም ከበለስ ተማሩ፤ ጫፍዋ ሲለሰልስ ቅጠልዋም ሲያቍኦጠቍጥ፥ ያን ጊዜ በጋ እንደ ቀረበ ታውቃላችሁ፤'),
  ('45ac3ed1-83cf-5483-adf0-ea1e27ebdfcb', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'a33df50b-95a0-5b08-a35e-5a6552feee2e', 5, 33, 'እንዲሁ እናንተ ደግሞ ይህን ሁሉ ስታዩ በደጅ እንደ ቀረበ እወቁ።'),
  ('50829cf0-7720-555b-a040-20307694d852', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'a33df50b-95a0-5b08-a35e-5a6552feee2e', 6, 34, 'እውነት እላችኋለሁ፤ ይህ ሁሉ እስኪሆን ድረስ ይህ ትውልድ አያልፍም።'),
  ('e047ad5e-fdec-5069-a6b4-e5b56be6645c', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'a33df50b-95a0-5b08-a35e-5a6552feee2e', 7, 35, 'ሰማይና ምድር ያልፋሉ፤ ቃሌ ግን አያልፍም።'),
  ('6909bfbe-e15a-51e1-ab43-aacd0340f120', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '9e4d17c1-3ee8-5023-a8fd-af20ec2d3748', 1, 36, '“ስለዚያች ቀንና ስለዚያች ሰዓት ግን ከአባት ብቻ በቀር የሰማይ መላእክትም ቢሆኑ ልጅም ቢሆን የሚያውቅ የለም።'),
  ('e16a794b-1266-5c3f-ab1e-dc637bb37bf1', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '9e4d17c1-3ee8-5023-a8fd-af20ec2d3748', 2, 37, 'የኖኅ ዘመን እንደ ነበረ የሰው ልጅ መምጣት እንዲሁ ይሆናልና።'),
  ('3c485157-0ab4-50a2-a464-9f3ca6493524', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '9e4d17c1-3ee8-5023-a8fd-af20ec2d3748', 3, 38, 'በዚያች ወራት ከጥፋት ውሃ በፊት፥ ኖኅ ወደ መርከብ እስከገባበት ቀን ድረስ፥ ሲበሉና ሲጠጡ ሲያገቡና ሲጋቡም እንደ ነበሩ፥'),
  ('663a12a0-8b39-5eb7-a35d-c454255c825a', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '9e4d17c1-3ee8-5023-a8fd-af20ec2d3748', 4, 39, 'የጥፋት ውሃም መጥቶ ሁሉን እስከ ወሰደ ድረስ እንዳላወቁ፥ የሰው ልጅ መምጣት ደግሞ እንዲሁ ይሆናል።'),
  ('01cbd8a0-564f-5dc2-a684-2437a3859e19', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '9e4d17c1-3ee8-5023-a8fd-af20ec2d3748', 5, 40, 'በዚያን ጊዜ ሁለት ሰዎች በእርሻ ይሆናሉ፤ አንዱ ይወሰዳል አንዱም ይቀራል፤'),
  ('487494f6-d051-597d-abdd-1fdd9e0b4b10', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '9e4d17c1-3ee8-5023-a8fd-af20ec2d3748', 6, 41, 'ሁለት ሴቶች በወፍጮ ይፈጫሉ፤ አንዲቱ ትወሰዳለች አንዲቱም ትቀራለች።'),
  ('2cd3e6a1-61a0-5669-a95d-227b39e1c073', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '9e4d17c1-3ee8-5023-a8fd-af20ec2d3748', 7, 42, 'ጌታችሁ በምን ሰዓት እንዲመጣ አታውቁምና እንግዲህ ንቁ።'),
  ('7589e4ba-69ee-5e2d-ad3b-e1aa2ea162e1', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '9e4d17c1-3ee8-5023-a8fd-af20ec2d3748', 8, 43, '“ያን ግን እወቁ፤ ባለቤት ከሌሊቱ በየትኛው ክፍል ሌባ እንዲመጣ ቢያውቅ ኖሮ፥ በነቃ፤ ቤቱም ሊቈፈር ባልተወም ነበር።'),
  ('c733a839-a04e-51af-ab36-dec46ccc687c', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', '9e4d17c1-3ee8-5023-a8fd-af20ec2d3748', 9, 44, 'ስለዚህ እናንተ ደግሞ ተዘጋጅታችሁ ኑሩ፤ የሰው ልጅ በማታስቡበት ሰዓት ይመጣልና።'),
  ('ee9b6062-f617-5bfc-a2cc-b1590d5f8346', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'b26df92c-cd0a-56a5-aaf6-ef3b0f3f41b4', 1, 45, '“እንኪያስ ምግባቸውን በጊዜው ይሰጣቸው ዘንድ ጌታው በቤተ ሰዎች ላይ የሾመው ታማኝና ልባም ባሪያ ማን ነው?'),
  ('d1e55e18-71cd-5fcc-aef8-94820c71b1db', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'b26df92c-cd0a-56a5-aaf6-ef3b0f3f41b4', 2, 46, 'ጌታው መጥቶ እንዲህ ሲያደርግ የሚያገኘው ያ ባሪያ ብፁዕ ነው፤'),
  ('54c3b35f-4da6-5253-a9da-8c0bb222444c', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'b26df92c-cd0a-56a5-aaf6-ef3b0f3f41b4', 3, 47, 'እውነት እላችኋለሁ፤ ባለው ሁሉ ላይ ይሾመዋል።'),
  ('0c066325-551a-5c9e-aa9a-53992d223bcc', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'b26df92c-cd0a-56a5-aaf6-ef3b0f3f41b4', 4, 48, 'ያ ክፉ ባሪያ ግን ‘ጌታዬ እስኪመጣ ይዘገያል፤’ ብሎ በልቡ ቢያስብ፥'),
  ('30fd22e8-48be-5472-a802-2f267914ff2b', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'b26df92c-cd0a-56a5-aaf6-ef3b0f3f41b4', 5, 49, 'ባልንጀሮቹን ባሮች ሊመታ ቢጀምር፥ ከሰካሮችም ጋር ቢበላና ቢጠጣ፥'),
  ('81a02863-4702-5ff9-af39-44ab732e1723', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'b26df92c-cd0a-56a5-aaf6-ef3b0f3f41b4', 6, 50, 'የዚያ ባሪያ ጌታ ባልጠበቃት ቀን ባላወቃትም ሰዓት ይመጣል፤'),
  ('c5cda0fd-8ffb-545f-ae17-eec1a0af62ff', '4de56ac0-b9c5-57b1-a526-21d8fbbc8511', 'b26df92c-cd0a-56a5-aaf6-ef3b0f3f41b4', 7, 51, 'ከሁለትም ይሰነጥቀዋል፤ እድሉንም ከግብዞች ጋር ያደርግበታል፤ በዚያ ልቅሶና ጥርስ ማፋጨት ይሆናል።'),
  ('70aea812-1e11-50b0-a3c6-815a40aa37b2', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 1, 1, '“በዚያን ጊዜ መንግሥተ ሰማያት መብራታቸውን ይዘው ሙሽራውን ሊቀበሉ የወጡ ዐሥር ቆነጃጅትን ትመስላለች።'),
  ('f443b8d3-13a6-586f-acf1-c4e01dcd91ef', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 2, 2, 'ከእነርሱም አምስቱ ሰነፎች አምስቱም ልባሞች ነበሩ።'),
  ('55ffb33c-7b4f-5347-a1a3-543310ac6228', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 3, 3, 'ሰነፎቹ መብራታቸውን ይዘው ከእነርሱ ጋር ዘይት አልያዙምና፤'),
  ('3d46e146-9092-5dd9-a999-998c25d5d38e', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 4, 4, 'ልባሞቹ ግን ከመብራታቸው ጋር በማሰሮአቸው ዘይት ያዙ።'),
  ('c24d845a-a1a8-501c-a359-de73cf799cbc', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 5, 5, 'ሙሽራውም በዘገየ ጊዜ፥ ሁሉም እንቅልፍ እንቅልፍ አላቸውና ተኙ።'),
  ('a60001ef-75db-589f-a6a8-7c4b931a984c', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 6, 6, 'እኩል ሌሊትም ሲሆን ‘እነሆ፥ ሙሽራው ይመጣል፤ ትቀበሉት ዘንድ ውጡ፤’ የሚል ውካታ ሆነ።'),
  ('e14e51f2-5514-564e-aa9a-a78e29f1e968', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 7, 7, 'በዚያን ጊዜ እነዚያ ቆነጃጅት ሁሉ ተነሡና መብራታቸውን አዘጋጁ።'),
  ('c612af16-c516-5bb0-ae6e-47bbf324d383', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 8, 8, 'ሰነፎቹም ልባሞቹን ‘መብራታችን ሊጠፋብን ነው፤ ከዘይታችሁ ስጡን፤’ አሉአቸው።'),
  ('87a13009-be6e-53d1-ad04-b2c2476bd194', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 9, 9, 'ልባሞቹ ግን መልሰው ‘ምናልባት ለእኛና ለእናንተ ባይበቃስ፤ ይልቅስ ወደሚሸጡት ሄዳችሁ ለራሳችሁ ግዙ፤’ አሉአቸው።'),
  ('c30f8f0e-421f-58c9-ab18-00bb22b7b66c', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 10, 10, 'ሊገዙም በሄዱ ጊዜ ሙሽራው መጣ፤ ተዘጋጅተው የነበሩትም ከእርሱ ጋር ወደ ሰርግ ገቡ፤ ደጁም ተዘጋ።'),
  ('e0b12737-0050-5a62-a0a0-d0b820c25da6', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 11, 11, 'በኋላም ደግሞ የቀሩቱ ቈነጃጅት መጡና ‘ጌታ ሆይ! ጌታ ሆይ! ክፈትልን፤’ አሉ።'),
  ('60dcb881-2a8c-565a-a0f1-5eba1451f0e5', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 12, 12, 'እርሱ ግን መልሶ ‘እውነት እላችኋለሁ፥ አላውቃችሁም፤’ አለ።'),
  ('08b4df3a-a72f-5167-a915-52f64e5bb830', '5358d306-a9d9-5b3f-aea2-728c48358df2', '8123a559-f21c-50c2-aaeb-53e471d681df', 13, 13, 'ቀኒቱንና ስዓቲቱን አታውቁምና እንግዲህ ንቁ።'),
  ('14cb50ef-6aa4-5d01-a314-f8e87b965b26', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 1, 14, '“ወደ ሌላ አገር የሚሄድ ሰው ባሮቹን ጠርቶ ያለውን ገንዘብ እንደ ሰጣቸው እንዲሁ ይሆናልና፤'),
  ('6541919a-1a28-5d6f-a8c4-0f022f6637cc', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 2, 15, 'ለእያንዳንዱ እንደ ዐቅሙ፥ ለአንዱ አምስት መክሊት ለአንዱ ሁለት ለአንዱም አንድ ሰጠና ወደ ሌላ አገር ወዲያው ሄደ።'),
  ('71db0a1a-5c88-5aba-a8e8-796c53f06253', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 3, 16, 'አምስት መክሊትም የተቀበለው ሄዶ ነገደበት፤ ሌላም አምስት አተረፈ፤'),
  ('fcf733bd-1737-53e8-ad61-edc26a1a0c46', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 4, 17, 'እንዲሁም ሁለት የተቀበለው ሌላ ሁለት አተረፈ።'),
  ('c7be7697-3702-5a2e-ae67-3f8a92631a6f', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 5, 18, 'አንድ የተቀበለው ግን ሄዶ ምድርን ቈፈረና የጌታውን ገንዘብ ቀበረ።'),
  ('6510dd7c-a8c3-57eb-a91b-c2e383c5630e', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 6, 19, 'ከብዙ ዘመንም በኋላ የእነዚያ ባሮች ጌታ መጣና ተቆጣጠራቸው።'),
  ('b32c8d55-739c-55a5-a535-50e2dcd06ddd', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 7, 20, 'አምስት መክሊት የተቀበለውም ቀረበና ሌላ አምስት መክሊት አስረክቦ ‘ጌታ ሆይ! አምስት መክሊት ሰጥተኸኝ ነበር፤ እነሆ፥ ሌላ አምስት መክሊት አተረፍሁበት፤’ አለ።'),
  ('a249b001-c571-5641-a2d4-7c7d1048fcec', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 8, 21, 'ጌታውም ‘መልካም፥ አንተ በጎ ታማኝም ባሪያ፥ በጥቂቱ ታምነሃል፤ በብዙ እሾምሃለሁ፤ ወደ ጌታህ ደስታ ግባ፤’ አለው።'),
  ('e24efd6f-e2db-5467-a8b3-fb597e4ece5c', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 9, 22, 'ሁለት መክሊትም የተቀበለው ደግሞ ቀርቦ ‘ጌታ ሆይ! ሁለት መክሊት ሰጥተኸኝ ነበር፤ እነሆ፥ ሌላ ሁለት መክሊት አተረፍሁበት፤’ አለ።'),
  ('37cc51a7-2832-54d3-a911-2253266f7a28', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 10, 23, 'ጌታውም ‘መልካም፥ አንተ በጎ፥ ታማኝም ባሪያ፤ በጥቂቱ ታምነሃል፤ በብዙ እሾምሃለሁ፤ ወደ ጌታህ ደስታ ግባ፤’ አለው።'),
  ('35747d72-5869-5ddb-ad4a-133cb7a259a6', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 11, 24, 'አንድ መክሊትም የተቀበለው ደግሞ ቀርቦ ‘ጌታ ሆይ! ካልዘራህባት የምታጭድ ካልበተንህባትም የምትሰበስብ ጨካኝ ሰው መሆንህን አውቃለሁ፤'),
  ('9b956253-31ac-500b-aeb0-acada00a5020', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 12, 25, 'ፈራሁም ሄጄም መክሊትህን በምድር ቀበርሁት፤ እነሆ፥ መክሊትህ አለህ፤’ አለ።'),
  ('4067529f-157b-5fe3-abc3-8be698dae527', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 13, 26, 'ጌታውም መልሶ እንዲህ አለው ‘አንተ ክፉና ሃኬተኛ ባሪያ፥ ካልዘራሁባት እንዳጭድ ካልበተንሁባትም እንድሰበስብ ታውቃለህን?'),
  ('fcdd5d76-22ed-5c89-ae1c-239792c2e2b0', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 14, 27, 'ስለዚህ ገንዘቤን ለለዋጮች አደራ ልትሰጠው በተገባህ ነበር፤ እኔም መጥቼ ያለኝን ከትርፉ ጋር እወስደው ነበር።'),
  ('9b220e9a-7b33-5893-aba5-182401994257', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 15, 28, 'ስለዚህ መክሊቱን ውሰዱበት ዐሥር መክሊትም ላለው ስጡት፤'),
  ('214a639a-68bd-52df-a536-13390991775e', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 16, 29, 'ላለው ሁሉ ይሰጠዋልና፤ ይበዛለትማል፤ ከሌለው ግን ያው ያለው እንኳ ይወሰድበታል።'),
  ('bb72c362-6823-5b46-a63f-550d60cdc62e', '5358d306-a9d9-5b3f-aea2-728c48358df2', '51e68a32-869a-574a-a47b-579ed728002a', 17, 30, 'የማይጠቅመውንም ባሪያ በውጭ ወዳለው ጨለማ አውጡት፤ በዚያ ልቅሶና ጥርስ ማፋጨት ይሆናል።’'),
  ('6c547687-6b7a-5480-ad5b-bb7009525fb5', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 1, 31, '“የሰው ልጅ በክብሩ በሚመጣበት ጊዜ ከእርሱም ጋር ቅዱሳን መላእክቱ ሁሉ፥ በዚያን ጊዜ በክብሩ ዙፋን ይቀመጣል፤'),
  ('fd0f3023-69d8-5e87-a6c1-15e0c8941c97', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 2, 32, 'አሕዛብም ሁሉ በፊቱ ይሰበሰባሉ፤ እረኛም በጎቹን ከፍየሎች እንደሚለይ እርስ በርሳቸው ይለያቸዋል፤'),
  ('479bd3a9-08de-5926-afb9-b9a38f8051d7', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 3, 33, 'በጎችን በቀኙ ፍየሎችንም በግራው ያቆማቸዋል።'),
  ('4a3da866-5a6e-5ce3-add9-8f103441ab59', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 4, 34, 'ንጉሡም በቀኙ ያሉትን እንዲህ ይላቸዋል ‘እናንተ የአባቴ ቡሩካን! ኑ፤ ዓለም ከተፈጠረበት ጊዜ ጀምሮ የተዘጋጀላችሁን መንግሥት ውረሱ።'),
  ('28803e3e-4a6c-5fae-ab27-98afc766ccc2', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 5, 35, 'ተርቤ አብልታችሁኛልና፤ ተጠምቼ አጠጥታችሁኛልና፤ እንግዳ ሆኜ ተቀብላችሁኛልና፤ ታርዤ አልብሳችሁኛልና፤'),
  ('07996f30-2966-55f5-a6c6-b1b7b4b86d89', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 6, 36, 'ታምሜ ጠይቃችሁኛልና፤ ታስሬ ወደ እኔ መጥታችኋልና።’'),
  ('688db4a8-ba31-5a11-ac5f-d38a4cc2641f', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 7, 37, 'ጻድቃንም መልሰው ይሉታል ‘ጌታ ሆይ! ተርበህ አይተን መቼ አበላንህ? ወይስ ተጠምተህ አይተን መቼ አጠጣንህ?'),
  ('6f6bd1a8-76d2-5266-a176-c8d2537f489a', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 8, 38, 'እንግዳ ሆነህስ አይተን መቼ ተቀበልንህ? ወይስ ታርዘህ አይተን መቼ አለበስንህ?'),
  ('dfe1ecd7-b676-5bdc-a44b-d52035580ad4', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 9, 39, 'ወይስ ታመህ ወይስ ታስረህ አይተን መቼ ወደ አንተ መጣን?’'),
  ('5218a3ab-077b-5647-a133-8d938e18ab7f', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 10, 40, 'ንጉሡም መልሶ ‘እውነት እላችኋለሁ፤ ከሁሉ ከሚያንሱ ከእነዚህ ወንድሞቼ ለአንዱ እንኳ ስላደረጋችሁት ለእኔ አደረጋችሁት፤’ ይላቸዋል።'),
  ('b89516e1-a518-57bd-ab63-430393e0a160', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 11, 41, 'በዚያን ጊዜ በግራው ያሉትን ደግሞ ይላቸዋል ‘እናንተ ርጉማን! ለሰይጣንና ለመላእክቱ ወደ ተዘጋጀ ወደ ዘላለም እሳት ከእኔ ሂዱ።'),
  ('e116fca7-3e05-5415-a55d-8a534ae39826', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 12, 42, 'ተርቤ አላበላችሁኝምና፤ ተጠምቼ አላጠጣችሁኝምና፤'),
  ('cfd5b069-4b33-5930-a09e-b9d9cb6e46cb', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 13, 43, 'እንግዳ ሆኜ አልተቀበላችሁኝምና፤ ታርዤ አላለበሳችሁኝምና፤ ታምሜ ታስሬም አልጠየቃችሁኝምና።’'),
  ('caf00c0f-223f-5abd-ac8b-8ffc1ce2fcd9', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 14, 44, 'እነርሱ ደግሞ ይመልሱና ‘ጌታ ሆይ! ተርበህ ወይስ ተጠምተህ ወይስ እንግዳ ሆነህ ወይስ ታርዘህ ወይስ ታመህ ወይስ ታስረህ መቼ አይተን አላገለገልንህም?’ ይሉታል።'),
  ('59d66f63-1434-5a95-a630-6ae957d421c8', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 15, 45, 'ያን ጊዜ ‘እውነት እላችኋለሁ፤ ከሁሉ ከሚያንሱ ከእነዚህ ለአንዱ ስላላደረጋችሁት ለእኔ ደግሞ አላደረጋችሁትም፤’ ብሎ ይመልስላቸዋል።'),
  ('e7c2a184-af17-5f4d-a924-6294c1296dd7', '5358d306-a9d9-5b3f-aea2-728c48358df2', 'af3cf21f-fa93-5580-a467-bad248a07f28', 16, 46, 'እነዚያም ወደ ዘላለም ቅጣት፥ ጻድቃን ግን ወደ ዘላለም ሕይወት ይሄዳሉ።”'),
  ('4025e421-29d9-507a-a14b-5f583f114113', '1820a8be-33bb-5fc2-a34a-51029a872627', '3681e2e3-ea6a-5d3d-a558-f53dc07ec220', 1, 1, 'ኢየሱስም እነዚህን ቃሎች ሁሉ በፈጸመ ጊዜ፥'),
  ('8d6dc5ac-446f-5b1b-ae29-36d22a2f8717', '1820a8be-33bb-5fc2-a34a-51029a872627', '3681e2e3-ea6a-5d3d-a558-f53dc07ec220', 2, 2, 'ለደቀ መዛሙርቱ “ከሁለት ቀን በኋላ ፋሲካ እንዲሆን ታውቃላችሁ፤ የሰው ልጅም ሊሰቀል አልፎ ይሰጣል፤” አለ።'),
  ('c6d2c384-857b-58e8-ac15-a76fa3d05b3a', '1820a8be-33bb-5fc2-a34a-51029a872627', '3681e2e3-ea6a-5d3d-a558-f53dc07ec220', 3, 3, 'በዚያን ጊዜ የካህናት አለቆች የሕዝብም ሽማግሎች ቀያፋ በሚባለው በሊቀ ካህናቱ ግቢ ተሰበሰቡ፤'),
  ('421128ad-ea57-56cc-a0bd-623fc6178459', '1820a8be-33bb-5fc2-a34a-51029a872627', '3681e2e3-ea6a-5d3d-a558-f53dc07ec220', 4, 4, 'ኢየሱስንም በተንኰል ሊያስይዙት ሊገድሉትም ተማከሩ፤'),
  ('0e9a9471-1208-5d56-af13-433f433d9f78', '1820a8be-33bb-5fc2-a34a-51029a872627', '3681e2e3-ea6a-5d3d-a558-f53dc07ec220', 5, 5, 'ነገር ግን “በሕዝቡ ዘንድ ሁከት እንዳይነሣ በበዓል አይሁን፤” አሉ።'),
  ('1136dab7-bb0d-5e0d-af65-fb40040c2f1d', '1820a8be-33bb-5fc2-a34a-51029a872627', '2ca3ab6d-e7f6-5b5f-add8-d43f9b910ef6', 1, 6, 'ኢየሱስም በቢታንያ በለምጻሙ በስምዖን ቤት ሳለ፥'),
  ('7529c432-3e91-5630-a2f3-3fa2e65167d7', '1820a8be-33bb-5fc2-a34a-51029a872627', '2ca3ab6d-e7f6-5b5f-add8-d43f9b910ef6', 2, 7, 'አንዲት ሴት ዋጋው እጅግ የበዛ ሽቱ የሞላው የአልባስጥሮስ ብልቃጥ ይዛ ወደ እርሱ ቀረበች፤ በማዕድም ተቀምጦ ሳለ በራሱ ላይ አፈሰሰችው።'),
  ('060c00d1-6714-50ae-a682-7e7868733df8', '1820a8be-33bb-5fc2-a34a-51029a872627', '2ca3ab6d-e7f6-5b5f-add8-d43f9b910ef6', 3, 8, 'ደቀ መዛሙርቱም ይህን አይተው ተቈጡና “ይህ ጥፋት ለምንድር ነው?'),
  ('8a98b48f-a189-5709-ae4a-1ae6f53ac0ad', '1820a8be-33bb-5fc2-a34a-51029a872627', '2ca3ab6d-e7f6-5b5f-add8-d43f9b910ef6', 4, 9, 'ይህ በብዙ ዋጋ ተሽጦ ለድሆች ሊሰጥ ይቻል ነበርና፤” አሉ።'),
  ('cda90993-eb94-5ac9-a499-f115a9f20163', '1820a8be-33bb-5fc2-a34a-51029a872627', '2ca3ab6d-e7f6-5b5f-add8-d43f9b910ef6', 5, 10, 'ኢየሱስም ይህን አውቆ እንዲህ አላቸው “መልካም ሥራ ሠርታልኛለችና ሴቲቱንስ ስለ ምን ታደክሙአታላችሁ?'),
  ('f9bd819b-579d-585e-aad2-4c04aa1d2f5c', '1820a8be-33bb-5fc2-a34a-51029a872627', '2ca3ab6d-e7f6-5b5f-add8-d43f9b910ef6', 6, 11, 'ድሆች ሁልጊዜ ከእናንተ ጋር ይኖራሉና፤ እኔ ግን ሁልጊዜ ከእናንተ ጋር አልኖርም፤'),
  ('682481d1-6bd4-5a89-a661-5bc581037cb4', '1820a8be-33bb-5fc2-a34a-51029a872627', '2ca3ab6d-e7f6-5b5f-add8-d43f9b910ef6', 7, 12, 'እርስዋ ይህን ሽቱ በሰውነቴ ላይ አፍስሳ ለመቃብሬ አደረገች።'),
  ('9e8d650b-4bf8-5f86-a78b-1129c4bb5d72', '1820a8be-33bb-5fc2-a34a-51029a872627', '2ca3ab6d-e7f6-5b5f-add8-d43f9b910ef6', 8, 13, 'እውነት እላችኋለሁ፤ ይህ ወንጌል በዓለም ሁሉ በማናቸውም ስፍራ በሚሰበክበት እርስዋ ያደረገችው ደግሞ ለእርስዋ መታሰቢያ እንዲሆን ይነገራል።”'),
  ('65a8b9f2-5789-5e78-a56a-4af8f1038c2a', '1820a8be-33bb-5fc2-a34a-51029a872627', '485ca727-98a5-5eb7-a768-18dfe10c3e84', 1, 14, 'በዚያን ጊዜ የአስቆሮቱ ይሁዳ የሚባለው ከዐሥራ ሁለቱ አንዱ ወደ ካህናት አለቆች ሄዶ'),
  ('40155d9a-e3bd-56b0-a496-6c5446405de9', '1820a8be-33bb-5fc2-a34a-51029a872627', '485ca727-98a5-5eb7-a768-18dfe10c3e84', 2, 15, '“ምን ልትሰጡኝ ትወዳላችሁ እኔም አሳልፌ እሰጣችኋለሁ?” እነርሱም ሠላሳ ብር መዘኑለት።'),
  ('912381fb-97a2-5f9e-a4fc-4e8df26a1fd1', '1820a8be-33bb-5fc2-a34a-51029a872627', '485ca727-98a5-5eb7-a768-18dfe10c3e84', 3, 16, 'ከዚያችም ሰዓት ጀምሮ አሳልፎ ሊሰጠው ምቹ ጊዜ ይሻ ነበር።'),
  ('0d69f6e6-e2aa-5573-a8a0-24c31e97f71d', '1820a8be-33bb-5fc2-a34a-51029a872627', '9af7269d-7eda-59c7-afb9-34af2a7b2c73', 1, 17, 'በቂጣው በዓል በመጀመሪያ ቀን ደቀ መዛሙርቱ ወደ ኢየሱስ ቀርበው “ፋሲካን ትበላ ዘንድ ወዴት ልናሰናዳልህ ትወዳለህ?” አሉት።'),
  ('8c2958eb-27aa-5a2b-ada5-bbfdecf4ba08', '1820a8be-33bb-5fc2-a34a-51029a872627', '9af7269d-7eda-59c7-afb9-34af2a7b2c73', 2, 18, 'እርሱም “ወደ ከተማ ከእገሌ ዘንድ ሄዳችሁ ‘መምህር ጊዜዬ ቀርቦአል፤ ከደቀ መዛሙርቴ ጋር ከአንተ ዘንድ ፋሲካን አደርጋለሁ ይላል’ በሉት፤” አለ።'),
  ('5d9dfcb5-f501-5391-a2ea-499646ec33d9', '1820a8be-33bb-5fc2-a34a-51029a872627', '9af7269d-7eda-59c7-afb9-34af2a7b2c73', 3, 19, 'ደቀ መዛሙርቱም ኢየሱስ እንዳዘዛቸው አደረጉ፤ ፋሲካንም አሰናዱ።'),
  ('d49b5248-811b-5e60-a3b4-6e4a4caecf22', '1820a8be-33bb-5fc2-a34a-51029a872627', '9af7269d-7eda-59c7-afb9-34af2a7b2c73', 4, 20, 'በመሸም ጊዜ ከዐሥራ ሁለቱ ደቀ መዛሙርቱ ጋር በማዕድ ተቀመጠ።'),
  ('a5f8b583-2273-52cf-acbf-f03f82d6efbf', '1820a8be-33bb-5fc2-a34a-51029a872627', '9af7269d-7eda-59c7-afb9-34af2a7b2c73', 5, 21, 'ሲበሉም “እውነት እላችኋለሁ፤ ከእናንተ አንዱ እኔን አሳልፎ ይሰጣል፤” አለ።'),
  ('4768ca98-1442-5fd3-a118-9a43751640a3', '1820a8be-33bb-5fc2-a34a-51029a872627', '9af7269d-7eda-59c7-afb9-34af2a7b2c73', 6, 22, 'እጅግም አዝነው እያንዳንዱ “ጌታ ሆይ! እኔ እሆንን?” ይሉት ጀመር።'),
  ('557a1582-4003-5194-adb7-a92393a53413', '1820a8be-33bb-5fc2-a34a-51029a872627', '9af7269d-7eda-59c7-afb9-34af2a7b2c73', 7, 23, 'እርሱም መልሶ “ከእኔ ጋር እጁን በወጭቱ ያጠለቀ፥ እኔን አሳልፎ የሚሰጥ እርሱ ነው።'),
  ('f2664d5c-9599-5959-a5b4-24808d0f784e', '1820a8be-33bb-5fc2-a34a-51029a872627', '9af7269d-7eda-59c7-afb9-34af2a7b2c73', 8, 24, 'የሰው ልጅስ ስለ እርሱ እንደ ተጻፈ ይሄዳል፤ ነገር ግን የሰው ልጅ አልፎ ለሚሰጥበት ለዚያ ሰው ወዮለት፤ ያ ሰው ባልተወለደ ይሻለው ነበር፤” አለ።'),
  ('e4be82b1-10c4-5eb2-aec4-3a8935e14363', '1820a8be-33bb-5fc2-a34a-51029a872627', '9af7269d-7eda-59c7-afb9-34af2a7b2c73', 9, 25, 'አሳልፎ የሚሰጠው ይሁዳም መልሶ “መምህር ሆይ! እኔ እሆንን?” አለ፤ “አንተ አልህ፤” አለው።'),
  ('e6a55c5f-25eb-5709-a675-383db4b34163', '1820a8be-33bb-5fc2-a34a-51029a872627', '08707d91-4c6f-5b9c-a8b7-f7b79d5898fa', 1, 26, 'ሲበሉም ኢየሱስ ኅብስትን አንሥቶ ባረከ፤ ቈርሶም ለደቀ መዛሙርቱ ሰጠና “እንካችሁ፥ ብሉ፤ ይህ ሥጋዬ ነው፤” አለ።'),
  ('369e9b31-de2d-533e-ae6d-541926f825bb', '1820a8be-33bb-5fc2-a34a-51029a872627', '08707d91-4c6f-5b9c-a8b7-f7b79d5898fa', 2, 27, 'ጽዋንም አንሥቶ አመስግኖም ሰጣቸው፤ እንዲህም አለ፤ “ሁላችሁ ከእርሱ ጠጡ፤'),
  ('a8bc02cb-0cd9-58c1-a085-49ffd5a28d19', '1820a8be-33bb-5fc2-a34a-51029a872627', '08707d91-4c6f-5b9c-a8b7-f7b79d5898fa', 3, 28, 'ስለ ብዙዎች ለኀጢአት ይቅርታ የሚፈስ የአዲስ ኪዳን ደሜ ይህ ነው።'),
  ('3ddfa8af-7921-5195-ae09-af41fd8667b7', '1820a8be-33bb-5fc2-a34a-51029a872627', '08707d91-4c6f-5b9c-a8b7-f7b79d5898fa', 4, 29, 'ነገር ግን እላችኋለሁ፤ በአባቴ መንግሥት ከእናንተ ጋር ከዚህ ከወይን ፍሬ አዲሱን እስከምጠጣበት እስከዚያ ቀን ድረስ ከዛሬ ጀምሬ አልጠጣም።”'),
  ('0a3e5a98-a6ed-5833-a7a5-ada3cf33f213', '1820a8be-33bb-5fc2-a34a-51029a872627', '08707d91-4c6f-5b9c-a8b7-f7b79d5898fa', 5, 30, 'መዝሙርም ከዘመሩ በኋላ ወደ ደብረ ዘይት ወጡ።'),
  ('a55ea3f1-f539-58a9-a5fd-91154044ba7e', '1820a8be-33bb-5fc2-a34a-51029a872627', '5cbb8a43-18ce-5215-a25c-ec7683307b91', 1, 31, 'በዚያን ጊዜ ኢየሱስ “በዚች ሌሊት ሁላችሁ በእኔ ትሰናከላላችሁ፤ ‘እረኛውን እመታለሁ፤ የመንጋውም በጎች ይበተናሉ፤’ የሚል ተጽፎአልና፤'),
  ('0c9e35af-b471-59d3-a2b1-7774ce9b79d7', '1820a8be-33bb-5fc2-a34a-51029a872627', '5cbb8a43-18ce-5215-a25c-ec7683307b91', 2, 32, 'ከተነሣሁ በኋላ ግን ወደ ገሊላ እቀድማችኋለሁ፤” አላቸው።'),
  ('89ca9f94-4c5d-513f-a358-b1b3df22796c', '1820a8be-33bb-5fc2-a34a-51029a872627', '5cbb8a43-18ce-5215-a25c-ec7683307b91', 3, 33, 'ጴጥሮስም መልሶ “ሁሉም በአንተ ቢሰናከሉ እኔ ከቶ አልሰናከልም፤” አለው።'),
  ('efd9db20-a42d-57fc-a256-4f749f005269', '1820a8be-33bb-5fc2-a34a-51029a872627', '5cbb8a43-18ce-5215-a25c-ec7683307b91', 4, 34, 'ኢየሱስም “እውነት እልሃለሁ፤ በዚች ሌሊት ዶሮ ሳይጮኽ ሦስት ጊዜ ትክደኛለህ፤” አለው።'),
  ('506a5d62-318f-51a9-a3fc-6bfcccc523e8', '1820a8be-33bb-5fc2-a34a-51029a872627', '5cbb8a43-18ce-5215-a25c-ec7683307b91', 5, 35, 'ጴጥሮስም “ከአንተ ጋር መሞት እንኳ የሚያስፈልገኝ ቢሆን፥ ከቶ አልክድህም፤” አለው። ደቀ መዛሙርቱ ሁሉ ደግሞ እንደዚሁ አሉ።'),
  ('693b3603-5358-5d73-a23b-b89022c78fe1', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 1, 36, 'በዚያን ጊዜ ኢየሱስ ከእነርሱ ጋር ጌቴሴማኒ ወደምትባል ስፍራ መጣ፤ ደቀ መዛሙርቱንም “ወዲያ ሄጄ ስጸልይ ሳለ በዚህ ተቀመጡ፤” አላቸው።'),
  ('db5c4eb0-265a-575f-add3-d088acbbd077', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 2, 37, 'ጴጥሮስንም ሁለቱንም የዘብዴዎስን ልጆች ወስዶ ሊያዝን ሊተክዝም ጀመር።'),
  ('ab9755f9-4667-560b-a919-fcc64584b20e', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 3, 38, '“ነፍሴ እስከ ሞት ድረስ እጅግ አዘነች፤ በዚህ ቆዩ፤ ከእኔም ጋር ትጉ፤” አላቸው።'),
  ('f0ea94a4-ec2f-552c-a8f4-5a17d08c0cfb', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 4, 39, 'ጥቂትም ወደ ፊት እልፍ ብሎ በፊቱ ወደቀና ሲጸልይ “አባቴ! ቢቻልስ፥ ይህች ጽዋ ከእኔ ትለፍ፤ ነገር ግን አንተ እንደምትወድ ይሁን እንጂ እኔ እንደምወድ አይሁን፤” አለ።'),
  ('12ef198b-a90e-5c84-aa20-f6af787b6b9e', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 5, 40, 'ወደ ደቀ መዛሙርቱም መጣ፤ ተኝተውም አገኛቸውና ጴጥሮስን “እንዲሁም ከእኔ ጋር አንዲት ሰዓት እንኳ ልትተጉ አልቻላችሁምን?'),
  ('28e8cfeb-4e1a-550b-a948-602556645657', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 6, 41, 'ወደ ፈተና እንዳትገቡ ትጉና ጸልዩ፤ መንፈስስ ተዘጋጅታለች፤ ሥጋ ግን ደካማ ነው፤” አለው።'),
  ('89fc4b0f-27cc-55c7-afc7-f75b1125bb1c', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 7, 42, 'ደግሞ ሁለተኛ ሄዶ ጸለየና “አባቴ! ይህች ጽዋ ሳልጠጣት ታልፍ ዘንድ የማይቻል እንደ ሆነ፥ ፈቃድህ ትሁን፤” አለ።'),
  ('f7ba85c0-cf59-577b-a091-30fa423d38f6', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 8, 43, 'ደግሞም መጥቶ ዐይኖቻቸው በእንቅልፍ ከብደው ነበርና ተኝተው አገኛቸው።'),
  ('2def4124-5c9a-520c-ac05-95db6b813819', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 9, 44, 'ደግሞም ትቶአቸው ሄደ፤ ሦስተኛም ያንኑ ቃል ደግሞ ጸለየ።'),
  ('0a23fe7d-bc49-5549-a31e-bd7cf679b68d', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 10, 45, 'ከዚያ ወዲያ ወደ ደቀ መዛሙርቱ መጥቶ “እንግዲህስ ተኙ፤ ዕረፉም፤ እነሆ፥ ሰዓቲቱ ቀርባለች፤ የሰው ልጅም በኀጢአተኞች እጅ አልፎ ይሰጣል።'),
  ('60a8257e-bf66-58eb-a6c0-11c3716de593', '1820a8be-33bb-5fc2-a34a-51029a872627', '065f1b08-2e32-5ed4-a2bc-329a37cb0d20', 11, 46, 'ተነሡ፤ እንሂድ፤ እነሆ፥ አሳልፎ የሚሰጠኝ ቀርቦአል፤” አላቸው።'),
  ('746c5214-44cf-5980-a5e5-dfedcc667c93', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 1, 47, 'ይህንም ገና ሲናገር፥ እነሆ፥ ከዐሥራ ሁለቱ አንዱ ይሁዳ መጣ፤ ከእርሱም ጋር ብዙ ሕዝብ ሰይፍና ጐመድ ይዘው ከካህናት አለቆችና ከሕዝቡ ሽማግሎች ዘንድ መጡ።'),
  ('af9a9607-c232-5264-abe5-306f127a4936', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 2, 48, 'አሳልፎ የሚሰጠውም “የምስመው እርሱ ነው፤ ያዙት፤” ብሎ ምልክት ሰጥቶአቸው ነበር።'),
  ('a3aff9fc-a52f-586b-afe9-7a1d804d1a73', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 3, 49, 'ወዲያውም ወደ ኢየሱስ ቀረበና “መምህር ሆይ! ሰላም ለአንተ ይሁን፤” ብሎ ሳመው።'),
  ('68e5963e-8f52-5aef-a011-d530fff7bc26', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 4, 50, 'ኢየሱስም “ወዳጄ ሆይ! ለምን ነገር መጣህ?” አለው። በዚያን ጊዜ ቀረቡ፤ እጃቸውንም በኢየሱስ ላይ ጭነው ያዙት።'),
  ('7d7e01d0-4c44-52cd-a848-42b905c77cd3', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 5, 51, 'እነሆም፥ ከኢየሱስ ጋር ከነበሩት አንዱ እጁን ዘርግቶ ሰይፉን መዘዘና የሊቀ ካህናቱን ባሪያ መትቶ ጆሮውን ቈረጠው።'),
  ('e9bba189-5db5-5dae-a326-187b2e2101fe', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 6, 52, 'በዚያን ጊዜ ኢየሱስ እንዲህ አለው “ሰይፍ የሚያነሡ ሁሉ በሰይፍ ይጠፋሉና ሰይፍህን ወደ ስፍራው መልስ።'),
  ('6a87b1ea-7a53-5318-a672-095fbaf58ef1', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 7, 53, 'ወይስ አባቴን እንድለምን እርሱም አሁን ከዐሥራ ሁለት ጭፍሮች የሚበዙ መላእክት እንዲሰድልኝ የማይችል ይመስልሃልን?'),
  ('51598491-7212-5b3a-aaff-e732ef3ccfbe', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 8, 54, 'እንዲህ ከሆነስ ‘እንደዚህ ሊሆን ይገባል፤’ የሚሉ መጻሕፍት እንዴት ይፈጸማሉ?”'),
  ('0bd55602-2195-502b-a395-75caace1ed4f', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 9, 55, 'በዚያን ሰዓት ኢየሱስ ለሕዝቡ “ወንበዴን እንደምትይዙ ሰይፍና ጐመድ ይዛችሁ ልትይዙኝ ወጣችሁን? በመቅደስ ዕለት ዕለት እያስተማርሁ ከእናንተ ጋር ስቀመጥ ሳለሁ አልያዛችሁኝም።'),
  ('7d3d87f6-074f-578f-aee8-f6fdd3310d51', '1820a8be-33bb-5fc2-a34a-51029a872627', '43f33fb6-f319-5366-a783-1e13e5f50831', 10, 56, 'ነገር ግን ይህ ሁሉ የሆነ የነቢያት መጻሕፍት ይፈጸሙ ዘንድ ነው፤” አለ። በዚያን ጊዜ ደቀ መዛሙርቱ ሁሉ ትተውት ሸሹ።'),
  ('3cbae666-9a5f-5c59-a182-58411e7fece9', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 1, 57, 'ኢየሱስን የያዙትም ጻፎችና ሽማግሎች ወደ ተከማቹበት ወደ ሊቀ ካህናቱ ወደ ቀያፋ ወሰዱት።'),
  ('acf14eea-e84c-50f9-a6cd-93ae426c8387', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 2, 58, 'ጴጥሮስ ግን እስከ ሊቀ ካህናቱ ግቢ ድረስ ሩቅ ሆኖ ተከተለው፤ የነገሩንም ፍጻሜ ያይ ዘንድ ወደ ውስጥ ገብቶ ከሎሌዎቹ ጋር ተቀመጠ።'),
  ('f2b87683-71c1-5e69-a0b8-27085b88279b', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 3, 59, 'የካህናት አለቆችና ሽማግሎች ሸንጎውም ሁሉ እንዲገድሉት በኢየሱስ ላይ የሐሰት ምስክር ይፈልጉ ነበር፤ አላገኙም፤'),
  ('a64cbe2f-7456-5622-af97-1c79edffac9d', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 4, 60, 'ብዙም የሐሰት ምስክሮች ምንም ቢቀርቡ አላገኙም።'),
  ('5199c4a3-8a7f-5216-acce-8be07c3d211f', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 5, 61, 'በኋላም ሁለት ቀርበው “ይህ ሰው ‘የእግዚአብሔርን ቤተ መቅደስ አፍርሼ በሦስት ቀን ልሠራው እችላለሁ፤’ ብሎአል፤” አሉ።'),
  ('878d4b43-7333-510e-a027-1e258cf3477f', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 6, 62, 'ሊቀ ካህናቱም ተነሥቶ “እነዚህ ለሚመሰክሩብህ አንድ ስንኳ አትመልስምን?” አለው።'),
  ('847c434c-298f-58f5-a393-c95cd2076416', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 7, 63, 'ኢየሱስ ግን ዝም አለ። ሊቀ ካህናቱም “አንተ የእግዚአብሔር ልጅ ክርስቶስ የሆንህ እንደ ሆነ እንድትነግረን በሕያው እግዚአብሔር አምልሃለሁ፤” አለው።'),
  ('d90dadc1-30b4-539d-a1a0-2e55c9a597b3', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 8, 64, 'ኢየሱስም “አንተ አልህ፤ ነገር ግን እላችኋለሁ፥ ከእንግዲህ ወዲህ የሰው ልጅ በኀይል ቀኝ ሲቀመጥ በሰማይም ደመና ሲመጣ ታያላችሁ፤” አለው።'),
  ('36a5ef26-9b9f-52c6-a552-9b00d0f45793', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 9, 65, 'በዚያን ጊዜ ሊቀ ካህናቱ ልብሱን ቀዶ “ተሳድቦአል፤ እንግዲህ ወዲህ ምስክሮች ስለ ምን ያስፈልገናል? እነሆ፥ ስድቡን አሁን ሰምታችኋል፤ ምን ይመስላችኋል?” አለ።'),
  ('43b340e0-c125-5f7f-ac64-83b122543261', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 10, 66, 'እነርሱም “ሞት ይገባዋል!” ብለው መለሱ።'),
  ('edcc530d-926b-512d-a875-d4789df35c0b', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 11, 67, 'በዚያን ጊዜ በፊቱ ተፉበት፤ ጐሰሙትም፤ ሌሎችም በጥፊ መትተው “ክርስቶስ ሆይ! በጥፊ የመታህ ማን ነው?'),
  ('b84c3d37-229c-56eb-a19e-fcc963cf1335', '1820a8be-33bb-5fc2-a34a-51029a872627', 'fcbe4662-fca6-5399-a9dd-0e3a43d4228d', 12, 68, 'ትንቢት ተናገርልን፤” አሉ።'),
  ('a2df9851-0758-55f1-a7d3-b6e19ae28a3d', '1820a8be-33bb-5fc2-a34a-51029a872627', '1e9d4a5d-224c-5627-a98e-1155509a4cbc', 1, 69, 'ጴጥሮስም ከቤት ውጭ በአጥሩ ግቢ ተቀምጦ ነበር፤ አንዲት ገረድም ወደ እርሱ ቀርባ “አንተ ደግሞ ከገሊላው ከኢየሱስ ጋር ነበርህ፤” አለችው።'),
  ('5987325e-4ef1-5546-a5c1-a627a298beb4', '1820a8be-33bb-5fc2-a34a-51029a872627', '1e9d4a5d-224c-5627-a98e-1155509a4cbc', 2, 70, 'እርሱ ግን “የምትዪውን አላውቀውም፤” ብሎ በሁሉ ፊት ካደ።'),
  ('a3391238-d43c-53b5-ae58-3cad32e0cf49', '1820a8be-33bb-5fc2-a34a-51029a872627', '1e9d4a5d-224c-5627-a98e-1155509a4cbc', 3, 71, 'ወደ በሩም ሲወጣ ሌላይቱ አየችውና በዚያ ላሉት “ይህ ደግሞ ከናዝሬቱ ከኢየሱስ ጋር ነበረ፤” አለች።'),
  ('86859dba-4e27-54ec-ae69-16c5d9089b72', '1820a8be-33bb-5fc2-a34a-51029a872627', '1e9d4a5d-224c-5627-a98e-1155509a4cbc', 4, 72, 'ዳግመኛም ሲምል “ሰውየውን አላውቀውም፤” ብሎ ካደ።'),
  ('9b9defae-aad9-527e-a77a-6ce3ba32b071', '1820a8be-33bb-5fc2-a34a-51029a872627', '1e9d4a5d-224c-5627-a98e-1155509a4cbc', 5, 73, 'ጥቂትም ቈይተው በዚያ ቆመው የነበሩ ቀርበው ጴጥሮስን “አነጋገርህ ይገልጥሃልና፥ በእውነት አንተ ደግሞ ከእነርሱ ወገን ነህ፤” አሉት።'),
  ('640aa373-c831-5a80-ade1-6cfe3fe80083', '1820a8be-33bb-5fc2-a34a-51029a872627', '1e9d4a5d-224c-5627-a98e-1155509a4cbc', 6, 74, 'በዚያን ጊዜ “ሰውየውን አላውቀውም፤” ብሎ ራሱን ሊረግምና ሊምል ጀመረ። ወዲያውም ዶሮ ጮኸ።'),
  ('d4389813-9b21-5aa4-ae48-efd457fa6e80', '1820a8be-33bb-5fc2-a34a-51029a872627', '1e9d4a5d-224c-5627-a98e-1155509a4cbc', 7, 75, 'ጴጥሮስም “ዶሮ ሳይጮኽ ሦስት ጊዜ ትክደኛለህ፤” ያለው የኢየሱስ ቃል ትዝ አለው፤ ወደ ውጭም ወጥቶ መራራ ልቅሶ አለቀሰ።'),
  ('2a6f2a7a-528f-5479-ac7c-32b987a6e6dc', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '6d6e431e-ab2e-516d-ae61-939e71573ce9', 1, 1, 'ሲነጋም የካህናት አለቆችና የሕዝቡ ሽማግሎች ሁሉ ሊገድሉት በኢየሱስ ላይ ተማከሩ፤'),
  ('b44c4a28-f12f-56d0-a119-da1c854540c5', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '6d6e431e-ab2e-516d-ae61-939e71573ce9', 2, 2, 'አስረውም ወሰዱት፤ ለገዢው ለጴንጤናዊው ጲላጦስም አሳልፈው ሰጡት።'),
  ('155e4bc3-22f0-5481-a5c2-2998859bb768', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '0292a8d9-712b-57ed-a525-3a994ffb74dc', 1, 3, 'በዚያን ጊዜ አሳልፎ የሰጠው ይሁዳ እንደ ተፈረደበት አይቶ ተጸጸተ፤ ሠላሳውንም ብር ለካህናት አለቆችና ለሽማግሎች መልሶ'),
  ('9aac0c62-049b-57b4-ab2b-f46aa7e7cdce', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '0292a8d9-712b-57ed-a525-3a994ffb74dc', 2, 4, '“ንጹሕ ደም አሳልፌ በመስጠቴ በድያለሁ፤” አለ። እነርሱ ግን “እኛስ ምን አግዶን? አንተው ተጠንቀቅ፤” አሉ።'),
  ('549dee00-eba1-58f9-aa22-3fbbd7538d20', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '0292a8d9-712b-57ed-a525-3a994ffb74dc', 3, 5, 'ብሩንም በቤተ መቅደስ ጥሎ ሄደና ታንቆ ሞተ።'),
  ('79062fea-8ed3-5b51-aee8-2fb543c76a9a', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '0292a8d9-712b-57ed-a525-3a994ffb74dc', 4, 6, 'የካህናት አለቆችም ብሩን አንሥተው “የደም ዋጋ ነውና ወደ መባ ልንጨምረው አልተፈቀደም፤” አሉ።'),
  ('a20b509e-3873-5557-a67f-95b78e8426b6', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '0292a8d9-712b-57ed-a525-3a994ffb74dc', 5, 7, 'ተማክረውም የሸክላ ሠሪውን መሬት ለእንግዶች መቃብር ገዙበት።'),
  ('befc16d0-40f7-5b10-a68b-cca104587e0a', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '0292a8d9-712b-57ed-a525-3a994ffb74dc', 6, 8, 'ስለዚህ ያ መሬት እስከ ዛሬ ድረስ “የደም መሬት” ተባለ።'),
  ('100bc532-0e2a-5e30-a068-6ee279917a42', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '0292a8d9-712b-57ed-a525-3a994ffb74dc', 7, 9, 'በዚያን ጊዜ በነቢዩ በኤርምያስ የተባለው'),
  ('00eaac65-495e-548c-ac39-b7faf981c96a', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '0292a8d9-712b-57ed-a525-3a994ffb74dc', 8, 10, 'ጌታም እንዳዘዘኝ ስለ ሸክላ ሠሪ መሬት ሰጡት።”'),
  ('1d26a744-cf6a-51a4-a55d-f970661998e7', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', 'fe72cf81-b3b6-527c-a04e-88c29f96e3ad', 1, 11, 'ኢየሱስም በገዢው ፊት ቆመ፤ ገዢውም “የአይሁድ ንጉሥ አንተ ነህን?” ብሎ ጠየቀው፤ ኢየሱስም “አንተ አልህ፤” አለው።'),
  ('36e212e2-93bb-5ea0-abb3-ad5d98e279dd', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', 'fe72cf81-b3b6-527c-a04e-88c29f96e3ad', 2, 12, 'የካህናት አለቆችም ሽማግሎችም ሲከሱት ምንም አልመለሰም።'),
  ('048bd2ed-00fd-593b-ab01-519120580d0c', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', 'fe72cf81-b3b6-527c-a04e-88c29f96e3ad', 3, 13, 'በዚያን ጊዜ ጲላጦስ “ስንት ያህል እንዲመሰክሩብህ አትሰማምን?” አለው።'),
  ('a3cc807a-0381-5476-a9bc-707b22729db9', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', 'fe72cf81-b3b6-527c-a04e-88c29f96e3ad', 4, 14, 'ገዢውም እጅግ እስኪደነቅ ድረስ አንዲት ቃል ስንኳ አልመለሰለትም።'),
  ('6cd7841e-e00a-5096-a48c-9059225e57ee', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 1, 15, 'በዚያም በዓል ሕዝቡ የወደዱትን አንድ እስረኛ ሊፈታላቸው ለገዢው ልማድ ነበረው።'),
  ('f663d7e9-edd5-588b-abac-fef59d6baf7c', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 2, 16, 'በዚያን ጊዜም በርባን የሚባል በጣም የታወቀ እስረኛ ነበራቸው።'),
  ('ed730d2f-4854-51cd-ae3b-53d8b8e29719', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 3, 17, 'እንግዲህ እነርሱ ተሰብስበው ሳሉ ጲላጦስ “በርባንን ወይስ ክርስቶስ የተባለውን ኢየሱስን ማንኛውን ልፈታላችሁ ትወዳላችሁ?” አላቸው፤'),
  ('60d810cf-76da-5da1-aea4-557245257bf5', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 4, 18, 'በቅንዓት አሳልፈው እንደ ሰጡት ያውቅ ነበርና።'),
  ('d2a38e3b-d5da-53f8-ac2a-9b628a13620a', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 5, 19, 'እርሱም በፍርድ ወንበር ተቀምጦ ሳለ ሚስቱ “ስለ እርሱ ዛሬ በሕልም እጅግ መከራ ተቀብያለሁና በዚያ ጻድቅ ሰው ምንም አታድርግ፤” ብላ ላከችበት።'),
  ('317c1473-c981-53a0-a89e-baee0ee494fc', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 6, 20, 'የካህናት አለቆችና ሽማግሎች ግን በርባንን እንዲለምኑ ኢየሱስን ግን እንዲያጠፉ ሕዝቡን አባበሉ።'),
  ('6615219e-bf74-5209-a531-49ca4759d499', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 7, 21, 'ገዢውም መልሶ “ከሁለቱ ማንኛውን ልፈታላችሁ ትወዳላችሁ?” አላቸው፤ እነርሱም “በርባንን” አሉ።'),
  ('92f4a24e-5d51-548b-a2f7-41e58f7f688c', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 8, 22, 'ጲላጦስ “ክርስቶስ የተባለውን ኢየሱስን እንግዲህ ምን ላድርገው?” አላቸው፤ ሁሉም “ይሰቀል!” አሉ።'),
  ('71c2c559-3572-55ec-a0d4-16ccc7f1c4c0', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 9, 23, 'ገዢውም “ምን ነው? ያደረገው ክፋት ምንድር ነው?” አለ፤ እነርሱ ግን “ይሰቀል!” እያሉ ጩኸት አበዙ።'),
  ('91519bf8-e210-5dd5-a5f5-ac37dfffaf93', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 10, 24, 'ጲላጦስም ሁከት እንዲጀመር እንጂ አንዳች እንዳይረባ ባየ ጊዜ፥ ውሃ አንሥቶ “እኔ ከዚህ ጻድቅ ሰው ደም ንጹሕ ነኝ፤ እናንተ ተጠንቀቁ፤” ሲል በሕዝቡ ፊት እጁን ታጠበ።'),
  ('d4b8d209-60ea-5c0b-a8b1-6d0ebfb124b6', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 11, 25, 'ሕዝቡም ሁሉ መልሰው “ደሙ በእኛና በልጆቻችን ላይ ይሁን፤” አሉ።'),
  ('49a9db75-ba0f-54f7-a498-ff6ecb662b2a', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '2435909a-cb9e-589b-a822-4d6953cdb3c4', 12, 26, 'በዚያን ጊዜ በርባንን ፈታላቸው፤ ኢየሱስን ግን ገርፎ ሊሰቀል አሳልፎ ሰጠ።'),
  ('3ad165a4-56a2-5dd5-a72c-025bc9bb9575', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '8a1852d6-90ef-5cd7-a899-962df7f02289', 1, 27, 'በዚያን ጊዜ የገዢው ወታደሮች ኢየሱስን ወደ ገዢው ግቢ ውስጥ ወሰዱት፤ ጭፍራውንም ሁሉ ወደ እርሱ አከማቹ።'),
  ('54b5e3dc-9e17-598b-a7a9-041b83b01772', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '8a1852d6-90ef-5cd7-a899-962df7f02289', 2, 28, 'ልብሱንም ገፈው ቀይ ልብስ አለበሱት፤'),
  ('0639ee1c-26a3-5669-afe0-3c6c1ea33f14', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '8a1852d6-90ef-5cd7-a899-962df7f02289', 3, 29, 'ከእሾህም አክሊል ጐንጕነው በራሱ ላይ፥ በቀኝ እጁም መቃ አኖሩ፤ በፊቱም ተንበርክከው “የአይሁድ ንጉሥ ሆይ! ሰላም ለአንተ ይሁን፤” እያሉ ዘበቱበት፤'),
  ('5f882880-1b9d-5691-a066-9d05f683b6de', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '8a1852d6-90ef-5cd7-a899-962df7f02289', 4, 30, 'ተፉበትም፤ መቃውንም ይዘው ራሱን መቱት።'),
  ('edd3fcec-511e-5e23-a65c-f796a55feee0', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '8a1852d6-90ef-5cd7-a899-962df7f02289', 5, 31, 'ከዘበቱበትም በኋላ ቀዩን ልብስ ገፈፉት፤ ልብሱንም አለበሱት፤ ሊሰቅሉትም ወሰዱት።'),
  ('2a01f97a-8abb-5117-a938-ed64d4e01666', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 1, 32, 'ሲወጡም ስምዖን የተባለው የቀሬናን ሰው አገኙ፤ እርሱንም መስቀሉን ይሸከም ዘንድ አስገደዱት።'),
  ('327c4d09-73fb-5493-a218-d03085ae4c3c', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 2, 33, 'ትርጓሜው የራስ ቅል ስፍራ ወደሚሆን ጎልጎታ ወደሚባለው ስፍራ በደረሱ ጊዜም፥'),
  ('d6bc7a66-1b60-54dd-af3d-73beab5d810e', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 3, 34, 'በሐሞት የተደባለቀ የወይን ጠጅ ሊጠጣ አቀረቡለት፤ ቀምሶም ሊጠጣው አልወደደም።'),
  ('7dd976d8-cd47-5e1a-ae20-c48e7277acb5', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 4, 35, 'ከሰቀሉትም በኋላ ልብሱን ዕጣ ጥለው ተካፈሉ፤'),
  ('ea4d7e42-9b48-5985-abd1-ab96af151ae1', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 5, 36, 'በዚያም ተቀምጠው ይጠብቁት ነበር።'),
  ('4d9cfee2-0385-5daa-a723-291fda3f7590', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 6, 37, '“ይህ ኢየሱስ የአይሁድ ንጉሥ ነው፤” የሚል የክሱን ጽሕፈት ከራሱ በላይ አኖሩ።'),
  ('c34bbba1-588c-5db2-af77-28dbb91489bc', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 7, 38, 'በዚያን ጊዜ ሁለት ወንበዴዎች አንዱ በቀኝ አንዱም በግራ ከእርሱ ጋር ተሰቀሉ።'),
  ('aab58bce-0bbb-53e8-a501-6eb97195681d', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 8, 39, 'የሚያልፉትም ራሳቸውን እየነቀነቁ ይሰድቡት ነበር፤'),
  ('5381a2a8-a3e0-5400-a188-1803173f5d26', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 9, 40, '“ቤተ መቅደስን የምታፈርስ በሦስት ቀንም የምትሠራው፥ ራስህን አድን፤ የእግዚአብሔር ልጅስ ከሆንህ ከመስቀል ውረድ፤” አሉት።'),
  ('ddf74d57-6514-589f-a23d-72bc4f4715c3', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 10, 41, 'እንዲሁም ደግሞ የካህናት አለቆች ከጻፎችና ከሽማግሎች ጋር እየዘበቱበት እንዲህ አሉ'),
  ('0b7ce267-8bf7-5771-a5c9-41963190280c', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 11, 42, '“ሌሎችን አዳነ፤ ራሱን ሊያድን አይችልም፤ የእስራኤል ንጉሥ ከሆነ፥ አሁን ከመስቀል ይውረድ፤ እኛም እናምንበታለን።'),
  ('ab48e3f5-0e89-5c6f-a22d-6fcf5c091290', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 12, 43, 'በእግዚአብሔር ታምኖአል፤ ‘የእግዚአብሔር ልጅ ነኝ፤’ ብሎአልና ከወደደውስ አሁን ያድነው።”'),
  ('f7b75ba6-33ae-521e-a813-220eb8107c09', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5ac049c6-9ba0-5089-aeaa-dc71efad0268', 13, 44, 'ከእርሱ ጋር የተሰቀሉት ወንበዴዎች ደግሞ ያንኑ እያሉ ይነቅፉት ነበር።'),
  ('48b392a8-01d2-5f06-adce-09af68bfe7dd', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 1, 45, 'ከስድስት ሰዓትም ጀምሮ እስከ ዘጠኝ ሰዓት ድረስ በምድር ሁሉ ላይ ጨለማ ሆነ።'),
  ('47bbe944-9c18-5d20-a4e7-d0981d681f81', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 2, 46, 'በዘጠኝ ሰዓትም ኢየሱስ “ኤሎሄ ኤሎሄ ላማ ሰበቅታኒ?” ብሎ በታላቅ ድምፅ ጮኸ። ይህም “አምላኬ አምላኬ፥ ስለ ምን ተውኸኝ?” ማለት ነው።'),
  ('cdd115e0-e972-50ef-aeb7-42bd2ecc52d0', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 3, 47, 'በዚያም ከቆሙት ሰዎች ሰምተው “ይህስ ኤልያስን ይጠራል፤” አሉ።'),
  ('e1d7ed23-19f6-51e8-a4b7-19ed4d1d1952', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 4, 48, 'ወዲያውም ከእነርሱ አንዱ ሮጠ፤ ሰፍነግም ይዞ ሆምጣጤ ሞላበት፤ በመቃም አድርጎ አጠጣው።'),
  ('2292130b-be4f-5c4e-ae0d-5beb17b5acaa', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 5, 49, 'ሌሎቹ ግን “ተው፤ ኤልያስ መጥቶ ያድነው እንደ ሆነ እንይ፤” አሉ።'),
  ('03699f83-04c2-52e4-a4ba-eccb56d6bdfd', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 6, 50, 'ኢየሱስም ሁለተኛ በታላቅ ድምፅ ጮኾ ነፍሱን ተወ።'),
  ('0824cfb6-8da5-54e9-ae16-dd5c7cb875e8', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 7, 51, 'እነሆም፥ የቤተ መቅደስ መጋረጃ ከላይ እስከ ታች ከሁለት ተቀደደ፤ ምድርም ተናወጠች፤ ዐለቶችም ተሰነጠቁ፤'),
  ('87f16303-2946-59e6-ab18-d9c56e0ebcfc', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 8, 52, 'መቃብሮችም ተከፈቱ፤ ተኝተው ከነበሩትም ከቅዱሳን ብዙ ሥጋዎች ተነሡ፤'),
  ('167e3e2a-c846-56dd-a542-b3c09379e614', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 9, 53, 'ከትንሣኤውም በኋላ ከመቃብሮች ወጥተው ወደ ቅድስት ከተማ ገቡና ለብዙዎች ታዩ።'),
  ('73e091b6-6367-561c-a8aa-648f045692ac', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 10, 54, 'የመቶ አለቃም ከእርሱም ጋር ኢየሱስን የሚጠብቁ መናወጡንና የሆነውን ነገር አይተው “ይህ በእውነት የእግዚአብሔር ልጅ ነበረ፤” ብለው እጅግ ፈሩ።'),
  ('9fe752df-bda5-5bb9-a7f5-0236c6f0d039', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 11, 55, 'ኢየሱስን እያገለገሉ ከገሊላ የተከተሉት ብዙ ሴቶች በሩቅ ሆነው ሲመለከቱ በዚያ ነበሩ፤'),
  ('6fd754c9-8567-5225-a5bd-0045165317ab', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '5d54bd03-2605-544c-a924-d0ffe436e124', 12, 56, 'ከእነርሱም መግደላዊት ማርያምና የያዕቆብና የዮሳ እናት ማርያም የዘብዴዎስም የልጆቹ እናት ነበሩ።'),
  ('8b2d7df8-86b4-5e29-a6f8-20f87318c77c', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '851737ba-026d-5cee-ac0d-5e07461202db', 1, 57, 'በመሸም ጊዜ ዮሴፍ የተባለው ባለ ጠጋ ሰው ከአርማትያስ መጣ፤ እርሱም ደግሞ የኢየሱስ ደቀ መዝሙር ነበረ፤'),
  ('86359ee6-8682-50a9-aee0-2c02c5bd4638', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '851737ba-026d-5cee-ac0d-5e07461202db', 2, 58, 'ይኸውም ወደ ጲላጦስ ቀርቦ የኢየሱስን ሥጋ ለመነው።'),
  ('34ed0483-32e8-5e78-a087-7bff2b272d69', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '851737ba-026d-5cee-ac0d-5e07461202db', 3, 59, 'ጲላጦስም እንዲሰጡት አዘዘ። ዮሴፍም ሥጋውን ይዞ በንጹሕ በፍታ ከፈነው፤')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0cad1fac-3e79-5c61-ae27-e5de0940116a', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '851737ba-026d-5cee-ac0d-5e07461202db', 4, 60, 'ከዐለት በወቀረው በአዲሱ መቃብርም አኖረው፤ በመቃብሩም ደጃፍ ታላቅ ድንጋይ አንከባሎ ሄደ።'),
  ('ef7917ec-7265-5034-a1de-5247208aa974', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '851737ba-026d-5cee-ac0d-5e07461202db', 5, 61, 'መግደላዊት ማርያምም ሁለተኛይቱም ማርያም በመቃብሩ አንጻር ተቀምጠው በዚያ ነበሩ።'),
  ('1f8f80d5-75f9-5014-a118-7cba444dabd4', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '9bc6765b-a23b-58d2-af6f-8a576f07af2b', 1, 62, 'በማግሥቱም ከመዘጋጀት በኋላ በሚሆነው ቀን፥ የካህናት አለቆችና ፈሪሳውያን ወደ ጲላጦስ ተሰበሰቡና'),
  ('e76c6570-2b04-56c1-a8a5-1be6597d44b8', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '9bc6765b-a23b-58d2-af6f-8a576f07af2b', 2, 63, '“ጌታ ሆይ! ያ አሳች በሕይወቱ ገና ሳለ ‘ከሦስት ቀን በኋላ እነሣለሁ፤’ እንዳለ ትዝ አለን።'),
  ('63fdbf19-b51f-513b-a691-7bbc794a0dc3', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '9bc6765b-a23b-58d2-af6f-8a576f07af2b', 3, 64, 'እንግዲህ ደቀ መዛሙርቱ መጥተው በሌሊት እንዳይሰርቁት ለሕዝቡም ‘ከሙታን ተነሣ፤’ እንዳይሉ፥ የኋለኛይቱ ስሕተት ከፊተኛይቱ ይልቅ የከፋች ትሆናለችና መቃብሩ እስከ ሦስተኛ ቀን ድረስ እንዲጠበቅ እዘዝ፤” አሉት።'),
  ('1fea674b-e0c8-5212-af30-f8921dffb690', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '9bc6765b-a23b-58d2-af6f-8a576f07af2b', 4, 65, 'ጲላጦስም “ጠባቆች አሉአችሁ፤ ሄዳችሁ እንዳወቃችሁ አስጠብቁ፤” አላቸው።'),
  ('666d5940-3d07-5f46-a027-4f75b151da32', '96e698b4-2728-5b4d-ac0c-ef34aaa36492', '9bc6765b-a23b-58d2-af6f-8a576f07af2b', 5, 66, 'እነርሱም ሄደው ከጠባቆች ጋር ድንጋዩን አትመው መቃብሩን አስጠበቁ።'),
  ('f3920213-8b28-5c4a-a741-732fa46b3b21', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 1, 1, 'በሰንበትም መጨረሻ መጀመሪያው ቀን ሲነጋ መግደላዊት ማርያምና ሁለተኛይቱ ማርያም መቃብሩን ሊያዩ መጡ።'),
  ('9da8a6d1-cd0f-5c77-a160-ac75a98f914d', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 2, 2, 'እነሆም፥ የጌታ መልአክ ከሰማይ ስለ ወረደ ታላቅ የምድር መናወጥ ሆነ፤ ቀርቦም ድንጋዩን አንከባሎ በላዩ ተቀመጠ።'),
  ('12e1a5ca-6e56-5277-a17f-5bb92f01abc9', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 3, 3, 'መልኩም እንደ መብረቅ ልብሱም እንደ በረዶ ነጭ ነበረ።'),
  ('33885e17-6a06-5c00-a7f1-38468cf592ef', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 4, 4, 'ጠባቆቹም እርሱን ከመፍራት የተነሣ ተናወጡ፤ እንደ ሞቱም ሆኑ።'),
  ('ae8797e9-255b-5a9b-acca-01b6d7f923bd', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 5, 5, 'መልአኩም መልሶ ሴቶቹን አላቸው “እናንተስ አትፍሩ የተሰቀለውን ኢየሱስን እንድትሹ አውቃለሁና፤'),
  ('7827dd3e-b5a2-53f1-a1ba-783378b65b05', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 6, 6, 'እንደ ተናገረ ተነሥቶአልና፤ በዚህ የለም፤ የተኛበትን ስፍራ ኑና እዩ።'),
  ('03e36ab1-9142-5bb5-ae7f-ee54363baefb', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 7, 7, 'ፈጥናችሁም ሂዱና ‘ከሙታን ተነሣ፤ እነሆም፥ ወደ ገሊላ ይቀድማችኋል በዚያም ታዩታላችሁ፤’ ብላችሁ ለደቀ መዛሙርቱ ንገሩአቸው።'),
  ('c79158ea-dbff-57f1-ade5-1699a6d39adb', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 8, 8, 'እነሆም ነገርኋችሁ።” በፍርሃትና በታላቅ ደስታም ፈጥነው ከመቃብር ሄዱ፤ ለደቀ መዛሙርቱም ሊያወሩ ሮጡ።'),
  ('0967d8d5-94db-588a-a885-6c5bbc855a48', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 9, 9, 'እነሆም፥ ኢየሱስ አገኛቸውና “ደስ ይበላችሁ፤” አላቸው። እነርሱም ቀርበው እግሩን ይዘው ሰገዱለት።'),
  ('f18bcc92-c2ec-5c8c-aab1-2a8892529a2b', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 10, 10, 'በዚያን ጊዜ ኢየሱስ “አትፍሩ፤ ሄዳችሁ ወደ ገሊላ እንዲሄዱ ለወንድሞቼ ተናገሩ፤ በዚያም ያዩኛል፤” አላቸው።'),
  ('7b483edc-cc30-59cd-a579-6697a015ea28', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 11, 11, 'ሲሄዱም ሳሉ እነሆ፥ ከጠባቆቹ አንዳንድ ወደ ከተማ መጥተው የሆነውን ሁሉ ለካህናት አለቆች አወሩ።'),
  ('6786c8dd-a4dc-506b-ae0f-1854b0d35792', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 12, 12, 'ከሽማግሎች ጋርም ተሰብስበው ተማከሩና ለጭፍሮች ብዙ ገንዘብ ሰጥተዋቸው'),
  ('f3067d34-2770-5003-a831-451d9ffc2aa7', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 13, 13, '“እኛ ተኝተን ሳለን ደቀ መዛሙርቱ በሌሊት መጥተው ሰረቁት” በሉ።'),
  ('eb408b73-1d26-51c9-a2d0-11cc50a65cbf', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 14, 14, 'ይህም በገዢው ዘንድ የተሰማ እንደ ሆነ፥ እኛ እናስረዳዋለን፤ እናንተም ያለ ሥጋት እንድትሆኑ እናደርጋለን፤” አሉአቸው።'),
  ('ff8a8a2a-7513-5a7d-a67f-e5c73f2aaf4a', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '617a3b91-330a-531f-a0e9-697717ae084a', 15, 15, 'እነርሱም ገንዘቡን ተቀብለው እንደ አስተማሩአቸው አደረጉ። ይህም ነገር በአይሁድ ዘንድ እስከ ዛሬ ድረስ ሲወራ ይኖራል።'),
  ('fe9910a5-7b75-5317-a641-b4bf391fa604', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '678355ff-3eab-54d7-a2bd-58e7d46fad8c', 1, 16, 'ዐሥራ አንዱ ደቀ መዛሙርት ግን ኢየሱስ ወዳዘዛቸው ተራራ ወደ ገሊላ ሄዱ፤'),
  ('afce6b94-3f77-5f4e-a075-09bcdd93de62', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '678355ff-3eab-54d7-a2bd-58e7d46fad8c', 2, 17, 'ባዩትም ጊዜ ሰገዱለት፤ የተጠራጠሩ ግን ነበሩ።'),
  ('59e1f315-567c-50c4-a29d-dc0f9b3e42ce', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '678355ff-3eab-54d7-a2bd-58e7d46fad8c', 3, 18, 'ኢየሱስም ቀረበና እንዲህ ብሎ ተናገራቸው “ሥልጣን ሁሉ በሰማይና በምድር ተሰጠኝ።'),
  ('61d97553-aa6b-51c1-a67a-46a8b5af9eb2', '3db35344-3dee-50a0-a388-b2cb92d2ba11', '678355ff-3eab-54d7-a2bd-58e7d46fad8c', 4, 19, 'እንግዲህ ሂዱና አሕዛብን ሁሉ በአብ በወልድና በመንፈስ ቅዱስ ስም እያጠመቃችኋቸው፥ ያዘዝኋችሁንም ሁሉ እንዲጠብቁ እያስተማራችኋቸው ደቀ መዛሙርት አድርጓቸው፤ እነሆም፥ እኔ እስከ ዓለም ፍጻሜ ድረስ ሁልጊዜ ከእናንተ ጋር ነኝ።”'),
  ('1f31ca38-9afb-5988-a631-226452126604', '40146a6e-46d6-5bfb-a190-09498942a490', '184a8329-7800-5987-a7a0-c730db285c07', 1, 1, 'የእግዚአብሔር ልጅ የኢየሱስ ክርስቶስ ወንጌል መጀመሪያ።'),
  ('e4f5fcd7-e7a9-54bd-aa4c-d4b3d30d4a85', '40146a6e-46d6-5bfb-a190-09498942a490', '184a8329-7800-5987-a7a0-c730db285c07', 2, 2, '“እነሆ፥ መንገድህን የሚጠርግ መልክተኛዬን በፊትህ እልካለሁ፤'),
  ('4b2fec3f-eee0-5d0f-a31f-511ab4f96187', '40146a6e-46d6-5bfb-a190-09498942a490', 'a3041a71-7e22-55af-ab66-6863a7239028', 1, 9, 'በዚያ ወራትም ኢየሱስ ከገሊላ ናዝሬት መጥቶ ከዮሐንስ በዮርዳኖስ ወንዝ ተጠመቀ።'),
  ('b7e66e44-87c1-55ce-af9b-53e24c362440', '40146a6e-46d6-5bfb-a190-09498942a490', 'a3041a71-7e22-55af-ab66-6863a7239028', 2, 10, 'ወዲያውም ከውሃው በወጣ ጊዜ ሰማያት ሲቀደዱ መንፈስም እንደ ርግብ ሲወርድበት አየና “የምወድህ ልጄ አንተ ነህ፤'),
  ('49cc27f1-a335-55b6-ac31-382e8f216248', '40146a6e-46d6-5bfb-a190-09498942a490', 'a3041a71-7e22-55af-ab66-6863a7239028', 3, 11, 'በአንተ ደስ ይለኛል፤” የሚል ድምፅ ከሰማያት መጣ።'),
  ('2a6dfb06-3ac5-5b16-ad25-e563e2797d6b', '40146a6e-46d6-5bfb-a190-09498942a490', '414a093a-7627-55f9-ac10-be75269e0695', 1, 12, 'ወዲያውም መንፈስ ወደ ምድረ በዳ አወጣው።'),
  ('2b3bdd47-c3a1-5a16-aa5c-956eb4833ac2', '40146a6e-46d6-5bfb-a190-09498942a490', '414a093a-7627-55f9-ac10-be75269e0695', 2, 13, 'በምድረ በዳም ከሰይጣን እየተፈተነ አርባ ቀን ሰነበተ፤ ከአራዊትም ጋር ነበረ፤ መላእክቱም አገለገሉት።'),
  ('7776f50e-ab92-552a-a6d1-1e006b0d9542', '40146a6e-46d6-5bfb-a190-09498942a490', '5faec019-39f2-5822-a15a-51827fea5902', 1, 14, 'ዮሐንስም አልፎ ከተሰጠ በኋላ ኢየሱስ የእግዚአብሔርን መንግሥት ወንጌል እየሰበከና'),
  ('679ea484-4131-5814-a44e-f422b061fb8a', '40146a6e-46d6-5bfb-a190-09498942a490', '5faec019-39f2-5822-a15a-51827fea5902', 2, 15, '“ዘመኑ ተፈጸመ፤ የእግዚአብሔርም መንግሥት ቀርባለች፤ ንስሐ ግቡ፤ በወንጌልም እመኑ፤” እያለ ወደ ገሊላ መጣ።'),
  ('75b8ff7e-969c-589b-a5cd-5718d8d43800', '40146a6e-46d6-5bfb-a190-09498942a490', '7916529c-59a0-53d7-a7ca-5df021e3bd3e', 1, 16, 'በገሊላ ባሕርም አጠገብ ሲያልፍ ስምዖንን ወንድሙንም እንድርያስን መረባቸውን ወደ ባሕር ሲጥሉ አየ፤ ዓሣ አጥማጆች ነበሩና።'),
  ('c632d65c-e3c0-5ba1-aeb2-a81450cf0bac', '40146a6e-46d6-5bfb-a190-09498942a490', '7916529c-59a0-53d7-a7ca-5df021e3bd3e', 2, 17, 'ኢየሱስም “በኋላዬ ኑና ሰዎችን አጥማጆች እንድትሆኑ አደርጋችኋለሁ፤” አላቸው።'),
  ('fca1fdf0-da70-5679-a848-bd026636768a', '40146a6e-46d6-5bfb-a190-09498942a490', '7916529c-59a0-53d7-a7ca-5df021e3bd3e', 3, 18, 'ወዲያውም መረባቸውን ትተው ተከተሉት።'),
  ('f975c485-afe1-58d6-aabe-188d0d46ff72', '40146a6e-46d6-5bfb-a190-09498942a490', '7916529c-59a0-53d7-a7ca-5df021e3bd3e', 4, 19, 'ከዚያም ጥቂት እልፍ ብሎ የዘብዴዎስን ልጅ ያዕቆብን ወንድሙንም ዮሐንስን ደግሞ በታንኳ ላይ መረባቸውን ሲያበጁ አየ።'),
  ('a6cccb3c-66a3-540f-a220-6ebc3270695a', '40146a6e-46d6-5bfb-a190-09498942a490', '7916529c-59a0-53d7-a7ca-5df021e3bd3e', 5, 20, 'ወዲያውም ጠራቸው፤ አባታቸውንም ዘብዴዎስን ከሞያተኞቹ ጋር በታንኳ ላይ ትተው ተከትለውት ሄዱ።'),
  ('21e267b3-ff80-537b-a684-b03dc3fcf87b', '40146a6e-46d6-5bfb-a190-09498942a490', '7106455f-0d9e-51c1-a2fd-aa50dd992fc7', 1, 21, 'ወደ ቅፍርናሆምም ገቡ፤ ወዲያውም በሰንበት ወደ ምኵራብ ገብቶ አስተማረ።'),
  ('d7433511-6823-5344-a98f-1e2ee824600c', '40146a6e-46d6-5bfb-a190-09498942a490', '7106455f-0d9e-51c1-a2fd-aa50dd992fc7', 2, 22, 'እንደ ባለ ሥልጣን ያስተምራቸው ነበር እንጂ እንደ ጻፎች አይደለምና በትምህርቱ ተገረሙ።'),
  ('8e45ab9c-4ed1-59e6-af50-c38bc2863625', '40146a6e-46d6-5bfb-a190-09498942a490', '7106455f-0d9e-51c1-a2fd-aa50dd992fc7', 3, 23, 'በዚያን ጊዜም በምኩራባቸው ርኵስ መንፈስ ያለው ሰው ነበረ፤'),
  ('84e2ec8a-a116-5afc-a948-f6dc92b3688c', '40146a6e-46d6-5bfb-a190-09498942a490', '7106455f-0d9e-51c1-a2fd-aa50dd992fc7', 4, 24, 'እርሱም “የናዝሬቱ ኢየሱስ ሆይ! ከአንተ ጋር ምን አለን? ልታጠፋን መጣህን? ማን እንደ ሆንህ አውቄአለሁ! የእግዚአብሔር ቅዱሱ!” ብሎ ጮኸ።'),
  ('ba572536-004a-5110-ace5-0a6743de5989', '40146a6e-46d6-5bfb-a190-09498942a490', '7106455f-0d9e-51c1-a2fd-aa50dd992fc7', 5, 25, 'ኢየሱስም “ዝም በል፤ ከእርሱም ውጣ፤” ብሎ ገሠጸው።'),
  ('1c991e9d-b339-5985-a6b6-8bd726065641', '40146a6e-46d6-5bfb-a190-09498942a490', '7106455f-0d9e-51c1-a2fd-aa50dd992fc7', 6, 26, 'ርኵሱም መንፈስ አንፈራገጠውና በታላቅ ድምፅ ጮኾ ከእርሱ ወጣ።'),
  ('5ced9f39-a1b5-5482-af9a-c79c8e4c3f90', '40146a6e-46d6-5bfb-a190-09498942a490', '7106455f-0d9e-51c1-a2fd-aa50dd992fc7', 7, 27, 'ሁሉም “ይህ ምንድር ነው? በሥልጣን ርኵሳን መናፍስትን ያዝዛል፤ እነርሱም ይታዘዙለታልና ይህ አዲስ ትምህርት ምንድር ነው?” ብለው እስኪጠያየቁ ድረስ አደነቁ።'),
  ('a3d1b59c-af3a-5571-adab-b0a2649aae03', '40146a6e-46d6-5bfb-a190-09498942a490', '7106455f-0d9e-51c1-a2fd-aa50dd992fc7', 8, 28, 'ዝናውም ወዲያው በየስፍራው ወደ ገሊላ ዙሪያ ሁሉ ወጣ።'),
  ('5de9cd1b-b2c1-571d-a0d9-99181bd82672', '40146a6e-46d6-5bfb-a190-09498942a490', '0adf0d73-6244-5a6a-ae61-97d7fac77ec5', 1, 29, 'ወዲያውም ከምኵራብ ወጥቶ ከያዕቆብና ከዮሐንስ ጋር ወደ ስምዖንና ወደ እንድርያስ ቤት ገባ።'),
  ('4cd6047f-01a6-5633-a541-43375bf0a20c', '40146a6e-46d6-5bfb-a190-09498942a490', '0adf0d73-6244-5a6a-ae61-97d7fac77ec5', 2, 30, 'የስምዖንም አማት በንዳድ ታማ ተኝታ ነበር፤ ስለ እርስዋም ወዲያው ነገሩት።'),
  ('25d80260-5b65-57f2-a669-10fe467fe829', '40146a6e-46d6-5bfb-a190-09498942a490', '0adf0d73-6244-5a6a-ae61-97d7fac77ec5', 3, 31, 'ቀርቦም እጅዋን ይዞ አስነሣት፤ ንዳዱም ወዲያው ለቀቃትና አገለገለቻቸው።'),
  ('086c4e80-19ef-55f9-ac11-261a6015c647', '40146a6e-46d6-5bfb-a190-09498942a490', '0adf0d73-6244-5a6a-ae61-97d7fac77ec5', 4, 32, 'ፀሐይም ገብቶ በመሸ ጊዜ፥ የታመሙትንና አጋንንት ያደረባቸውን ሁሉ ወደ እርሱ አመጡ፤'),
  ('7e325d38-71b0-5204-a623-451945aa148d', '40146a6e-46d6-5bfb-a190-09498942a490', '0adf0d73-6244-5a6a-ae61-97d7fac77ec5', 5, 33, 'ከተማይቱም ሁላ በደጅ ተሰብስባ ነበር።'),
  ('b8f0167d-fe1a-5a81-adb4-8fbae84a5cb8', '40146a6e-46d6-5bfb-a190-09498942a490', '0adf0d73-6244-5a6a-ae61-97d7fac77ec5', 6, 34, 'በልዩ ልዩ ደዌም የታመሙትን ብዙዎችን ፈወሰ፤ ብዙዎችንም አጋንንት አወጣ፤ አጋንንትም ክርስቶስ መሆኑን አውቀው ነበርና ሊናገሩ አልፈቀደላቸውም።'),
  ('bd655211-dc3d-5532-a42d-ee7910bd3eb9', '40146a6e-46d6-5bfb-a190-09498942a490', '10ca3e66-3cfa-5753-af13-6a927ae7a10c', 1, 35, 'ማለዳም ተነሥቶ ገና ሌሊት ሳለ ወጣ፤ ወደ ምድረ በዳም ሄዶ በዚያ ጸለየ።'),
  ('9243f7dd-1bf9-5767-af70-0ef1745634b4', '40146a6e-46d6-5bfb-a190-09498942a490', '10ca3e66-3cfa-5753-af13-6a927ae7a10c', 2, 36, 'ስምዖንና ከእርሱ ጋር የነበሩትም ገሥግሠው ተከተሉት፤'),
  ('2587b0c8-2cc5-547a-ad34-2329a8031d41', '40146a6e-46d6-5bfb-a190-09498942a490', '10ca3e66-3cfa-5753-af13-6a927ae7a10c', 3, 37, 'ባገኙትም ጊዜ “ሁሉ ይፈልጉሃል፤” አሉት።'),
  ('534358bf-e8dc-55af-aeb0-2f557156b426', '40146a6e-46d6-5bfb-a190-09498942a490', '10ca3e66-3cfa-5753-af13-6a927ae7a10c', 4, 38, 'እርሱም “በዚያ ደግሞ ልሰብክ ወደ ሌላ ስፍራ በቅርብ ወዳሉ መንደሮች እንሂድ፤ ስለዚህ መጥቻለሁና፤” አላቸው።'),
  ('60f48a3d-5dc7-59ea-ac52-77aca44371c7', '40146a6e-46d6-5bfb-a190-09498942a490', '10ca3e66-3cfa-5753-af13-6a927ae7a10c', 5, 39, 'በምኵራባቸውም እየሰበከ አጋንንትንም እያወጣ ወደ ገሊላ ሁሉ መጣ።'),
  ('50325708-8882-5534-a560-d7f09058d649', '40146a6e-46d6-5bfb-a190-09498942a490', '9318d33a-fbd4-552f-a5c7-906ff8018877', 1, 40, 'ለምጻምም ወደ እርሱ መጥቶ ተንበረከከና “ብትወድስ ልታነጻኝ ትችላለህ፤” ብሎ ለመነው።'),
  ('4827d526-aaec-51ab-a589-483d55637d1a', '40146a6e-46d6-5bfb-a190-09498942a490', '9318d33a-fbd4-552f-a5c7-906ff8018877', 2, 41, 'ኢየሱስም አዘነለት እጁንም ዘርግቶ ዳሰሰውና “እወድዳለሁ፤ ንጻ፤” አለው።'),
  ('c8783b03-799a-53dc-a53c-5d4e9b580693', '40146a6e-46d6-5bfb-a190-09498942a490', '9318d33a-fbd4-552f-a5c7-906ff8018877', 3, 42, 'በተናገረም ጊዜ ለምጹ ወዲያው ለቀቀውና ነጻ።'),
  ('fe53d37f-ffa0-5e7a-ae1a-ec1c9e463f5f', '40146a6e-46d6-5bfb-a190-09498942a490', '9318d33a-fbd4-552f-a5c7-906ff8018877', 4, 43, 'በብርቱም ተናግሮ ወዲያው አሰናበተው፤'),
  ('356baadd-0158-59fa-af6c-f4394e4e8b3b', '40146a6e-46d6-5bfb-a190-09498942a490', '9318d33a-fbd4-552f-a5c7-906ff8018877', 5, 44, '“ለማንም አንዳች እንዳትናገር ተጠንቀቅ፤ ነገር ግን ሄደህ ራስህን ለካህን አሳይ፤ ለእነርሱም ምስክር እንዲሆን ስለ መንጻትህ ሙሴ ያዘዘውን አቅርብ፤” አለው።'),
  ('526ed855-7a81-5cf4-af11-ac3e08a42168', '40146a6e-46d6-5bfb-a190-09498942a490', '9318d33a-fbd4-552f-a5c7-906ff8018877', 6, 45, 'እርሱ ግን ሲወጣ ብዙ ሊሰብክና ነገሩን ሊያወራ ጀመረ፤ ስለዚህም ኢየሱስ ተገልጦ ወደ ከተማ መግባት ወደ ፊት ተሳነው፤ ነገር ግን በውጭ በምድረ በዳ ይኖር ነበር፤ ከየስፍራውም ወደ እርሱ ይመጡ ነበር።'),
  ('eb7b83dd-ff0e-5586-a7d2-d818e573ae9a', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 1, 1, 'ከጥቂት ቀን በኋላ ወደ ቅፍርናሆም ደግሞ ገብቶ በቤት እንደ ሆነ ተሰማ።'),
  ('40a4580a-2f39-544d-a21b-67a92b0cd411', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 2, 2, 'በደጅ ያለው ስፍራም እስኪጠባቸው ድረስ ብዙ ሰዎች ተሰበሰቡ፤ ቃሉንም ይነግራቸው ነበር።'),
  ('b5bad2c4-d60a-55c1-a0fd-d3699822afef', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 3, 3, 'አራት ሰዎችም የተሸከሙትን ሽባ አመጡለት።'),
  ('9c2a7de7-7a5f-57ee-ad38-06618119c63e', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 4, 4, 'ስለ ሕዝቡም ብዛት ወደ እርሱ ማቅረብ ቢያቅታቸው እርሱ ያለበትን የቤቱን ጣራ አነሡ፤ ነድለውም ሽባው የተኛበትን አልጋ አወረዱ።'),
  ('a9c548b5-80d6-5c2d-aa41-9c1b7bd50c79', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 5, 5, 'ኢየሱስም እምነታቸውን አይቶ ሽባውን “አንተ ልጅ! ኀጢአትህ ተሰረየችልህ፤” አለው።'),
  ('f60df115-2adc-5aa9-a348-c095db9ac2e2', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 6, 6, 'ከጻፎችም አንዳንዶቹ በዚያ ተቀምጠው ነበር በልባቸውም “ይህ ሰው ስለ ምን እንደዚህ ያለ ስድብ ይናገራል?'),
  ('b9eeec4c-b936-5f75-a389-3e950251d7ae', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 7, 7, 'ከአንዱ ከእግዚአብሔር በቀር ኀጢአት ሊያስተሰርይ ማን ይችላል፤” ብለው አሰቡ።'),
  ('da5c9171-2f29-5400-aef2-4ee1fbd80504', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 8, 8, 'ወዲያውም ኢየሱስ በልባቸው እንዲህ እንዳሰቡ በመንፈስ አውቆ እንዲህ አላቸው “በልባችሁ ይህን ስለ ምን ታስባላችሁ?'),
  ('ae593206-3632-5500-a8d2-4aac653c458d', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 9, 9, 'ሽባውን ‘ኀጢአትህ ተሰረየችልህ፤’ ከማለት ወይስ ‘ተነሣ አልጋህንም ተሸከምና ሂድ፤’ ከማለት ማናቸው ይቀላል?'),
  ('d02fce5b-3558-52e2-a1d0-68e647f00d7f', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 10, 10, 'ነገር ግን ለሰው ልጅ በምድር ላይ ኀጢአትን ሊያስተሰርይ ሥልጣን እንዳለው እንድታውቁ፤”'),
  ('62486f77-1991-52bc-a882-f4bba60442b0', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 11, 11, 'ሽባውን “አንተን እልሃለሁ፥ ተነሣ፤ አልጋህን ተሸከምና ወደ ቤትህ ሂድ፤” አለው።'),
  ('3e6fe4c3-f84c-5fa2-abee-a26547a4533c', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'f1f58df2-3a56-5fd0-abda-aaac529dfde2', 12, 12, 'ተነሥቶም ወዲያው አልጋውን ተሸክሞ በሁሉ ፊት ወጣ፤ ስለዚህም ሰዎች ሁሉ ተገረሙና “እንዲህ ያለ ከቶ አላየንም፤” ብለው እግዚአብሔርን አከበሩ።'),
  ('31d6bb42-730c-5fca-a436-47639c0fc3da', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', '6c1e4d27-ce3d-57e8-a306-a530bcd7893b', 1, 13, 'ደግሞም በባሕር አጠገብ ወጣ፤ ሕዝቡም ሁሉ ወደ እርሱ መጡና አስተማራቸው።'),
  ('5e9b1df7-d882-5f24-a630-02eaf748503c', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', '6c1e4d27-ce3d-57e8-a306-a530bcd7893b', 2, 14, 'ሲያልፍም በመቅረጫው ተቀምጦ የነበረውን የእልፍዮስን ልጅ ሌዊን አየና “ተከተለኝ፤” አለው። ተነሥቶም ተከተለው።'),
  ('c6dac699-9aa0-5e99-a296-1b8b4d922bbf', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', '6c1e4d27-ce3d-57e8-a306-a530bcd7893b', 3, 15, 'በቤቱም በማዕድ ተቀምጦ ሳለ፥ ብዙ ቀራጮችና ኀጢአተኞች ከኢየሱስና ከደቀ መዛሙርቱ ጋር ተቀመጡ፤ ብዙ ነበሩ፤ ይከተሉትም ነበር።'),
  ('d620e8ce-9bca-5ea0-a2c6-0ee39bb73935', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', '6c1e4d27-ce3d-57e8-a306-a530bcd7893b', 4, 16, 'ጻፎችና ፈሪሳውያንም ከቀራጮችና ከኀጢአተኞች ጋር ሲበላ አይተው ለደቀ መዛሙርቱ “ከቀራ ጮችና ከኀጢአተኞች ጋር የሚበላና የሚጠጣ ስለ ምንድር ነው?” አሉ።'),
  ('01dcfa7a-8a77-5259-aefc-9f2fd2f4b248', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', '6c1e4d27-ce3d-57e8-a306-a530bcd7893b', 5, 17, 'ኢየሱስም ሰምቶ “ሕመምተኞች እንጂ ብርቱዎች ባለ መድኃኒት አያስፈልጋቸውም፤ ኀጢአተኞችን እንጂ ጻድቃንን ልጠራ አልመጣሁም፤” አላቸው።'),
  ('ece9b9c0-e648-59c3-aee4-734e1f2ca700', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'b7cc314d-a272-59d7-a4af-a879fa99912a', 1, 18, 'የዮሐንስ ደቀ መዛሙርትና ፈሪሳውያን ይጾሙ ነበር። መጥተውም “የዮሐንስና የፈሪሳውያን ደቀ መዛሙርት የሚጾሙት የአንተ ደቀ መዛሙርት ግን የማይጾሙት ስለ ምንድር ነው?” አሉት።'),
  ('57b4b405-b2f7-5802-a600-f260c3b1db22', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'b7cc314d-a272-59d7-a4af-a879fa99912a', 2, 19, 'ኢየሱስም አላቸው “ሙሽራው ከእነርሱ ጋር ሳለ ሚዜዎች ሊጾሙ ይችላሉን? ሙሽራው ከእነርሱ ጋር ሳለ ሊጾሙ አይችሉም።'),
  ('ac7332ae-9125-5ea6-afec-7ee47d876a48', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'b7cc314d-a272-59d7-a4af-a879fa99912a', 3, 20, 'ነገር ግን ሙሽራው ከእነርሱ የሚወሰድበት ወራት ይመጣል፤ በዚያ ወራትም ይጾማሉ።'),
  ('c1548956-e23f-5f9a-a9a5-fd9931da1238', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'b7cc314d-a272-59d7-a4af-a879fa99912a', 4, 21, 'በአረጀ ልብስ አዲስ እራፊ የሚጥፍ የለም፤ ቢደረግ ግን፥ አዲሱ መጣፊያ አሮጌውን ይቦጭቀዋል፤ መቀደዱም የባሰ ይሆናል።'),
  ('87e87c6a-d35c-52cd-a788-a24c9478200e', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'b7cc314d-a272-59d7-a4af-a879fa99912a', 5, 22, 'በአረጀ አቁማዳም አዲስ የወይን ጠጅ የሚያኖር የለም፤ ቢደረግ ግን፥ የወይን ጠጁ አቁማዳውን ያፈነዳል፤ የወይኑም ጠጅ ይፈሳል፤ አቁማዳውም ይጠፋል፤ አዲሱን የወይን ጠጅ ግን በአዲስ አቁማዳ ያኖራሉ።”'),
  ('293b6c07-abd5-5298-a179-a0830cae6668', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'd124f303-23fb-5b22-a54b-ad917ccddc47', 1, 23, 'በሰንበትም በእርሻ መካከል ሲያልፍ ደቀ መዛሙርቱ እየሄዱ እሸት ይቀጥፉ ጀመር።'),
  ('395cb2ab-8e61-54d2-a9a1-465d64c36b79', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'd124f303-23fb-5b22-a54b-ad917ccddc47', 2, 24, 'ፈሪሳውያንም “እነሆ፥ በሰንበት ያልተፈቀደውን ስለ ምን ያደርጋሉ?” አሉት።'),
  ('c13933a3-a69d-5b9a-a7d1-b4ecb1758547', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'd124f303-23fb-5b22-a54b-ad917ccddc47', 3, 25, 'እርሱም “ዳዊት ባስፈለገውና በተራበ ጊዜ፥ እርሱ አብረውት ከነበሩት ጋር ያደረገውን፥'),
  ('c7699e8a-5f14-50cd-a08a-727f39b90102', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'd124f303-23fb-5b22-a54b-ad917ccddc47', 4, 26, 'አብያተር ሊቀ ካህናት በነበረ ጊዜ ወደ እግዚአብሔር ቤት እንደ ገባ፥ ከካህናት በቀር መብላት ያልተፈቀደውን የመሥዋዕትን እንጀራ እንደ በላ፥ ከእርሱም ጋር ለነበሩት እንደ ሰጣቸው ከቶ አላነበባችሁምን?” አላቸው።'),
  ('a293dbf1-452b-5ce6-adb0-29e4e4011346', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'd124f303-23fb-5b22-a54b-ad917ccddc47', 5, 27, 'ደግሞ “ሰንበት ስለ ሰው ተፈጥሮአል እንጂ ሰው ስለ ሰንበት አልተፈጠረም፤'),
  ('91b65fa8-cef9-533e-ab39-dc1c9eecd21a', '13ef6b2b-7c75-5f2e-af4e-1ddbea996383', 'd124f303-23fb-5b22-a54b-ad917ccddc47', 6, 28, 'እንዲሁም የሰው ልጅ ለሰንበት እንኳ ጌታዋ ነው፤” አላቸው።'),
  ('f3fa2a32-2528-5d7f-a86c-b51e68c7e5a8', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '905fe24b-86ab-5ef3-a2f0-0203c016e230', 1, 1, 'ደግሞም ወደ ምኵራብ ገባ፤ በዚያም እጁ የሰለለች ሰው ነበር፤'),
  ('6cf8437e-fb57-5156-ae7e-6437e0501d7a', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '905fe24b-86ab-5ef3-a2f0-0203c016e230', 2, 2, 'ሊከሱትም በሰንበት ይፈውሰው እንደ ሆነ ይጠባበቁት ነበር።'),
  ('f065422e-7cef-53c4-a3cb-66ac9a193fec', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '905fe24b-86ab-5ef3-a2f0-0203c016e230', 3, 3, 'እጁ የሰለለችውንም ሰው “ተነሥተህ ወደ መካከል ና፤” አለው።'),
  ('d7fb5776-c446-5ce9-a4bc-0b1ec7a0d87c', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '905fe24b-86ab-5ef3-a2f0-0203c016e230', 4, 4, '“በሰንበት በጎ ማድረግ ተፈቅዶአልን? ወይስ ክፉ? ነፍስ ማዳን ወይስ መግደል?” አላቸው፤ እነርሱም ዝም አሉ።'),
  ('aa8d1053-efa5-5c21-a829-ea2be22fd53f', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '905fe24b-86ab-5ef3-a2f0-0203c016e230', 5, 5, 'ስለ ልባቸውም ድንዛዜ አዝኖ ዙሪያውን እየተመለከተ በቍጣ አያቸው፤ ሰውየውንም “እጅህን ዘርጋ፤” አለው። ዘረጋትም፤ እጁም ዳነች።'),
  ('58253184-4e1f-577a-a2ca-cab4e4874b43', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '905fe24b-86ab-5ef3-a2f0-0203c016e230', 6, 6, 'ፈሪሳውያንም ወጥተው ወዲያው እንዴት አድርገው እንዲያጠፉት ከሄሮድስ ወገን ጋር ተማከሩበት።'),
  ('1be1ff46-0328-565b-aaa8-1870bda98873', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'f1bdd478-cad3-5763-ab3e-fe87292abfa4', 1, 7, 'ኢየሱስም ከደቀ መዛሙርቱ ጋር ወደ ባህር ፈቀቅ አለ፤ ከገሊላ የመጡም ብዙ ሰዎች ተከተሉት፤'),
  ('c827658c-39ae-5956-a7ff-7acde93c8fba', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'f1bdd478-cad3-5763-ab3e-fe87292abfa4', 2, 8, 'እንዴት ትልቅ ነገርም እንዳደረገ ሰምተው ብዙ ሰዎች ከይሁዳ ከኢየሩሳሌምም ከኤዶምያስም ከዮርዳኖስ ማዶም ከጢሮስና ከሲዶና ምድርም ወደ እርሱ መጡ።'),
  ('c00dd6ac-db80-5838-a4b4-03567de1fb94', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'f1bdd478-cad3-5763-ab3e-fe87292abfa4', 3, 9, 'ሰዎቹም እንዳያጋፉት ታንኳን ያቆዩለት ዘንድ ደቀ መዛሙርቱን አዘዛቸው፤'),
  ('7182b71b-d0a0-5d2e-a7e8-2a74d8694568', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'f1bdd478-cad3-5763-ab3e-fe87292abfa4', 4, 10, 'ብዙ ሰዎችን አድኖ ነበርና፥ ስለዚህም ሥቃይ ያለባቸው ሁሉ እንዲዳስሱት ይወድቁበት ነበር።'),
  ('deffdf73-5902-5f1c-a56f-3717b0396ef3', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'f1bdd478-cad3-5763-ab3e-fe87292abfa4', 5, 11, 'ርኵሳን መናፍስትም ባዩት ጊዜ በፊቱ ተደፍተው “አንተ የእግዚአብሔር ልጅ ነህ፤” እያሉ ጮኹ።'),
  ('5a4197d8-1412-52c6-a0f7-29778b3b6b35', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'f1bdd478-cad3-5763-ab3e-fe87292abfa4', 6, 12, 'እንዳይገልጡትም በጣም አዘዛቸው።'),
  ('dfc2172f-5d1f-51f9-a330-85c2996824f0', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '64f20565-6fc5-5db7-a0c7-255047666c4c', 1, 13, 'ወደ ተራራም ወጣ፤ ራሱም የወደዳቸውን ወደ እርሱ ጠራ፤ ወደ እርሱም ሄዱ።'),
  ('308a3d44-36df-5f11-ac89-a6c1a6bd884b', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '64f20565-6fc5-5db7-a0c7-255047666c4c', 2, 14, 'ከእርሱም ጋር እንዲኖሩና ለመስበክ እንዲልካቸው፥'),
  ('382306cf-ec64-5cbb-a007-7b5843420394', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '64f20565-6fc5-5db7-a0c7-255047666c4c', 3, 15, 'ድውዮችንም ሊፈውሱ አጋንንትንም ሊያወጡ ሥልጣን ይሆንላቸው ዘንድ ዐሥራ ሁለት አደረገ፤'),
  ('93012c8c-b26b-5303-a5e8-755449804860', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '64f20565-6fc5-5db7-a0c7-255047666c4c', 4, 16, 'ስምዖንንም ጴጥሮስ ብሎ ሰየመው፤'),
  ('191777d0-1fb8-5491-aa39-3812cd874707', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '64f20565-6fc5-5db7-a0c7-255047666c4c', 5, 17, 'የዘብዴዎስንም ልጅ ያዕቆብን የያዕቆብንም ወንድም ዮሐንስን ቦአኔርጌስ ብሎ ሰየማቸው፤ የነጎድጓድ ልጆች ማለት ነው፤'),
  ('eb098fbb-bf2e-5a34-a6bb-167125e314fc', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '64f20565-6fc5-5db7-a0c7-255047666c4c', 6, 18, 'እንድርያስንም ፊልጶስንም በርተሎሜውስንም ማቴዎስንም ቶማስንም የእልፍዮስን ልጅ ያዕቆብንም ታዴዎስንም ቀነናዊውንም ስምዖንን፥'),
  ('d2727a9a-5a41-5f4e-a230-5a518e09a617', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '64f20565-6fc5-5db7-a0c7-255047666c4c', 7, 19, 'አሳልፎ የሰጠውንም የአስቆሮቱን ይሁዳን።'),
  ('2bcad3a6-f4cd-5586-a36e-c91a3000d9bb', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 1, 20, 'ወደ ቤትም መጡ፤ እንጀራም መብላት ስንኳ እስኪሳናቸው ድረስ እንደ ገና ብዙ ሰዎች ተሰበሰቡ።'),
  ('e7229138-77d9-548a-aafc-095df28ea61f', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 2, 21, 'ዘመዶቹም ሰምተው “አበደ” ብለዋልና ሊይዙት ወጡ።'),
  ('bfcb303b-91da-5067-acb8-487d3c2e6256', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 3, 22, 'ከኢየሩሳሌም የወረዱ ጻፎችም “ብዔል ዜቡል አለበት፤” ደግሞ “በአጋንንት አለቃ አጋንንትን ያወጣል፤” ብለው ተናገሩ።'),
  ('5a46e165-3154-555b-a089-00e89ceac43d', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 4, 23, 'እነርሱንም ወደ እርሱ ጠርቶ በምሳሌ አላቸው “ሰይጣን ሰይጣንን ሊያወጣው እንዴት ይችላል?'),
  ('93ab8953-dcfb-50c4-a276-0e48542561ee', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 5, 24, 'መንግሥትም እርስ በርስዋ ከተለያየች ያች መንግሥት ልትቆም አትችልም፤'),
  ('bb43b123-7cf0-57d5-a12e-cddff5afa581', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 6, 25, 'ቤትም እርስ በርሱ ከተለያየ ያ ቤት ሊቆም አይችልም።'),
  ('2ff29b42-1ec8-5f65-a04b-955a6edd15a0', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 7, 26, 'ሰይጣንም ራሱን ተቃውሞ ከተለያየ፥ መጨረሻ ይሆንበታል እንጂ ሊቆም አይችልም።'),
  ('ea4543ab-de16-5f27-aa5e-3d85c7c3130b', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 8, 27, 'ነገር ግን አስቀድሞ ኀይለኛውን ሳያስር ወደ ኀይለኛው ቤት ገብቶ ዕቃውን ሊበዘብዝ የሚችል የለም፤ ከዚያም ወዲያ ቤቱን ይበዘብዛል።'),
  ('de30cd16-bb1b-5a85-adb2-54b7984eee43', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 9, 28, '“እውነት እላችኋለሁ፤ ለሰው ልጆች ኀጢአት ሁሉ የሚሳደቡትም ስድብ ሁሉ ይሰረይላቸዋል፤'),
  ('42c915bb-30bc-55c8-a4c4-b429d3b33566', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 10, 29, 'በመንፈስ ቅዱስ ላይ የሚሳደብ ሁሉ ግን የዘላለም ኀጢአት ዕዳ ይሆንበታል እንጂ ለዘላለም አይሰረይለትም።”'),
  ('010e8142-6957-517b-a01b-8d3cbd1c8f4d', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', '08018f07-94bb-516e-aa67-56f545c48c1e', 11, 30, '“ርኵስ መንፈስ አለበት፤” ይሉ ነበርና።'),
  ('db4f7fbe-44d8-5ad3-a857-dea47f33a388', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'a5c56642-fbcd-5117-aeac-50ff9b0b21da', 1, 31, 'እናቱና ወንድሞቹም መጡ፤ በውጭም ቆመው ወደ እርሱ ልከው አስጠሩት።'),
  ('fc6b3966-4114-5699-ae77-476580efa77f', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'a5c56642-fbcd-5117-aeac-50ff9b0b21da', 2, 32, 'ብዙ ሰዎችም በዙሪያው ተቀምጠው ነበሩና “እነሆ፥ እናትህ ወንድሞችህም በውጭ ቆመው ይፈልጉሃል፤” አሉት።'),
  ('c1497986-499f-5f87-a0ff-d4dbe69b619f', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'a5c56642-fbcd-5117-aeac-50ff9b0b21da', 3, 33, 'መልሶም “እናቴ ማን ናት? ወንድሞቼስ እነ ማን ናቸው?” አላቸው።'),
  ('971781c7-2113-5b75-a000-a36d0f2503dd', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'a5c56642-fbcd-5117-aeac-50ff9b0b21da', 4, 34, 'በዙሪያው ተቀምጠው ወደ ነበሩትም ተመለከተና “እነሆ እናቴ ወንድሞቼም።'),
  ('1800ab0d-3ed7-58d4-a683-fa831f1cce15', 'df3bccb2-9fec-57d2-ada8-f2048bd1d6c2', 'a5c56642-fbcd-5117-aeac-50ff9b0b21da', 5, 35, 'የእግዚአብሔርን ፈቃድ የሚያደርግ ሁሉ፥ እርሱ ወንድሜ ነው፤ እኅቴም፤ እናቴም፤” አለ።'),
  ('7882e601-2d2a-5836-a808-bf4a560bd029', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 1, 1, 'ደግሞም በባሕር ዳር ሊያስተምር ጀመረ። እጅግ ብዙ ሰዎችም ወደ እርሱ ስለ ተሰበሰቡ እርሱ በታንኳ ገብቶ በባሕር ላይ ተቀመጠ፤ ሕዝቡም ሁሉ በባሕር ዳር በምድር ላይ ነበሩ።'),
  ('04b340f1-7926-5674-ad5f-f0fb875b3282', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 2, 2, 'በምሳሌም ብዙ ያስተምራቸው ነበር፤ በትምህርቱም አላቸው።'),
  ('31f0b8d6-ac4b-5008-a8e8-a5479ae5c83a', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 3, 3, '“ስሙ! እነሆ፥ ዘሪ ሊዘራ ወጣ።'),
  ('f806782c-f436-514c-a8db-a2b7ff374d6f', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 4, 4, 'ሲዘራም አንዳንዱ በመንገድ ዳር ወደቀና ወፎች መጥተው በሉት።'),
  ('17ca6433-a2ce-5a16-a2e5-d3551e42bc96', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 5, 5, 'ሌላውም ብዙ መሬት በሌለበት በጭንጫ ላይ ወደቀና ጥልቅ መሬት ስላልነበረው ወዲያው በቀለ፤'),
  ('1e67ab26-0761-5947-a799-2c6007682bd1', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 6, 6, 'ፀሐይም ሲወጣ ጠወለገ፤ ሥርም ስላልነበረው ደረቀ።'),
  ('024eb5f8-f1ac-5464-a9ba-fbc94acecb2e', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 7, 7, 'ሌላውም በእሾህ መካከል ወደቀ፤ እሾህም ወጣና አነቀው፤ ፍሬም አልሰጠም።'),
  ('ed1eb89d-45a1-572f-ada6-2e14dc572e56', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 8, 8, 'ሌላውም በመልካም መሬት ላይ ወደቀና ወጥቶ አድጎ ፍሬ ሰጠ፤ አንዱም ሠላሳ አንዱም ስድሳ አንዱም መቶ አፈራ።'),
  ('1bdb2d51-3ca4-5f19-a7bf-e1b9676ee367', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 9, 9, 'የሚሰማ ጆሮ ያለው ይስማ፤” አለ።'),
  ('a7909aa0-b413-52ba-af4d-9ef77b5c4280', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 10, 10, 'ብቻውንም በሆነ ጊዜ በዙሪያው የነበሩት ከዐሥራ ሁለቱ ጋር ስለ ምሳሌው ጠየቁት።'),
  ('ee010dac-8d7a-5a73-ad06-c82fc0c25aa4', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'f8062c54-c622-5106-a398-b3efaefd6a3d', 11, 11, 'እንዲህም አላቸው “ለእናንተ የእግዚአብሔርን መንግሥት ምሥጢር ማወቅ ተሰጥቶአችኋል፤ በውጭ ላሉት ግን፥'),
  ('f242767c-7f4e-5714-a458-2e4cc7f6a951', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e0f2b600-31b0-5c4b-a10d-81ac1269e549', 1, 21, 'እንዲህም አላቸው “መብራትን ከዕንቅብ ወይስ ከአልጋ በታች ሊያኖሩት ያመጡታልን? በመቅረዝ ላይ ሊያኖሩት አይደለምን?'),
  ('b852d28e-fbf5-564f-a95d-22fbc5feaf49', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e0f2b600-31b0-5c4b-a10d-81ac1269e549', 2, 22, 'እንዲገለጥ ባይሆን የተሰወረ የለምና፤ ወደ ግልጥ እንዲመጣ እንጂ የተሸሸገ የለም።'),
  ('21305167-add3-54f2-a195-a8a6c36ea1f4', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e0f2b600-31b0-5c4b-a10d-81ac1269e549', 3, 23, 'የሚሰማ ጆሮ ያለው ቢኖር ይስማ።”'),
  ('b5a25ef6-21e1-5087-aa41-3d3d2844ea8f', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e0f2b600-31b0-5c4b-a10d-81ac1269e549', 4, 24, 'አላቸውም “ምን እንድትሰሙ ተጠበቁ። በምትሰፍሩበት መስፈሪያ ይሰፈርላችኋል፤ ለእናንተም ይጨመርላችኋል።'),
  ('9d71aa93-0bc5-5c3c-a6aa-f530aff82da0', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e0f2b600-31b0-5c4b-a10d-81ac1269e549', 5, 25, 'ላለው ይሰጠዋልና፤ ከሌለውም ያው ያለው እንኳ ይወሰድበታል።”'),
  ('075a51c9-4bf1-59aa-a816-e0042a7c65cb', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', '5f4f5b70-5abf-5fd7-a16f-50e34c5419e0', 1, 26, 'እርሱም አለ፤ “በምድር ዘርን እንደሚዘራ ሰው የእግዚአብሔር መንግሥት እንደዚህ ናት፤'),
  ('0c145995-dea8-55e6-a8f9-b418a6cf6677', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', '5f4f5b70-5abf-5fd7-a16f-50e34c5419e0', 2, 27, 'ሌሊትና ቀን ይተኛልም፤ ይነሣልም፤ እርሱም እንዴት እንደሚሆን ሳያውቅ ዘሩ ይበቅላል፤ ያድግማል።'),
  ('3f4d0ce8-0f60-57d2-a09e-a6d5966e3f58', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', '5f4f5b70-5abf-5fd7-a16f-50e34c5419e0', 3, 28, 'ምድሪቱም አውቃ በመጀመሪያ ቡቃያ ኋላም ዛላ ኋላም በዛላው ፍጹም ሰብል ታፈራለች።'),
  ('5e4585d1-2f6d-5afc-a978-94f15a35ea76', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', '5f4f5b70-5abf-5fd7-a16f-50e34c5419e0', 4, 29, 'ፍሬ ግን ሲበስል መከር ደርሶአልና ወዲያው ማጭድ ይልካል።”'),
  ('b08b763e-a8ce-5c84-aaf6-ec1042777b7a', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', '2e771d62-c38d-5fcc-a878-d9039c6f2225', 1, 30, 'እርሱም አለ “የእግዚአብሔርን መንግሥት በምን እናስመስላታለን? ወይስ በምን ምሳሌ እንመስላታለን?'),
  ('242164b1-ef40-53c6-a665-d52b786e077b', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', '2e771d62-c38d-5fcc-a878-d9039c6f2225', 2, 31, 'እንደ ሰናፍጭ ቅንጣት ናት፤ እርስዋም በምድር በተዘራች ጊዜ በምድር ካለ ዘር ሁሉ ታንሳለች፤'),
  ('8df2859d-b62a-5a6c-ae24-6959853e9611', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', '2e771d62-c38d-5fcc-a878-d9039c6f2225', 3, 32, 'በተዘራችም ጊዜ ትወጣለች፤ ከአትክልትም ሁሉ የምትበልጥ ትሆናለች፤ የሰማይ ወፎችም በጥላዋ ሊሰፍሩ እስኪችሉ ታላላቅ ቅርንጫፎች ታደርጋለች።”'),
  ('5eaff88b-380f-594c-aa1c-202b796813ed', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', '2e771d62-c38d-5fcc-a878-d9039c6f2225', 4, 33, 'መስማትም በሚችሉበት መጠን እነዚህን በሚመስል በብዙ ምሳሌ ቃሉን ይነግራቸው ነበር፤ ያለ ምሳሌ ግን አልነገራቸውም፤'),
  ('7041d23c-edd0-551c-a2c3-2703897d8ecc', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', '2e771d62-c38d-5fcc-a878-d9039c6f2225', 5, 34, 'ለብቻቸውም ሲሆኑ ነገሩን ሁሉ ለገዛ ደቀ መዛሙርቱ ይፈታላቸው ነበር።'),
  ('b27f2ee7-8963-5566-a4a7-b66456bf1002', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e5bc891a-2bcb-55da-a3ee-60c18ee37616', 1, 35, 'በዚያም ቀን በመሸ ጊዜ “ወደ ማዶ እንሻገር፤” አላቸው።'),
  ('49bca074-774a-5666-ad00-a933ddf388e2', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e5bc891a-2bcb-55da-a3ee-60c18ee37616', 2, 36, 'ሕዝቡንም ትተው በታንኳዪቱ ውስጥ እንዳለ ወሰዱት፤ ሌሎች ታንኳዎችም ከእርሱ ጋር ነበሩ።'),
  ('0da1086b-b5c5-5f28-a054-5d40f8b403a9', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e5bc891a-2bcb-55da-a3ee-60c18ee37616', 3, 37, 'ብርቱ ዐውሎ ነፋስም ተነሣና ውሃ በታንኳይቱ እስኪሞላ ድረስ ማዕበሉ በታንኳይቱ ይገባ ነበር።'),
  ('c968bc00-6d76-535a-a315-bf4356aab637', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e5bc891a-2bcb-55da-a3ee-60c18ee37616', 4, 38, 'እርሱም በስተኋላዋ ትራስ ተንተርሶ ተኝቶ ነበር፤ አንቅተውም “መምህር ሆይ! ስንጠፋ አይገድህምን?” አሉት።'),
  ('1b809bb6-a299-5e22-ad4e-41d4e49cdb96', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e5bc891a-2bcb-55da-a3ee-60c18ee37616', 5, 39, 'ነቅቶም ነፋሱን ገሠጸው፤ ባሕሩንም “ዝም በል፤ ፀጥ በል፤” አለው። ነፋሱም ተወ ታላቅ ፀጥታም ሆነ።'),
  ('1c02644f-fa51-5659-a7a5-c4efec616540', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e5bc891a-2bcb-55da-a3ee-60c18ee37616', 6, 40, '“እንዲህ የምትፈሩ ስለ ምን ነው? እንዴትስ እምነት የላችሁም?” አላቸው።'),
  ('660c493c-229b-5870-a255-96c951af508f', '7cece270-a35f-5ea0-aaee-e6e9f0f6afbb', 'e5bc891a-2bcb-55da-a3ee-60c18ee37616', 7, 41, 'እጅግም ፈሩና “እንግዲህ ነፋስም ባሕርም የሚታዘዙለት ይህ ማን ነው?” ተባባሉ።'),
  ('9ba3cef7-4d64-54a4-ada3-d5c77e0935f3', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 1, 1, 'ወደ ባሕር ማዶም ወደ ጌርጌሴኖን አገር መጡ።'),
  ('19e9d1ff-a7c6-5a13-afd3-00de04acd17b', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 2, 2, 'ከታንኳይቱም በወጣ ጊዜ፥ ርኵስ መንፈስ የያዘው ሰው ከመቃብር ወጥቶ ወዲያው ተገናኘው፤'),
  ('03577204-5a62-5252-ae68-be4e08d03a4e', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 3, 3, 'እርሱም በመቃብር ይኖር ነበር፤ በሰንሰለትም ስንኳ ማንም ሊያስረው በዚያን ጊዜ አይችልም ነበር፤'),
  ('2ef21b22-0b40-50d6-a66a-b3b3bc44babe', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 4, 4, 'ብዙ ጊዜ በእግር ብረትና በሰንሰለት ይታሰር ነበርና፤ ዳሩ ግን ሰንሰለቱን ይበጣጥስ እግር ብረቱንም ይሰባብር ነበር፤ ሊያሸንፈውም የሚችል አልነበረም፤'),
  ('0b6699d1-7ee2-58fb-a887-8e4717d60ee3', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 5, 5, 'ሁልጊዜም ሌሊትና ቀን በመቃብርና በተራራ ሆኖ ይጮኽ ነበር፤ ሰውነቱንም በድንጋይ ይቧጭር ነበር።'),
  ('2c19cef5-4cd0-5687-a0b5-48afa49b5b75', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 6, 6, 'ኢየሱስንም ከሩቅ ባየ ጊዜ ሮጦ ሰገደለት፤'),
  ('7c1d7008-4fb3-5d16-ad19-4313b293e219', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 7, 7, 'በታላቅ ድምፅም እየጮኸ “የልዑል እግዚአብሔር ልጅ ኢየሱስ ሆይ! ከአንተ ጋር ምን አለኝ? እንዳታሠቃየኝ በእግዚአብሔር አምልሃለሁ፤” አለ፤'),
  ('ba2ead16-c03b-58bf-ad32-f79586330a9b', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 8, 8, '“አንተ ርኵስ መንፈስ፥ ከዚህ ሰው ውጣ፤” ብሎት ነበርና።'),
  ('e6918a39-106d-582b-a041-36d403e4ceaf', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 9, 9, '“ስምህ ማን ነው?” ብሎ ጠየቀው። “ብዙዎች ነንና ስሜ ሌጌዎን ነው፤” አለው፤'),
  ('ef152e2b-ea92-59ce-aa13-3da6c6bd2219', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 10, 10, 'ከአገርም ውጭ እንዳይሰዳቸው አጥብቆ ለመነው።'),
  ('d55e73d2-8e5a-52b6-a3ad-7eae4682af4a', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 11, 11, 'በዚያም በተራራ ጥግ ብዙ የእሪያ መንጋ ይሰማራ ነበርና'),
  ('080dab0f-149a-58d9-a027-9c9b9025b361', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 12, 12, '“ወደ እሪያዎቹ እንድንገባ ስደደን፤” ብለው ለመኑት።'),
  ('d13ed27d-eb17-552f-ac7b-b5a3192d4890', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 13, 13, 'ኢየሱስም ፈቀደላቸው። ርኵሳን መናፍስቱም ወጥተው ወደ እሪያዎቹ ገቡ፤ ሁለት ሺህም የሚያህል መንጋ ከአፋፉ ወደ ባሕር ተጣደፉና በባሕር ሰጠሙ።'),
  ('9bd1f077-d523-5392-aaef-f4945a312281', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 14, 14, 'እረኞቹም ሸሽተው በከተማውና በአገሩ አወሩ፤ ነገሩም ምን እንደ ሆነ ለማየት መጡ።'),
  ('7ec5ce67-1e6e-5182-af10-d73076344af5', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 15, 15, 'ወደ ኢየሱስም መጡ፤ አጋንንትም ያደሩበትን ሌጌዎንም የነበረበትን ሰው ተቀምጦ ለብሶም ልቡም ተመልሶ አዩና ፈሩ።'),
  ('5cd02aba-3115-58ac-aba7-87fad1d5ea14', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 16, 16, 'ያዩት ሰዎችም አጋንንት ላደሩበት ሰው የሆነውንና ስለ እሪያዎቹ ተረኩላቸው።'),
  ('6bef08bf-d58d-5a4a-a88a-50f602deb667', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 17, 17, 'ከአገራቸውም እንዲሄድላቸው ይለምኑት ጀመር።'),
  ('3fc85206-abe5-50fb-a0a6-e5fb13804faa', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 18, 18, 'ወደ ታንኳይቱም በገባ ጊዜ አጋንንት አድረውበት የነበረው ሰው ከእርሱ ጋር እንዲኖር ለመነው።'),
  ('a00ee15f-bd86-5577-a765-dc370cf03255', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 19, 19, 'ኢየሱስም አልፈቀደለትም፤ ነገር ግን “ወደ ቤትህ ወደ ቤተ ሰዎችህ ዘንድ ሄደህ ጌታ እንዴት ያለ ታላቅ ነገር እንዳደረገልህ እንዴትስ እንደ ማረህ አውራላቸው፤” አለው።'),
  ('6c19aab6-83dc-5136-a1a4-7b594f80584e', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '1391b1b0-ad74-5547-a5b2-f11c45d2f50b', 20, 20, 'ሄዶም ኢየሱስ እንዴት ያለ ታላቅ ነገር እንዳደረገለት ዐሥር ከተማ በሚባል አገር ይሰብክ ጀመር፤ ሁሉም ተደነቁ።'),
  ('c514f330-9506-542c-ac4e-7501624d9cbb', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 1, 21, 'ኢየሱስም ደግሞ በታንኳይቱ ወደ ማዶ ከተሻገረ በኋላ ብዙ ሰዎች ወደ እርሱ ተሰበሰቡ፤ በባሕርም አጠገብ ነበረ።'),
  ('ac63a7c3-568c-5f91-acb7-bd2f26d830b4', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 2, 22, 'ኢያኢሮስ የተባለ ከምኵራብ አለቆች አንዱ መጣ፤ ባየውም ጊዜ በእግሩ ላይ ወደቀና'),
  ('8ab89f34-9a78-5cff-ae07-cc4b9d943bcc', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 3, 23, '“ታናሽቱ ልጄ ልትሞት ቀርባለችና እንድትድንና በሕይወት እንድትኖር መጥተህ እጅህን ጫንባት፤” ብሎ አጥብቆ ለመነው።'),
  ('42ebd21e-8958-5248-a6fc-ed0b4a6a2f7c', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 4, 24, 'ከእርሱም ጋር ሄደ። ብዙ ሕዝብም ተከተሉት አጋፉትም።'),
  ('63dded67-e8a5-587c-a1c7-19b3977d4dd6', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 5, 25, 'ከዐሥራ ሁለት ዓመትም ጀምሮ ደም የሚፈሳት ሴት ነበረች፤'),
  ('86902663-f932-5db1-afaf-aa275f54e018', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 6, 26, 'ከብዙ ባለ መድኃኒቶችም ብዙ ተሠቃየች፤ ገንዘብዋንም ሁሉ ከስራ ባሰባት እንጂ ምንም አልተጠቀመችም፤'),
  ('70a285f7-f0f4-5b29-a527-8a6e5eaeb402', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 7, 27, 'የኢየሱስንም ወሬ ሰምታ በስተኋላው በሰዎች መካከል መጥታ ልብሱን ዳሰሰች'),
  ('32068425-5c92-5a13-ab3d-e0b70ca16f7e', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 8, 28, '“ልብሱን ብቻ የዳሰስሁ እንደ ሆነ እድናለሁ፤” ብላለችና።'),
  ('63f784fc-3e2e-5140-a2ee-64e7c0e8ed6c', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 9, 29, 'ወዲያውም የደምዋ ምንጭ ደረቀ፤ ከሥቃይዋም እንደዳነች በሰውነትዋ አወቀች።'),
  ('89170a64-94e3-505c-a47e-9a7ddf02f8c7', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 10, 30, 'ወዲያውም ኢየሱስ ከእርሱ ኃይል እንደ ወጣ በገዛ ራሱ አውቆ በሕዝቡ መካከል ዘወር ብሎ “ልብሴን የዳሰሰ ማን ነው?” አለ።'),
  ('998aa45f-56d6-56be-a092-5221309f4017', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 11, 31, 'ደቀ መዛሙርቱም “ሕዝቡ ሲያጋፉህ እያየህ ‘ማን ዳሰሰኝ?” ትላለህን?” አሉት።'),
  ('c10530df-87a1-5a4b-a9e0-26e66aff3b64', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 12, 32, 'ይህንም ያደረገችውን ለማየት ዘወር ብሎ ይመለከት ነበር።'),
  ('4093b26a-5c68-5248-af63-0d8a0a561329', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 13, 33, 'ሴቲቱ ግን የተደረገላትን ስላወቀች፥ እየፈራች እየተንቀጠቀጠችም፥ መጥታ በፊቱ ተደፋች፤ እውነቱንም ሁሉ ነገረችው።'),
  ('ac5c337e-a35a-5607-a69d-49006f359e5d', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 14, 34, 'እርሱም “ልጄ ሆይ! እምነትሽ አድኖሻል፤ በሰላም ሂጂ፤ ከሥቃይሽም ተፈወሽ፤” አላት።'),
  ('d8a6c004-abb3-50ea-aa61-f46c826ffef9', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 15, 35, 'እርሱም ገና ሲናገር ከምኵራብ አለቃው ቤት ዘንድ የመጡት “ልጅህ ሞታለች፤ ስለ ምን መምህሩን አሁን ታደክመዋለህ?” አሉት።'),
  ('e781e75a-48d5-56e6-a40d-f342fa711eae', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 16, 36, 'ኢየሱስ ግን የተናገሩትን ቃል አድምጦ ለምኵራቡ አለቃ “እመን ብቻ እንጂ አትፍራ፤” አለው።'),
  ('f2bc4676-c6cb-561a-a07a-18085b5c2faf', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 17, 37, 'ከጴጥሮስም ከያዕቆብም ከያዕቆብም ወንድም ከዮሐንስ በቀር ማንም እንዲከተለው አልፈቀደም።'),
  ('11445ecb-9692-5fdf-a7a3-bba489c472f9', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 18, 38, 'ወደ ምኵራቡ አለቃ ቤትም መጥቶ ሰዎች ሲንጫጩና ሲያለቅሱ ዋይታም ሲያበዙ አየ፤'),
  ('f4a29654-b357-5959-a5b4-2bbb78c9e960', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 19, 39, 'ገብቶም “ስለ ምን ትንጫጫላችሁ? ታለቅሳላችሁም? ብላቴናይቱ ተኝታለች እንጂ አልሞተችም፤” አላቸው።'),
  ('347d3a13-7295-520a-a4d0-bf7a40389904', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 20, 40, 'በጣምም ሳቁበት። እርሱ ግን ሁሉን አስወጥቶ የብላቴናይቱን አባትና እናት ከእርሱ ጋር የነበሩትንም ይዞ ብላቴናይቱ ወዳለችበት ገባ።'),
  ('d5952a2a-abec-5b6b-ad81-c99554fbc747', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 21, 41, 'የብላቴናይቱንም እጅ ይዞ “ጣሊታ ቁሚ!” አላት፤ ፍችውም “አንቺ ብላቴና ተነሽ እልሻለሁ!” ነው።'),
  ('2ab8054b-406b-5394-ade1-e4b3a0e05465', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 22, 42, 'ብላቴናይቱም የዐሥራ ሁለት ዓመት ልጅ ነበረችና ወዲያው ቆማ ተመላለሰች። ወዲያውም ታላቅ መገረም ተገረሙ።'),
  ('c2f08ff6-98e2-5e99-ab8c-01e6fb5f1ba3', '1a8c29ed-23f3-5a61-a894-667beabc75b4', '76e53b2c-22d6-5e4f-ae2b-64175a4ed599', 23, 43, 'ይህንም ማንም እንዳያውቅ አጥብቆ አዞአቸው “የምትበላውን ስጡአት፤” አላቸው።'),
  ('fbf272b5-47cd-5c27-ae60-3a303907134c', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '72cd6b78-850c-530b-aca5-ff62cf1475ac', 1, 1, 'ከዚያም ወጥቶ ወደ ገዛ አገሩ መጣ፤ ደቀ መዛሙርቱም ተከተሉት።'),
  ('5bbb482a-2576-5057-a7fa-d5017bfd033a', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '72cd6b78-850c-530b-aca5-ff62cf1475ac', 2, 2, 'ሰንበትም በሆነ ጊዜ በምኵራብ ያስተምር ጀመር፤ ብዙዎችም ሰምተው ተገረሙና “እነዚህን ነገሮች ይህ ከወዴት አገኛቸው? ለዚህ የተሰጠችው ጥበብ ምንድር ናት? በእጁም የሚደረጉ እንደነዚህ ያሉ ተአምራት ምንድር ናቸው?'),
  ('3d4fc57e-77c2-5c4b-af2b-e677066d1fd5', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '72cd6b78-850c-530b-aca5-ff62cf1475ac', 3, 3, 'ይህስ ጸራቢው የማርያም ልጅ የያቆብም የዮሳም የይሁዳም የስምዖንም ወንድም አይደለምን? እኅቶቹስ በዚህ በእኛ ዘንድ አይደሉምን?” አሉ፤ ይሰናከሉበትም ነበር።'),
  ('98f5057b-ec03-5b05-a9ca-e84b750c5a89', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '72cd6b78-850c-530b-aca5-ff62cf1475ac', 4, 4, 'ኢየሱስም “ነቢይ ከገዛ አገሩና ከገዛ ዘመዶቹ ከገዛ ቤቱም በቀር ሳይከበር አይቀርም፤” አላቸው።'),
  ('4e0463fa-feee-5ac2-afbd-cf97af4b620b', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '72cd6b78-850c-530b-aca5-ff62cf1475ac', 5, 5, 'በዚያም በጥቂቶች ድውዮች ላይ እጁን ጭኖ ከመፈወስ በቀር፥ ተአምር ሊያደርግ ምንም አልቻለም።'),
  ('62c08d3b-c96e-5af3-ae2a-427dcb0ea679', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '72cd6b78-850c-530b-aca5-ff62cf1475ac', 6, 6, 'ስለ አለማመናቸውም ተደነቀ። በመንደሮችም እያስተማረ ይዞር ነበር።'),
  ('c26e7753-faec-514d-a69a-4d2be4f51500', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '70a3a055-fe31-53a8-ad6d-e5ace260bafa', 1, 7, 'ዐሥራ ሁለቱንም ወደ እርሱ ጠራ፤ ሁለት ሁለቱንም ይልካቸው ጀመር፤ በርኵሳን መናፍስትም ላይ ሥልጣን ሰጣቸው፤'),
  ('9639f9c4-8078-5379-a6f3-448aec006ea4', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '70a3a055-fe31-53a8-ad6d-e5ace260bafa', 2, 8, 'ለመንገድም ከበትር በቀር እንጀራም ቢሆን ከረጢትም ቢሆን መሐለቅም በመቀነታቸው ቢሆን እንዳይዙ አዘዛቸው።'),
  ('b6724395-a4b7-5bc8-a32d-dc2f8ce6c7e4', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '70a3a055-fe31-53a8-ad6d-e5ace260bafa', 3, 9, '“በእግራችሁ ጫማ አድርጉ እንጂ ሁለት እጀ ጠባብ አትልበሱ፤” አለ።'),
  ('99bef86f-3f14-5516-aaa0-dbe62068a69c', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '70a3a055-fe31-53a8-ad6d-e5ace260bafa', 4, 10, '“በማናቸውም ስፍራ ወደ ቤት ብትገቡ ከዚያ እስክትወጡ ድረስ በዚያው ተቀመጡ።'),
  ('d4dbbbf4-1ebb-5ae7-a4a1-8352554049ec', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '70a3a055-fe31-53a8-ad6d-e5ace260bafa', 5, 11, 'ከማይቀበሉአችሁና ከማይሰሙአችሁ ስፍራ ሁሉ፥ ከዚያ ወጥታችሁ ምስክር ይሆንባቸው ዘንድ ከእግራችሁ በታች ያለውን ትቢያ አራግፉ። እውነት እላችኋለሁ፤ ከዚያች ከተማ ይልቅ ለሰዶምና ለገሞራ በፍርድ ቀን ይቀልላቸዋል፤” አላቸው።'),
  ('83d32db5-0dfa-557c-a2d7-5f3116087a5b', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '70a3a055-fe31-53a8-ad6d-e5ace260bafa', 6, 12, 'ወጥተውም ንስሐ እንዲገቡ ሰበኩ፤'),
  ('d9a35e3a-5247-54a9-a15b-c53420ee78f7', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '70a3a055-fe31-53a8-ad6d-e5ace260bafa', 7, 13, 'ብዙ አጋንንትንም አወጡ፤ ብዙ ድውዮችንም ዘይት እየቀቡ ፈወሱአቸው።'),
  ('48ca016e-1b86-5e3c-a3b7-7d88709fb3aa', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 1, 14, 'ስሙም ተገልጦአልና ንጉሡ ሄሮድስ በሰማ ጊዜ “መጥምቁ ዮሐንስ ከሙታን ተነሥቶአል፤ ስለዚህም ኀይል በእርሱ ይደረጋል፤” አለ።'),
  ('d8854c4d-e36e-5aac-a965-221744f44fc3', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 2, 15, 'ሌሎችም “ኤልያስ ነው፤” አሉ፤ ሌሎችም “ከነቢያት እንደ አንዱ ነቢይ ነው፤” አሉ።'),
  ('ec6baf79-0716-5242-a6c8-195ab33b05e5', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 3, 16, 'ሄሮድስ ግን ሰምቶ “እኔ ራሱን ያስቈረጥሁት ዮሐንስ ይህ ነው፤ እርሱ ከሙታን ተነሥቶአል፤” አለ።'),
  ('6d702b67-9db0-582f-a3d2-b0c781ac934e', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 4, 17, 'ሄሮድስ የወንድሙን የፊልጶስን ሚስት ሄሮድያዳን አግብቶ ነበርና በእርስዋ ምክንያት ራሱ ልኮ ዮሐንስን አስይዞ በወኅኒ አሳስሮት ነበር፤'),
  ('3b70a7bf-8219-58f8-ad22-227661776f72', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 5, 18, 'ዮሐንስ ሄሮድስን “የወንድምህ ሚስት ለአንተ ልትሆን አልተፈቀደም፤” ይለው ነበርና።'),
  ('b8bc1a2e-c20f-5fdd-aceb-f98f3c5c66ce', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 6, 19, 'ሄሮድያዳ ግን ተቃውማው ልትገድለው ትፈልግ ነበር፤ አልቻለችም፤'),
  ('43647f3b-dcf9-59b0-a695-6ea4cd1d5734', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 7, 20, 'ሄሮድስ ዮሐንስ ጻድቅና ቅዱስ ሰው እንደ ሆነ አውቆ ይፈራውና ይጠባበቀው ነበር፤ እርሱንም ሰምቶ በብዙ ነገር ያመነታ ነበር፤ በደስታም ይሰማው ነበር።'),
  ('99f63cff-d3ff-5e08-a5a6-f2988f62e1a4', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 8, 21, 'ሄሮድስም በተወለደበት ቀን ለመኳንንቱና ለሻለቆቹ ለገሊላም ሹማምንት ግብር ባደረገ ጊዜ ምቹ ቀን ሆነላትና'),
  ('a2e163b8-af59-5e67-a28f-15123a10bc30', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 9, 22, 'የሄሮድያዳ ልጅ ገብታ ስትዘፍን ሄሮድስንና ከእርሱ ጋር የተቀመጡትን ደስ አሰኘቻቸው። ንጉሡም ብላቴናይቱን “የምትወጂውን ሁሉ ለምኚኝ፤ እሰጥሽማለሁ፤” አላት፤'),
  ('5867ae84-ba2e-55e7-a6cd-23453662f226', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 10, 23, '“የመንግሥቴ እኩሌታ ስንኳ ቢሆን የምትለምኚውን ሁሉ እሰጥሻለሁ፤” ብሎ ማለላት።'),
  ('efaa9934-077c-5bc0-a510-0cde4e9504e3', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 11, 24, 'ወጥታም ለእናትዋ “ምን ልለምነው?” አለች። እርስዋም “የመጥምቁን የዮሐንስን ራስ” አለች።'),
  ('cce4ab1b-5bd8-5c85-ad95-dec24997f5c2', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 12, 25, 'ወዲያውም ፈጥና ወደ ንጉሡ ገብታ “የመጥምቁን የዮሐንስን ራስ በወጭት አሁን ልትሰጠኝ እወዳለሁ፤” ብላ ለመነችው።'),
  ('e7a48ba2-7c75-5f3a-af8c-614ae721c742', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 13, 26, 'ንጉሡም እጅግ አዝኖ ስለ መሐላው ከእርሱም ጋር ስለ ተቀመጡት ሊነሣት አልወደደም።'),
  ('58c50a19-28af-5489-a9e8-b82816a9822b', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 14, 27, 'ወዲያውም ንጉሡ ባለ ወግ ልኮ ራሱን እንዲያመጣ አዘዘው። ሄዶም በወኅኒ ራሱን ቈረጠ፤'),
  ('4ccdcc35-8b07-5c60-a34b-1141874c248d', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 15, 28, 'ራሱንም በወጭት አምጥቶ ለብላቴናይቱ ሰጣት፤ ብላቴናይቱም ለእናትዋ ሰጠች።'),
  ('fcf96d9a-3ef6-50e1-aa13-e81a252da290', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '7dfeaada-576c-5a5f-a4a7-70408d75d111', 16, 29, 'ደቀ መዛሙርቱም ሰምተው መጡ፤ በድኑንም ወስደው ቀበሩት።'),
  ('2b3d478e-32d6-504e-a7a6-49c4c3fa137c', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 1, 30, 'ሐዋርያትም ወደ ኢየሱስ ተሰብስበው ያደረጉትንና ያስተማሩትን ሁሉ ነገሩት።'),
  ('509908ad-fc92-53a3-a4bc-5db691f6eb6b', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 2, 31, '“እናንተ ራሳችሁ ብቻችሁን ወደ ምድረ በዳ ኑና ጥቂት ዕረፉ፤” አላቸው፤ የሚመጡና የሚሄዱ ብዙዎች ነበሩና፥ ለመብላት እንኳ ጊዜ አጡ።'),
  ('d6bde910-02f6-55ca-a3b8-7122d732980d', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 3, 32, 'በታንኳውም ብቻቸውን ወደ ምድረ በዳ ሄዱ።'),
  ('324ceef5-a9da-5f26-ad81-a13ab5a187ff', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 4, 33, 'ሰዎችም ሲሄዱ አዩአቸው፤ ብዙዎችም አወቁአቸውና ከከተሞች ሁሉ በእግር እየሮጡ ወዲያ ቀደሙአቸው፤ ወደ እርሱም ተሰበሰቡ።'),
  ('3e69ad54-ace5-5d23-a743-f393f1dcd263', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 5, 34, 'ኢየሱስም ወጥቶ ብዙ ሕዝብ አየና እረኛ እንደሌላቸው በጎች ስለ ነበሩ አዘነላቸው፤ ብዙም ነገር ያስተምራቸው ጀመር።'),
  ('73f4000d-13e8-551b-a1e4-13a2f6e2533e', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 6, 35, 'በዚያን ጊዜም ብዙ ሰዓት ካለፈ በኋላ ደቀ መዛሙርቱ ወደ እርሱ ቀርበው “ቦታው ምድረ በዳ ነው፤ አሁንም መሽቶአል፤'),
  ('5b48a05f-8052-5361-a9e6-bc864801811c', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 7, 36, 'የሚበሉት የላቸውምና በዙሪያ ወዳሉ ገጠሮችና መንደሮች ሄደው እንጀራ ለራሳቸው እንዲገዙ አሰናብታቸው፤” አሉት።'),
  ('83fd4318-2730-51ad-aac8-b60ee7eeeff3', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 8, 37, 'እርሱ ግን መልሶ “እናንተ የሚበሉትን ስጡአቸው፤” አላቸው። “ሄደን እንጀራ በሁለት መቶ ዲናር እንግዛላቸውን? እንዲበሉም እንስጣቸውን?” አሉት።'),
  ('d6817b1b-80b2-5f0f-a55e-885d55292c41', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 9, 38, 'እርሱም “ስንት እንጀራ አላችሁ? ሂዱና እዩ፤” አላቸው። ባወቁም ጊዜ “አምስት፥ ሁለትም ዓሣ፤” አሉት።'),
  ('90577146-fdb6-536f-a34b-a4f5d799498d', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 10, 39, 'ሁሉንም በየክፍሉ በለመለመ ሣር ላይ እንዲያስቀምጡአቸው አዘዛቸው።'),
  ('621b5308-464f-5b9a-aafa-522121b0ccc3', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 11, 40, 'መቶ መቶውና አምሳ አምሳው እየሆኑ በተራ በተራ ተቀመጡ።'),
  ('a0f53796-e044-5158-ad61-66d6f0909eac', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 12, 41, 'አምስቱንም እንጀራ ሁለቱንም ዓሣ ይዞ ወደ ሰማይ አሻቅቦ አየና ባረከ፤ እንጀራውንም ቈርሶ እንዲያቀርቡላቸው ለደቀ መዛሙርቱ ሰጠ፤'),
  ('c2379596-dad9-5086-a476-27af7a59b80b', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 13, 42, 'ሁለቱን ዓሣ ደግሞ ለሁሉ ከፈለ። ሁሉም በልተው ጠገቡ፤'),
  ('fc4c2066-b4a9-53af-a668-6e340d391f1c', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 14, 43, 'ከቍርስራሹም ዐሥራ ሁለት መሶብ የሞላ አነሡ፤ ከዓሣውም ደግሞ።'),
  ('77cbf42a-6bcb-5adf-ab5e-41cc0b8a57a9', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '3a65406c-3157-529e-a77f-c0459b0b4c4f', 15, 44, 'እንጀራውንም የበሉት ወንዶቹ አምስት ሺህ ነበሩ።'),
  ('c78f1f76-6ce0-5324-af3a-ec350c5a711a', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', 'ff0cb03c-f01b-5629-a340-1e48b58923bd', 1, 45, 'ወዲያውም ሕዝቡን ሲያሰናብት ሳለ ደቀ መዛሙርቱ በታንኳ ገብተው ወደ ማዶ ወደ ቤተ ሳይዳ እንዲቀድሙት ግድ አላቸው።'),
  ('7475465a-2c32-506a-a691-1e5802327fbe', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', 'ff0cb03c-f01b-5629-a340-1e48b58923bd', 2, 46, 'ካሰናበታቸውም በኋላ ሊጸልይ ወደ ተራራ ወጣ።'),
  ('a656d31f-79bc-504c-a3b3-17443eb263da', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', 'ff0cb03c-f01b-5629-a340-1e48b58923bd', 3, 47, 'በመሸም ጊዜ ታንኳይቱ በባሕር መካከል ሳለች እርሱ ብቻውን በምድር ላይ ነበረ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4653bfb1-b52a-594d-a77b-2950b90ea0ca', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', 'ff0cb03c-f01b-5629-a340-1e48b58923bd', 4, 48, 'ነፋስ ከወደ ፊታቸው ነበረና እየቀዘፉ ሲጨነቁ አይቶ፥ ከሌሊቱ በአራተኛው ክፍል በባሕር ላይ እየሄደ ወደ እነርሱ መጣ፤ ሊያልፋቸውም ይወድ ነበር።'),
  ('3aa0b1a3-97c5-593f-a9b6-23cc7dc2b2a0', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', 'ff0cb03c-f01b-5629-a340-1e48b58923bd', 5, 49, 'እነርሱ ግን በባሕር ላይ ሲሄድ ባዩት ጊዜ ምትሀት መሰላቸውና ጮኹ፤'),
  ('f0188102-45a0-5dbe-a88f-f5bdcf00f632', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', 'ff0cb03c-f01b-5629-a340-1e48b58923bd', 6, 50, 'ሁሉ አይተውታልና ታወኩም። ወዲያውም ተናገራቸውና “አይዞአችሁ፤ እኔ ነኝ፤ አትፍሩ፤” አላቸው።'),
  ('fe6ba9d4-7287-5e63-a296-7f0f9389b9e0', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', 'ff0cb03c-f01b-5629-a340-1e48b58923bd', 7, 51, 'ወደ እነርሱም ወደ ታንኳይቱ ገባ፤ ነፋሱም ተወ፤ እነርሱ ራሳቸው ያለ መጠን እጅግ ተገረሙ፤'),
  ('8b07ef41-83d9-5adc-a29e-3b6d2e6e74a2', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', 'ff0cb03c-f01b-5629-a340-1e48b58923bd', 8, 52, 'ስለ እንጀራው አላስተዋሉምና፤ ነገር ግን ልባቸው ደንዝዞ ነበር።'),
  ('2fe2c778-c9cc-5d68-a8a6-91c4cf334cec', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '98e1fba7-9097-5e4b-a3ae-a78abd54c390', 1, 53, 'ተሻግረውም ወደ ምድር ወደ ጌንሴሬጥ ደረሱ፤ ታንኳይቱንም አስጠጉ።'),
  ('95f90844-cf9e-5832-a6d8-abaf4bc99bab', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '98e1fba7-9097-5e4b-a3ae-a78abd54c390', 2, 54, 'ከታንኳይቱም ሲወጡ ወዲያው አውቀውት'),
  ('69e56be1-ab04-5826-a54c-4cd1ca4ea5ce', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '98e1fba7-9097-5e4b-a3ae-a78abd54c390', 3, 55, 'በዚያች አገር ሁሉ ዙሪያ ሮጡና እርሱ እንዳለ ወደ ሰሙበት ስፍራ ሕመምተኞችን በአልጋ ላይ ያመጡ ጀመር።'),
  ('ddb98edc-abf5-58ff-a9ce-ad8562173118', '5e83375a-d4b5-57a1-afd0-d3f1af7d5c25', '98e1fba7-9097-5e4b-a3ae-a78abd54c390', 4, 56, 'በገባበትም ስፍራ ሁሉ፥ መንደርም ከተማም ገጠርም ቢሆን፥ በገበያ ድውዮችን ያኖሩ ነበር፤ የልብሱንም ጫፍ እንኳ ሊዳስሱ ይለምኑት ነበር፤ የዳሰሱትም ሁሉ ዳኑ።'),
  ('16475699-5d2a-59ad-a928-51638425171c', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 1, 1, 'ፈሪሳውያንና ከጻፎች ወገን ከኢየሩሳሌም የመጡትም ወደ እርሱ ተሰበሰቡ።'),
  ('05d29b3a-4013-5420-a95d-15677f3d07f3', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 2, 2, 'ከደቀ መዛሙርቱም አንዳንድ በርኵስ ማለት ባልታጠበ እጅ እንጀራ ሲበሉ አዩ።'),
  ('d0af4ed4-1305-5f53-a8fe-88a90dcd775f', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 3, 3, 'ፈሪሳውያንና አይሁድም ሁሉ የሽማግሎችን ወግ ሲጠብቁ እጃቸውን ደኅና አድርገው ሳይታጠቡ አይበሉምና፤'),
  ('7dcde146-0fc6-5f11-a462-bc5f3e6247f8', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 4, 4, 'ከገበያም ተመልሰው ካልታጠቡ አይበሉም፤ ጽዋንም ማድጋንም የናስ ዕቃንም አልጋንም እንደ ማጠብ ሌላ ነገር ሊጠብቁት የተቀበሉት ብዙ አለ።'),
  ('7af3ea24-f351-5875-ac91-8341e649cbd4', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 5, 5, 'ፈሪሳውያንና ጻፎችም “ደቀ መዛሙርትህ እንደ ሽማግሌዎች ወግ ስለ ምን አይሄዱም? ነገር ግን እጃቸውን ሳይታጠቡ እንጀራ ይበላሉ፤” ብለው ጠየቁት።'),
  ('81fabf32-f1d7-5394-a67f-71560e78adb1', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 6, 6, 'እርሱ ግን እንዲህ አላቸው “ኢሳይያስ ስለ እናንተ ስለ ግብዞች'),
  ('94a6aaca-f6e1-5b2c-a760-af77a266d385', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 7, 7, 'የሰውም ሥርዓት የሆነ ትምህርት እያስተማሩ'),
  ('ef5eda0d-3ab5-5f30-abb5-4ff3d6c4352f', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 8, 9, 'እንዲህም አላቸው “ወጋችሁን ትጠብቁ ዘንድ የእግዚአብሔርን ትእዛዝ እጅግ ንቃችኋል።'),
  ('e438198b-e5dd-5e9e-aadd-e4a1343d69aa', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 9, 10, 'ሙሴ ‘አባትህንና እናትህን አክብር፤’ ደግሞም ‘አባቱን ወይም እናቱን የሰደበ ፈጽሞ ይሙት፤’ ብሎአልና።'),
  ('37a9295e-f3c7-5eed-af26-c00602372161', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 10, 11, 'እናንተ ግን ትላላችሁ ‘ሰው አባቱን ወይም እናቱን ከእኔ የምትጠቀምበት ነገር ሁሉ ቍርባን ማለት መባ ነው፤’ ቢል፥'),
  ('e030e070-4403-54cf-a874-4960a1d73097', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 11, 12, 'ለአባቱና ለእናቱ ምንም እንኳ ሊያደርግ ወደ ፊት አትፈቅዱለትም፤'),
  ('67093e40-7c8e-5f1c-a53e-0064502de835', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 12, 13, 'ባስተላለፋችሁትም ወግ የእግዚአብሔርን ቃል ትሽራላችሁ፤ እንደዚሁም ይህን የሚመስል ብዙ ነገር ታደርጋላችሁ።”'),
  ('a6087114-4127-5cee-a950-f2122c02dd96', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 13, 14, 'ደግሞም ሕዝቡን ጠርቶ “ሁላችሁ እኔን ስሙ፤ አስተውሉም።'),
  ('8a6fa38d-6f86-50e8-a5f5-4448251eae2a', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 14, 15, 'ከሰው የሚወጡት ሰውን የሚያረክሱ ናቸው እንጂ ከሰው ውጭ የሚገባውስ ሊያረክሰው የሚችል ምንም የለም።'),
  ('9446544b-7f69-5ef6-a940-5416f25e5e1b', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 15, 16, 'የሚሰማ ጆሮ ያለው ቢኖር ይስማ፤” አላቸው።'),
  ('af408c1f-91fa-5a63-abab-626b0e5bf2d9', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 16, 17, 'ከሕዝቡ ዘንድ ወደ ቤት ከገባ በኋላ ደቀ መዛሙርቱ ምሳሌውን ጠየቁት።'),
  ('69701e03-758f-5d95-a5ea-8a975608abcd', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 17, 18, 'እርሱም “እናንተ ደግሞ እንደዚህ የማታስተውሉ ናችሁን? ከውጭ ወደ ሰው የሚገባ ሊያረክሰው ምንም እንዳይችል አትመለከቱምን?'),
  ('38c626a8-eed2-5a5f-a68a-e1c3914e303b', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 18, 19, 'ወደ ሆድ ገብቶ ወደ እዳሪ ይወጣል እንጂ ወደ ልብ አይገባምና፤ መብልን ሁሉ እያጠራ፤” አላቸው።'),
  ('3ba76cb1-a7ec-5ffb-aa5d-ab3d58b420ec', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 19, 20, 'እርሱም አለ “ከሰው የሚወጣው ሰውን የሚያረክስ ያ ነው።'),
  ('03ff4aea-0813-5b34-ab21-e61d743b9f30', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 20, 21, 'ከውስጥ ከሰው ልብ የሚወጣ ክፉ አሳብ፥'),
  ('7e9ba55d-523d-56a3-ac3c-64377bca190a', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 21, 22, 'ዝሙት፥ መስረቅ፥ መግደል፥ ምንዝርነት፥ መጐምጀት፥ ክፋት፥ ተንኰል፥ መዳራት፥ ምቀኝነት፥ ስድብ፥ ትዕቢት፥ ስንፍና ናቸውና፤'),
  ('349a7c5c-9831-57e0-a30e-acbf566cff52', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '9822164f-9fd8-5c68-a16f-1f7cf478c50a', 22, 23, 'ይህ ክፉው ሁሉ ከውስጥ ይወጣል፤ ሰውን ያረክሰዋል።”'),
  ('dc68de2d-00b3-5596-aaea-fcc76b90f0d5', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '4f4555f1-19c7-51f0-a28c-3d50e12f104e', 1, 24, 'ከዚያም ተነሥቶ ወደ ጢሮስና ወደ ሲዶና አገር ሄደ። ወደ ቤትም ገብቶ ማንም እንዳያውቅበት ወደደ፤ ሊሰወርም አልተቻለውም፤'),
  ('bdb9c23d-dd7b-57a8-a99c-48ddca101c15', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '4f4555f1-19c7-51f0-a28c-3d50e12f104e', 2, 25, 'ወዲያው ግን ታናሺቱ ልጅዋ ርኵስ መንፈስ ያደረባት አንዲት ሴት ስለ እርሱ ሰምታ መጣችና በእግሩ ላይ ተደፋች፤'),
  ('9b081c58-e8f3-5a64-a8fa-125ca333e502', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '4f4555f1-19c7-51f0-a28c-3d50e12f104e', 3, 26, 'ሴቲቱም ግሪክ፥ ትውልድዋም ሲሮፊኒቃዊት ነበረች፤ ከልጅዋ ጋኔን ያወጣላት ዘንድ ለመነችው።'),
  ('6156b5f5-fc5f-5705-a96f-6ed1777972b2', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '4f4555f1-19c7-51f0-a28c-3d50e12f104e', 4, 27, 'ኢየሱስ ግን “ልጆቹ በፊት ይጠግቡ ዘንድ ተዪ፤ የልጆቹን እንጀራ ይዞ ለቡችሎች መጣል አይገባምና” አላት።'),
  ('5e07ac2a-8f6b-5008-ad5f-db594e78375c', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '4f4555f1-19c7-51f0-a28c-3d50e12f104e', 5, 28, 'እርስዋም መልሳ “አዎን፥ ጌታ ሆይ! ቡችሎች እንኳ ከማዕድ በታች ሆነው የልጆችን ፍርፋሪ ይበላሉ፤” አለችው።'),
  ('afc7b787-d9c3-54ae-a841-1227284c6090', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '4f4555f1-19c7-51f0-a28c-3d50e12f104e', 6, 29, 'እርሱም “ስለዚህ ቃልሽ ሂጂ፤ ጋኔኑ ከልጅሽ ወጥቶአል፤” አላት።'),
  ('91cf126f-601d-5371-a923-4db3ad290580', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '4f4555f1-19c7-51f0-a28c-3d50e12f104e', 7, 30, 'ወደ ቤትዋም ሄዳ ጋኔኑ ወጥቶ ልጅዋም በአልጋ ላይ ተኝታ አገኘች።'),
  ('1d565024-d9a9-58e2-ac1e-36c2446bdc04', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '42134ff9-59c2-5b50-ab3e-e20c23b48d7d', 1, 31, 'ደግሞም ከጢሮስ አገር ወጥቶ በሲዶና አልፎ ዐሥር ከተማ በሚባል አገር መካከል ወደ ገሊላ ባሕር መጣ።'),
  ('279801fc-b6a0-5194-aaf0-6ef4e0aac321', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '42134ff9-59c2-5b50-ab3e-e20c23b48d7d', 2, 32, 'ደንቆሮና ኰልታፋም የሆነ ሰው ወደ እርሱ አመጡ፤'),
  ('b166e59d-0955-539b-ad2f-add3b13acdd4', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '42134ff9-59c2-5b50-ab3e-e20c23b48d7d', 3, 33, 'እጁንም ይጭንበት ዘንድ ለመኑት። ከሕዝቡም ለይቶ ለብቻው ወሰደው፤ ጣቶቹንም በጆሮቹ አገባ፤ እንትፍም ብሎ መላሱን ዳሰሰ፤'),
  ('2ecb516e-fbf0-52f7-abf8-477bf0c3f7f1', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '42134ff9-59c2-5b50-ab3e-e20c23b48d7d', 4, 34, 'ወደ ሰማይም አሻቅቦ አይቶ ቃተተና “ኤፍታህ” አለው፤ እርሱም “ተከፈት” ማለት ነው።'),
  ('d2f3a0c1-d9e5-55e6-a3c3-c9dff5174e7d', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '42134ff9-59c2-5b50-ab3e-e20c23b48d7d', 5, 35, 'ወዲያውም ጆሮቹ ተከፈቱ የምላሱም እስራት ተፈታ፤ አጥርቶም ተናገረ።'),
  ('3d7bb4e2-b57b-53df-a34b-f5a26910a9d3', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '42134ff9-59c2-5b50-ab3e-e20c23b48d7d', 6, 36, '“ለማንም አትንገሩ፤” ብሎ አዘዛቸው፤ እነርሱ ግን ባዘዛቸውም መጠን ይልቅ እጅግ አወሩት።'),
  ('79dc1597-1e76-5c04-a9cc-4213aafe5af2', '8170976a-46df-5d70-a1be-e1eb2e50a9db', '42134ff9-59c2-5b50-ab3e-e20c23b48d7d', 7, 37, 'ያለ መጠንም ተገረሙና “ሁሉን ደኅና አድርጎአል፤ ደንቆሮችም እንዲሰሙ ዲዳዎችም እንዲናገሩ ያደርጋል፤” አሉ።'),
  ('5a7cfeef-48be-5ade-abdd-633de0c0ac51', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 1, 1, 'በዚያ ወራት ደግሞ ብዙ ሕዝብ ነበረ፤ የሚበሉትም ስለሌላቸው ደቀ መዛሙርቱን ጠርቶ'),
  ('78cc68d8-b890-5839-a7d4-6379a14d1344', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 2, 2, '“ሕዝቡ ከእኔ ጋር እስካሁን ሦስት ቀን ውለዋልና የሚበሉት ስለሌላቸው አዝንላቸዋለሁ፤'),
  ('1f218e96-b9c8-5a83-a4f4-3752475884ec', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 3, 3, 'ከእነርሱም አንዳንዶቹ ከሩቅ መጥተዋልና፥ ጦማቸውን ወደ ቤታቸው ባሰናብታቸው በመንገድ ይዝላሉ፤” አላቸው።'),
  ('227cd15f-8147-5ea4-a416-c508d07ee3d8', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 4, 4, 'ደቀ መዛሙርቱም “በዚህ በምድረ በዳ እንጀራ ከየት አግኝቶ ሰው እነዚህን ማጥገብ ይችላል?” ብለው መለሱለት።'),
  ('ef37dde3-c6e4-5f22-afdc-2ca672851c1c', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 5, 5, 'እርሱም “ስንት እንጀራ አላችሁ?” ብሎ ጠየቃቸው፤ እነርሱም “ሰባት” አሉት።'),
  ('1231b3a9-5242-5645-a481-65f5cc65d1e2', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 6, 6, 'ሕዝቡም በምድር እንዲቀመጡ አዘዘ። ሰባቱንም እንጀራ ይዞ አመሰገነ፤ ቈርሶም እንዲያቀርቡላቸው ለደቀ መዛሙርቱ ሰጠ፤ ለሕዝቡም አቀረቡ።'),
  ('7688547a-9c00-5ba3-ac11-61863c80281a', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 7, 7, 'ጥቂትም ትንሽ ዓሣ ነበራቸው፤ ባረከውም፤ ይህንም ደግሞ እንዲያቀርቡላቸው አዘዘ።'),
  ('8df147e6-d2f1-5ad5-a8c7-f64b329cc076', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 8, 8, 'በሉም፤ ጠገቡም፤ የተረፈውንም ቍርስራሽ ሰባት ቅርጫት አነሡ።'),
  ('eb409f63-f0c9-56d0-af14-3f0414c2fac3', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 9, 9, 'የበሉትም አራት ሺህ ያህል ነበሩ፤ አሰናበታቸውም።'),
  ('77e74431-585b-541b-a722-f50bc3753e87', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '0d3cab7f-91ae-5204-afb1-4df18facaaa3', 10, 10, 'ወዲያውም ከደቀ መዛሙርቱ ጋር ወደ ታንኳይቱ ገብቶ ወደ ዳልማኑታ አገር መጣ።'),
  ('f916a67f-5b2f-5345-acf2-00cf29f58c70', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '09c38cea-af5b-57c0-af39-0e2c6d4c9807', 1, 11, 'ፈሪሳውያንም ወጡና ሊፈትኑት ከሰማይ ምልክት ከእርሱ ፈልገው ከእርሱ ጋር ይከራከሩ ጀመር።'),
  ('65e32397-896c-5562-accf-5bbbe7ff9d84', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '09c38cea-af5b-57c0-af39-0e2c6d4c9807', 2, 12, 'በመንፈሱም እጅግ ቃተተና “ይህ ትውልድ ስለ ምን ምልክት ይፈልጋል? እውነት እላችኋለሁ፤ ለዚህ ትውልድ ምልክት አይሰጠውም፤” አለ።'),
  ('a3b53d9a-9719-5b48-abf3-2172cded8c7c', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '09c38cea-af5b-57c0-af39-0e2c6d4c9807', 3, 13, 'ትቶአቸውም እንደ ገና ወደ ታንኳይቱ ገብቶ ወደ ማዶ ሄደ።'),
  ('67474ffc-0d9e-5f54-a329-b22be36de135', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'bf28a8cf-348f-5bbf-a0b5-c8e5d069140c', 1, 14, 'እንጀራ መያዝም ረሱ፤ ለእነርሱም ከአንድ እንጀራ በቀር በታንኳይቱ አልነበራቸውም።'),
  ('fca3f2f5-513e-5940-a36b-4a6f9ca1ef76', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'bf28a8cf-348f-5bbf-a0b5-c8e5d069140c', 2, 15, 'እርሱም “ተጠንቀቁ፤ ከፈሪሳውያንና ከሄሮድስ እርሾ ተጠበቁ፤” ብሎ አዘዛቸው።'),
  ('7d7b7bb5-57a3-5c16-a7ef-e6ae9b0c0376', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'bf28a8cf-348f-5bbf-a0b5-c8e5d069140c', 3, 16, 'እርስ በርሳቸውም “እንጀራ ስለሌለን ይሆናል፤” ብለው ተነጋገሩ።'),
  ('80e28fa6-42ce-5c72-a82b-654de64bec44', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'bf28a8cf-348f-5bbf-a0b5-c8e5d069140c', 4, 17, 'ኢየሱስም አውቆ እንዲህ አላቸው “እንጀራ ስለሌላችሁ ስለ ምን ትነጋገራላችሁ? ገና አልተመለከታችሁምን? አላስተዋላችሁምን?'),
  ('6a52c4bc-1023-5b5f-a1dd-67bef8c69978', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'bf28a8cf-348f-5bbf-a0b5-c8e5d069140c', 5, 18, 'ልባችሁስ ደንዝዞአልን? ዐይን ሳላችሁ አታዩምን? ጆሮስ ሳላችሁ አትሰሙምን? ትዝስ አይላችሁምን?'),
  ('c9e5a931-cf97-556c-a965-d50527e86e28', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'bf28a8cf-348f-5bbf-a0b5-c8e5d069140c', 6, 19, 'አምስቱን እንጀራ ለአምስት ሺህ በቈረስሁ ጊዜ፥ ቍርስራሹ የሞላ ስንት መሶብ አነሣችሁ” እነርሱም “ዐሥራ ሁለት፤” አሉት።'),
  ('76a36c7f-e009-5921-a7b3-07a77a62eff0', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'bf28a8cf-348f-5bbf-a0b5-c8e5d069140c', 7, 20, 'ሰባቱን እንጀራስ ለአራት ሺህ በቈረስሁ ጊዜ፥ ቍርስራሹ የሞላ ስንት ቅርጫት አነሣችሁ? እነርሱም “ሰባት” አሉት።'),
  ('b2f2e88b-efe4-5668-a1bb-0bc5b591fe0f', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'bf28a8cf-348f-5bbf-a0b5-c8e5d069140c', 8, 21, '“ገና አላስተዋላችሁምን?” አላቸው።'),
  ('dbddc617-eac4-5c7f-a297-ab12bd3ac0b2', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '9edd3a10-1100-5746-a7cd-558de7010507', 1, 22, 'ወደ ቤተ ሳይዳም መጡ። ዕውርም አመጡለት፤ እንዲዳስሰውም ለመኑት።'),
  ('41c18213-7be3-56c3-a06e-66aa8df674d8', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '9edd3a10-1100-5746-a7cd-558de7010507', 2, 23, 'ዕውሩንም እጁን ይዞ ከመንደር ውጭ አወጣው፤ በዐይኑም ተፍቶበት እጁንም ጭኖበት “አንዳች ታያለህን?” ብሎ ጠየቀው።'),
  ('bc67f3b5-b63a-5909-a62f-566cb1b2f45c', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '9edd3a10-1100-5746-a7cd-558de7010507', 3, 24, 'አሻቅቦም “ሰዎች እንደ ዛፍ ሲመላለሱ አያለሁ፤” አለ።'),
  ('5e798fb6-fae5-58fb-a97a-60ebdd999a20', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '9edd3a10-1100-5746-a7cd-558de7010507', 4, 25, 'ከዚህም በኋላ ደግሞ እጁን በዐይኑ ላይ ጫነበት፤ አጥርቶም አየ፤ ዳነም፤ ከሩቅም ሳይቀር ሁሉን ተመለከተ።'),
  ('5e34ba03-8bb6-502b-a7a8-5e53f7ed9423', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', '9edd3a10-1100-5746-a7cd-558de7010507', 5, 26, 'ወደ ቤቱም ሰደደውና “ወደ መንደሩ አትግባ፤ በመንደሩም ለማንም አንዳች አትናገር፤” አለው።'),
  ('f2a8793d-8c0a-5396-a483-d55ba6f9f195', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'b9344630-2fda-537d-a2c6-df8d173bfadf', 1, 27, 'ኢየሱስና ደቀ መዛሙርቱም በፊልጶስ ቂሣርያ ወዳሉ መንደሮች ወጡ፤ በመንገድም “ሰዎች እኔ ማን እንደ ሆንሁ ይላሉ?” ብሎ ደቀ መዛሙርቱን ጠየቃቸው።'),
  ('282d5149-f95b-5267-ad45-45a656653d71', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'b9344630-2fda-537d-a2c6-df8d173bfadf', 2, 28, 'እነርሱም “መጥምቁ ዮሐንስ፥ ሌሎችም ኤልያስ፥ ሌሎችም ከነቢያት አንዱ” ብለው ነገሩት።'),
  ('e82ef4df-7fc7-5502-a29c-13b918fbaf96', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'b9344630-2fda-537d-a2c6-df8d173bfadf', 3, 29, '“እናንተስ እኔ ማን እንደ ሆንሁ ትላላችሁ?” ብሎ ጠየቃቸው። ጴጥሮስም “አንተ ክርስቶስ ነህ፤” ብሎ መለሰለት።'),
  ('9fbfb035-1d77-583b-a0af-ee4fa79037c3', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'b9344630-2fda-537d-a2c6-df8d173bfadf', 4, 30, 'ስለ እርሱም ለማንም እንዳይናገሩ አዘዛቸው።'),
  ('b98895b9-dd0a-58c2-ac85-e4fa5cfff065', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'ceb279e7-32da-5720-af78-1ab877489b16', 1, 31, 'የሰው ልጅ ብዙ መከራ ሊቀበል፥ በሽማግሌዎችም በካህናት አለቆችም በጻፎችም ሊናቅ፥ ሊገደልም ከሦስት ቀንም በኋላ ሊነሣ እንዲገባው ያስተምራቸው ጀመር፤ ቃሉንም ገልጦ ይናገር ነበር።'),
  ('2ccda30f-33ea-5048-a900-016ec8751671', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'ceb279e7-32da-5720-af78-1ab877489b16', 2, 32, 'ጴጥሮስም ወደ እርሱ ወስዶ ይገሥጸው ጀመር።'),
  ('8c92c1de-c390-57d2-a694-460a71496972', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'ceb279e7-32da-5720-af78-1ab877489b16', 3, 33, 'እርሱ ግን ዘወር አለ፤ ደቀ መዛሙርቱንም አይቶ ጴጥሮስን ገሠጸውና “ወደ ኋላዬ ሂድ! አንተ ሰይጣን! የሰውን እንጂ የእግዚአብሔርን ነገር አታስብምና፤” አለ።'),
  ('d1fc6a56-cf19-5045-a0da-aa5a4bda8233', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'ceb279e7-32da-5720-af78-1ab877489b16', 4, 34, 'ሕዝቡንም ከደቀ መዛሙርቱ ጋር ጠርቶ እንዲህ አላቸው “በኋላዬ ሊመጣ የሚወድ ቢኖር፥ ራሱን ይካድ፤ መስቀሉንም ተሸክሞ ይከተለኝ።'),
  ('d381edc6-ba56-5e3a-af5f-17f8d78595a4', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'ceb279e7-32da-5720-af78-1ab877489b16', 5, 35, 'ነፍሱን ሊያድን የሚወድ ሁሉ ያጠፋታልና፤ ስለ እኔና ስለ ወንጌል ነፍሱን የሚያጠፋ ሁሉ ግን ያድናታል።'),
  ('dbe60141-3285-5982-af48-b398e1744ded', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'ceb279e7-32da-5720-af78-1ab877489b16', 6, 36, 'ሰው ዓለምን ሁሉ ቢያተርፍ ነፍሱንም ቢያጐድል ምን ይጠቅመዋል?'),
  ('70b980a4-06f9-5314-a717-38afc3db281c', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'ceb279e7-32da-5720-af78-1ab877489b16', 7, 37, 'ሰውስ ስለ ነፍሱ ቤዛ ምን ይሰጣል?'),
  ('9fb2268b-7c11-524c-afc0-4e550fc66707', 'f544e315-ad31-5e67-aac7-7fc9aa14bf09', 'ceb279e7-32da-5720-af78-1ab877489b16', 8, 38, 'በዚህም በዘማዊና በኀጢአተኛ ትውልድ መካከል በእኔና በቃሌ የሚያፍር ሁሉ፥ የሰው ልጅ ደግሞ በአባቱ ክብር ከቅዱሳን መላእክት ጋር በመጣ ጊዜ በእርሱ ያፍርበታል።'),
  ('f58cf9fb-6dd9-500a-ac00-35c9dcc2aeaa', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 1, 1, 'እውነት እላችኋለሁ፥ በዚህ ከቆሙት ሰዎች የእግዚአብሔር መንግሥት በኀይል ስትመጣ እስኪያዩ ድረስ፥ ሞትን የማይቀምሱ አንዳንዶች አሉ፤” አላቸው።'),
  ('720413b4-7546-5f0e-a32c-3434f98c77e9', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 2, 2, 'ከስድስት ቀንም በኋላ ኢየሱስ ጴጥሮስንና ያዕቆብን ዮሐንስንም ይዞ ወደ ረጅም ተራራ ብቻቸውን አወጣቸው። በፊታቸውም ተለወጠ፤ ልብሱም አንጸባረቀ፤'),
  ('b2cac081-01bc-539a-a992-63238c9c3b37', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 3, 3, 'አጣቢም በምድር ላይ እንደዚያ ሊያነጣው እስከማይችል በጣም ነጭ ሆነ።'),
  ('4aecbfa4-7668-526f-a76d-8887443bafe5', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 4, 4, 'ኤልያስና ሙሴም ታዩአቸው፤ ከኢየሱስም ጋር ይነጋገሩ ነበር።'),
  ('4c39a377-4258-5328-ab8d-21b57317bb04', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 5, 5, 'ጴጥሮስም መልሶ ኢየሱስን “መምህር ሆይ! በዚህ መሆን ለእኛ መልካም ነውና አንድ ለአንተ አንድም ለሙሴ አንድም ለኤልያስ ሦስት ዳሶች እንሥራ፤” አለው።'),
  ('e7f978c0-54b3-53b9-ab1b-0aa2e2246bc1', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 6, 6, 'እጅግ ስለ ፈሩ የሚለውን አያውቅም ነበር።'),
  ('bfecb316-c4d2-5500-a9a7-bb3f3fe7f0b6', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 7, 7, 'ደመናም መጥቶ ጋረዳቸው፤ ከደመናውም “የምወደው ልጄ ይህ ነው፤ እርሱን ስሙት፤” የሚል ድምፅ መጣ።'),
  ('73995cd1-a5ee-551e-a11f-2d162c5fbbee', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 8, 8, 'ድንገትም ዞረው ሲመለከቱ ከእነርሱ ጋር ከኢየሱስ ብቻ በቀር ማንንም አላዩም።'),
  ('977b7845-0582-583e-aaf8-6bea4f43a05f', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 9, 9, 'ከተራራውም ሲወርዱ የሰው ልጅ ከሙታን እስኪነሣ ድረስ ያዩትን ለማንም እንዳይነግሩ አዘዛቸው።'),
  ('4f43e402-7d42-5cd5-a7f1-9696f1e88174', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 10, 10, 'ቃሉንም ይዘው “ከሙታን መነሣት ምንድር ነው?” እያሉ እርስ በርሳቸው ተጠያየቁ።'),
  ('d0554ec7-3670-5d52-aa2b-536a7a5e0aa6', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 11, 11, 'እነርሱም “ኤልያስ አስቀድሞ ሊመጣ እንዲገባው ጻፎች ስለ ምን ይላሉ?” ብለው ጠየቁት።'),
  ('a2336a4d-87f7-596a-a992-b0648cf09fa4', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 12, 12, 'እርሱም መልሶ “ኤልያስማ አስቀድሞ ይመጣል፤ ሁሉንም ያቀናል፤ ስለ ሰው ልጅም እንዴት ተብሎ ተጽፎአል? ብዙ መከራ እንዲቀበል እንዲናቅም።'),
  ('862e2705-28a8-5af5-af6f-a0fb0a493dd4', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '804e7ed9-a1ff-5334-acbd-aeff40c2041e', 13, 13, 'ነገር ግን እላችኋለሁ፤ ኤልያስ ደግሞ መጥቶአል፤ ስለ እርሱም እንደ ተጸፈ የወደዱትን ሁሉ አደረጉበት፤” አላቸው።'),
  ('90da7002-66a9-5cca-a167-27bac53fa148', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 1, 14, 'ወደ ደቀ መዛሙርቱም በመጣ ጊዜ ብዙ ሕዝብ ሲከብቡአቸው ጻፎችም ከእነርሱ ጋር ሲከራከሩ አየ።'),
  ('2b832b56-36f9-51f8-a58c-e3a974960415', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 2, 15, 'ወዲያውም ሕዝቡ ሁሉ ባዩት ጊዜ ደነገጡ፤ ወደ እርሱም ሮጠው እጅ ነሡት።'),
  ('426d1fdc-2358-5513-a1a4-70815249b486', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 3, 16, 'ጻፎችንም “ስለ ምን ከእነርሱ ጋር ትከራከራላችሁ?” ብሎ ጠየቃቸው።'),
  ('36bc3029-1572-5750-a21b-944b7357692c', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 4, 17, 'ከሕዝቡ አንዱ መልሶ “መምህር ሆይ! ድዳ መንፈስ ያደረበትን ልጄን ወደ አንተ አምጥቼአለሁ፤'),
  ('9942d76f-001b-5b7b-adf3-720548ea78fd', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 5, 18, 'በያዘውም ስፍራ ሁሉ ይጥለዋል፤ አረፋም ይደፍቃል፤ ጥርሱንም ያፋጫል፤ ይደርቃልም፤ እንዲያወጡለትም ለደቀ መዛሙርትህ ነገርኋቸው፤ አልቻሉምም” አለው።'),
  ('13e24d29-6613-5808-ab85-604824345fb2', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 6, 19, 'እርሱም መልሶ “የማታምን ትውልድ ሆይ! እስከመቼ ከእናንተ ጋር እኖራለሁ? እስከ መቼስ እታገሣችኋለሁ? ወደ እኔ አምጡት፤” አላቸው።'),
  ('08e0360b-6e33-5124-ac40-fc48324dac8e', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 7, 20, 'ወደ እርሱም አመጡት። እርሱንም ባየ ጊዜ ያ መንፈስ ወዲያው አንፈራገጠው፤ ወደ ምድርም ወድቆ አረፋ እየደፈቀ ተንፈራፈረ።'),
  ('ebf00efc-fc12-5f1e-a429-83a7a44a6934', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 8, 21, 'አባቱንም “ይህ ከያዘው ስንት ዘመን ነው?” ብሎ ጠየቀው። እርሱም “ከሕፃንነቱ ጀምሮ ነው፤'),
  ('f0159664-189c-5c1d-a987-9f3070b9faa3', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 9, 22, 'ብዙ ጊዜም ሊያጠፋው ወደ እሳትም ወደ ውኀም ጣለው፤ ቢቻልህ ግን እዘንልን፤ እርዳንም፤” አለው።'),
  ('9b0c4b15-2dcb-5767-adce-258134f63ac8', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 10, 23, 'ኢየሱስም “ቢቻልህ ትላለህ? ለሚያምን ሁሉ ይቻላል፤” አለው።'),
  ('e3cc05ea-8734-532e-a793-1d3e3b4e24a7', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 11, 24, 'ወዲያውም የብላቴናው አባት ጮኾ “አምናለሁ፤ አለማመኔን እርዳው፤” አለ።'),
  ('e37d33d9-20a2-5e99-a243-2d9ee9704ef6', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 12, 25, 'ኢየሱስም ሕዝቡ እንደ ገና ሲራወጥ አይቶ ርኵሱን መንፈስ ገሠጸና “አንተ ድዳ ደንቆሮም መንፈስ፥ እኔ አዝሃለሁ፤ ከእርሱ ውጣ! ከእንግዲህም አትግባበት፤” አለው።'),
  ('ec9b2164-de40-500c-adf1-24f3b4e09098', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 13, 26, 'ጮኾም እጅግም አንፈራግጦት ወጣ፤ ብዙዎችም “ሞተ” እስኪሉ ድረስ እንደ ሙት ሆነ።'),
  ('da730573-61a7-5c8b-a0fe-c1b17e5a84a7', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 14, 27, 'ኢየሱስ ግን እጁን ይዞ አስነሣው፤ ቆመም።'),
  ('490ba835-65c9-5d25-afc9-7e19489b8e72', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 15, 28, 'ወደ ቤትም ከገባ በኋላ ደቀ መዛሙርቱ “እኛ ልናወጣው ያልቻልን ስለ ምንድር ነው?” ብለው ብቻውን ጠየቁት።'),
  ('dfbdffd4-8363-5cee-a063-e6e0554d82a8', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '2357eb02-b63a-5487-a8a4-1a80c06e693a', 16, 29, '“ይህ ወገን በጸሎትና በጦም ካልሆነ በምንም ሊወጣ አይችልም፤” አላቸው።'),
  ('3c770b41-ddda-538a-a75e-07c591aaff4e', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '4e116970-6f26-568f-aa10-a90d9d840430', 1, 30, 'ከዚያም ወጥተው በገሊላ በኩል አለፉ፤ ደቀ መዛሙርቱንም ያስተምር ስለ ነበር ማንም ያውቅ ዘንድ አልወደደም፤ ለእነርሱም “የሰው ልጅ በሰዎች እጅ አልፎ ይሰጣል፤ ይገድሉትማል፤ ተገድሎም በሦስተኛው ቀን ይነሣል፤” ይላቸው ነበር።'),
  ('44b82023-ab0a-538a-a27a-2e283225f37e', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '4e116970-6f26-568f-aa10-a90d9d840430', 2, 32, 'እነርሱም ነገሩን አላስተዋሉም፤ እንዳይጠይቁትም ፈሩ።'),
  ('e5714e64-3c9d-52e0-a4d9-a165c23c8560', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '3cdd69c9-a5a9-51a9-a977-c70fb32de99e', 1, 33, 'ወደ ቅፍርናሆምም መጣ። በቤትም ሆኖ “በመንገድ እርስ በርሳችሁ ምን ተነጋገራችሁ?” ብሎ ጠየቃቸው።'),
  ('aceb930d-cb16-54e9-a26d-aeebf34ffb15', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '3cdd69c9-a5a9-51a9-a977-c70fb32de99e', 2, 34, 'እነርሱ ግን በመንገድ “ከሁሉ የሚበልጥ ማን ይሆን?” ተባብለው ነበርና ዝም አሉ።'),
  ('bbe851a4-d7b9-5ffb-a356-c20717855357', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '3cdd69c9-a5a9-51a9-a977-c70fb32de99e', 3, 35, 'ተቀምጦም ዐሥራ ሁለቱን ጠርቶ “ሰው ፊተኛ ሊሆን ቢወድ ከሁሉ በኋላ የሁሉም አገልጋይ ይሁን፤” አላቸው።'),
  ('89142932-49e3-5a6b-a93f-79898a104a9a', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '3cdd69c9-a5a9-51a9-a977-c70fb32de99e', 4, 36, 'ሕፃንም ይዞ በመካከላቸው አቆመው፤ አቅፎም'),
  ('5e431c8a-4ba6-5549-a205-e65e7c8861a1', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '3cdd69c9-a5a9-51a9-a977-c70fb32de99e', 5, 37, '“እንደዚህ ካሉ ሕፃናት አንዱን በስሜ የሚቀበል ሁሉ እኔን ይቀበላል፤ የሚቀበለኝም ሁሉ የላከኝን እንጂ እኔን አይቀበልም አላቸው።”'),
  ('2a15418e-2c3a-5699-ae70-b7671c33793e', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '3cdd69c9-a5a9-51a9-a977-c70fb32de99e', 6, 38, 'ዮሐንስ መልሶ “መምህር ሆይ! አንድ ሰው በስምህ አጋንንትን ሲያወጣ አየነው፤'),
  ('9fcb129b-9d9a-5e7c-a8b8-c0fbff762e07', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '3cdd69c9-a5a9-51a9-a977-c70fb32de99e', 7, 39, 'ስለማይከተለንም ከለከልነው፤” አለው። ኢየሱስ ግን አለ “በስሜ ተአምር ሠርቶ በቶሎ በእኔ ላይ ክፉ መናገር የሚችል ማንም የለምና አትከልክሉት፤'),
  ('c9693fcb-c858-5942-a236-656818ded950', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '3cdd69c9-a5a9-51a9-a977-c70fb32de99e', 8, 40, 'የማይቃወመን እርሱ ከእኛ ጋር ነውና።'),
  ('f4f482e2-73a1-550b-a382-2698dbe64799', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '3cdd69c9-a5a9-51a9-a977-c70fb32de99e', 9, 41, 'የክርስቶስ ስለ ሆናችሁ በስሜ ጽዋ ውኀ የሚያጠጣችሁ ሁሉ፥ ዋጋው እንዳይጠፋበት እውነት እላችኋለሁ።'),
  ('1b1c0dd8-06a3-57a5-a9e2-325ad142cb3d', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '312e0cc3-4d09-53c2-af51-118ca6399361', 1, 42, '“በእኔም ከሚያምኑት ከእነዚህ ከታናናሾቹ አንዱን የሚያሰናክል ሁሉ ትልቅ የወፍጮ ድንጋይ በአንገቱ ታስሮ ወደ ባሕር ቢጣል ይሻለው ነበር።'),
  ('61986fc4-5837-5dd5-a508-48e14ee45780', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '312e0cc3-4d09-53c2-af51-118ca6399361', 2, 43, 'እጅህ ብታሰናክልህ ቍረጣት፤ ሁለት እጅ ኖሮህ ትላቸው ወደማይሞትበት እሳቱም ወደማይጠፋበት ወደ ገሃነም ወደማይጠፋ እሳት ከመሄድ ጕንድሽ ሆነህ ወደ ሕይወት መግባት ይሻላል።'),
  ('135c0070-fd68-52b1-a5c3-3f66edb0fa95', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '312e0cc3-4d09-53c2-af51-118ca6399361', 3, 45, 'እግርህ ብታሰናክልህ ቍረጣት፤ ሁለት እግር ኖሮህ ትላቸው ወደማይሞትበት እሳቱም ወደማይጠፋበት ወደ ገሃነም ወደማይጠፋ እሳት ከመጣል አንካሳ ሆነህ ወደ ሕይወት መግባት ይሻልሃል።'),
  ('98eb12eb-4922-53c8-abf9-2245e4bc1344', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '312e0cc3-4d09-53c2-af51-118ca6399361', 4, 47, 'ዐይንህ ብታሰናክልህ አውጣት፤ ሁለት ዐይን ኖሮህ ትላቸው ወደማይሞትበት እሳቱም ወደማይጠፋበት ወደ ገሃነመ እሳት ከመጣል አንዲት ዐይን ኖራህ ወደ እግዚአብሔር መንግሥት መግባት ይሻልሃል።'),
  ('c2cbc518-4442-531c-a412-dab940fda960', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '312e0cc3-4d09-53c2-af51-118ca6399361', 5, 49, 'ሰው ሁሉ በእሳት ይቀመማልና፤ መሥዋዕትም ሁሉ በጨው ይቀመማል።'),
  ('75ab916e-464e-59d6-a7de-7bda95c7ce60', '1c4a76f6-55c5-59a0-a9cf-a136812a2c41', '312e0cc3-4d09-53c2-af51-118ca6399361', 6, 50, 'ጨው መልካም ነው፤ ጨው ግን አልጫ ቢሆን በምን ታጣፍጡታላችሁ? በነፍሳችሁ ጨው ይኑርባችሁ፤ እርስ በርሳችሁም ተስማሙ።”'),
  ('ca4f1274-e265-5887-ace1-d41f4db3c4cc', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 1, 1, 'ከዚያም ተነሥቶ በዮርዳኖስ ማዶ ወደ ይሁዳ አገር መጣ፤ ደግሞም ብዙ ሰዎች ወደ እርሱ ተሰበሰቡ፤ እንደ ልማዱም ደግሞ ያስተምራቸው ነበር።'),
  ('3d379936-8610-5f15-ac36-3437653c7b5e', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 2, 2, 'ፈሪሳውያንም ቀርበው “ሰው ሚስቱን ሊፈታ ተፈቅዶለታልን?” ብለው ሊፈትኑት ጠየቁት።'),
  ('24f66004-1852-5aea-a83b-5aef396e321f', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 3, 3, 'እርሱ ግን መልሶ “ሙሴ ምን አዘዛችሁ?” አላቸው።'),
  ('8cf16a5a-7600-5a29-a2c9-58d678c84529', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 4, 4, 'እነርሱም “ሙሴስ የፍችዋን ጽሕፈት ጽፎ እንዲፈታት ፈቀደ፤” አሉ።'),
  ('9033c333-916a-50b9-a115-922e968e77a9', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 5, 5, 'ኢየሱስም መልሶ እንዲህ አላቸው “ስለ ልባችሁ ጥንካሬ ይህችን ትእዛዝ ጻፈላችሁ።'),
  ('dfd489ff-db91-5730-a44a-5b31efa9508d', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 6, 6, 'ከፍጥረት መጀመሪያ ግን እግዚአብሔር ወንድና ሴት አደረጋቸው፤'),
  ('9ef2b7c6-1237-5d36-a3f5-91f47f365641', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 7, 7, 'ስለዚህ ሰው አባቱንና እናቱን ይተዋል፤ ከሚስቱም ጋር ይተባበራል፤'),
  ('f06b5a9e-558a-5ca7-aa87-0f41b27b3332', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 8, 8, 'ሁለቱም አንድ ሥጋ ይሆናሉ፤ ስለዚህ አንድ ሥጋ ናቸው እንጂ ወደ ፊት ሁለት አይደሉም።'),
  ('700219b6-477e-5c2b-afea-9e2a2f6efaa8', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 9, 9, 'እግዚአብሔር ያጣመረውን እንግዲህ ሰው አይለየው።”'),
  ('b6176f3a-f190-5826-ae6b-d66db6522e67', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 10, 10, 'በቤትም ደግሞ ደቀ መዛሙርቱ ስለዚህ ነገር ጠየቁት።'),
  ('72085d38-7f34-530b-a951-894df93f2127', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 11, 11, 'እርሱም “ሚስቱን ፈትቶ ሌላ የሚያገባ ሁሉ በእርስዋ ላይ ያመነዝራል፤'),
  ('d870b428-b457-55b5-a7da-958bde202ea7', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '2065d501-7fd5-5004-ae17-4f292daa0395', 12, 12, 'እርስዋም ባልዋን ፈትታ ሌላ ብታገባ ታመነዝራለች፤” አላቸው።'),
  ('dba616d0-e41b-5e4e-ac75-31947d8ee9b2', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '035a8f5f-df12-5ba7-af8d-28267bdae9a9', 1, 13, 'እንዲዳስሳቸውም ሕፃናትን ወደ እርሱ አመጡ፤ ደቀ መዛሙርቱም ያመጡአቸውን ገሠጹአቸው።'),
  ('93e4834a-80de-5791-a308-28677c5beb09', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '035a8f5f-df12-5ba7-af8d-28267bdae9a9', 2, 14, 'ኢየሱስ ግን አይቶ ተቈጣና “ሕፃናትን ወደ እኔ ይመጡ ዘንድ ተዉ፤ አትከልክሉአቸው፤ የእግዚአብሔር መንግሥት እንደነዚህ ላሉት ናትና።'),
  ('a5bd8672-9726-5205-ab1d-598e3e70f750', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '035a8f5f-df12-5ba7-af8d-28267bdae9a9', 3, 15, 'እውነት እላችኋለሁ፤ የእግዚአብሔርን መንግሥት እንደ ሕፃን የማይቀበላት ሁሉ ከቶ አይገባባትም፤” አላቸው።'),
  ('dfbdede6-968b-51a1-ac42-d8a06af6dc60', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '035a8f5f-df12-5ba7-af8d-28267bdae9a9', 4, 16, 'አቀፋቸውም እጁንም ጭኖ ባረካቸው።'),
  ('0be45fb0-bbeb-5d85-a18a-2e8b516e2ac3', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 1, 17, 'እርሱም በመንገድ ሲወጣ አንድ ሰው ወደ እርሱ ሮጦ ተንበረከከለትና “ቸር መምህር ሆይ! የዘላለም ሕይወትን እወርስ ዘንድ ምን ላድርግ?” ብሎ ጠየቀው።'),
  ('109684ee-8400-5c1a-ad8c-d4d7717fa464', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 2, 18, 'ኢየሱስም “ስለ ምን ቸር ትለኛለህ? ከአንዱ ከእግዚአብሔር በቀር ቸር ማንም የለም።'),
  ('4839a34f-fdf4-5be6-a899-ce7b0c4910ed', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 3, 19, 'ትእዛዛትን ታውቃለህ፤ አታመንዝር፥ አትግደል፥ አትስረቅ፥ በሐሰት አትመስክር፥ አታታልል፥ አባትህንና እናትህን አክብር፤” አለው።'),
  ('efe2a68b-7e9f-5547-a425-8a5bb0f5f2e6', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 4, 20, 'እርሱም መልሶ “መምህር ሆይ! ይህን ሁሉ ከሕፃንነቴ ጀምሬ ጠብቄአለሁ፤” አለው።'),
  ('f54fd5c2-43b7-5641-af94-604a0a63b0b6', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 5, 21, 'ኢየሱስም ወደ እርሱ ተመልክቶ ወደደውና “አንድ ነገር ጐደለህ፤ ሂድ፤ ያለህን ሁሉ ሽጠህ ለድሆች ስጥ፤ በሰማይም መዝገብ ታገኛለህ፤ መስቀሉንም ተሸክመህ ና፤ ተከተለኝ፤” አለው።'),
  ('961d8e61-d176-5489-a39e-9a1bd8f9804b', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 6, 22, 'ነገር ግን ስለዚህ ነገር ፊቱ ጠቈረ፤ ብዙ ንብረት ነበረውና እያዘነም ሄደ።'),
  ('7b5ea808-4d36-5c7a-acd2-20d19b2be9f9', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 7, 23, 'ኢየሱስም ዘወር ብሎ አይቶ ደቀ መዛሙርቱን “ገንዘብ ላላቸው ወደ እግዚአብሔር መንግሥት መግባት እንዴት ጭንቅ ይሆናል፤” አላቸው።'),
  ('8d97333a-afad-5232-ab89-0f3046654ee0', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 8, 24, 'ደቀ መዛሙርቱም እነዚህን ቃሎች አደነቁ። ኢየሱስም ደግሞ መልሶ “ልጆች ሆይ! በገንዘብ ለሚታመኑ ወደ እግዚአብሔር መንግሥት መግባት እንዴት ጭንቅ ነው።'),
  ('adcf2b50-7d2c-5201-ac5b-ffe947903bf6', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 9, 25, 'ባለ ጠጋ ወደ እግዚአብሔር መንግሥት ከሚገባ ግመል በመርፌ ቀዳዳ ቢያልፍ ይቀላል፤” አላቸው።'),
  ('6781651a-dbed-598c-a352-d0326b5fa61f', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 10, 26, 'እነርሱም ያለ መጠን ተገረሙና እርስ በርሳቸው “እንግዲያ ማን ሊድን ይችላል?” ተባባሉ።'),
  ('53aecf63-d6dd-53d2-a994-d238e3e3ccf0', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 11, 27, 'ኢየሱስም ተመለከታቸውና “ይህ በእግዚአብሔር ዘንድ እንጂ በሰው ዘንድ አይቻልም፤ በእግዚአብሔር ዘንድ ሁሉ ይቻላልና፤” አለ።'),
  ('28f4ba29-18c7-5cc2-af57-a215aa5daad3', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 12, 28, 'ጴጥሮስም “እነሆ፥ እኛ ሁሉን ትተን ተከተልንህ፤” ይለው ጀመር።'),
  ('dc43165a-9d77-54fb-aed2-eec812cea8ff', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 13, 29, 'ኢየሱስም መልሶ እንዲህ አለ “እውነት እላችኋለሁ፤ ስለ እኔና ስለ ወንጌል ቤትን ወይም ወንድሞችን ወይም እኅቶችን ወይም አባትን ወይም እናትን ወይም ሚስትን ወይም ልጆችን ወይም እርሻን የተወ፥'),
  ('055a66e7-883a-5959-a996-a0c335318152', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 14, 30, 'አሁን በዚህ ዘመን ከስደት ጋር ቤቶችን ወንድሞችንና እኅቶችንም እናቶችንም ልጆችንም እርሻንም መቶ እጥፍ፥ በሚመጣውም ዓለም የዘላለም ሕይወት የማይቀበል ማንም የለም።'),
  ('9bc517bf-5d2f-5ad3-a6b6-f848416bc013', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '9889ef96-34c7-5c11-add1-df5107446e33', 15, 31, 'ግን ብዙ ፊተኞች ኋለኞች ኋለኞችም ፊተኞች ይሆናሉ።”'),
  ('790c77e6-b996-51b2-a6c6-9dcfc6195565', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '329e72eb-d1c6-5977-a5eb-8e4a1b2c9595', 1, 32, 'ወደ ኢየሩሳሌምም ሊወጡ በመንገድ ነበሩ፤ ኢየሱስም ይቀድማቸው ነበርና ተደነቁ፤ የተከተሉትም ይፈሩ ነበር። ደግሞም ዐሥራ ሁለቱን ወደ እርሱ አቅርቦ ይደርስበት ዘንድ ያለውን ይነግራቸው ጀመር'),
  ('9c305758-ee37-59ee-acec-3ab8006eeb35', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '329e72eb-d1c6-5977-a5eb-8e4a1b2c9595', 2, 33, '“እነሆ፥ ወደ ኢየሩሳሌም እንወጣለን፤ የሰው ልጅም ለካህናት አለቆችና ለጻፎች አልፎ ይሰጣል፤ የሞት ፍርድም ይፈርዱበታል፤ ለአሕዛብም አሳልፈው ይሰጡታል፤'),
  ('318faa12-c1e1-5e48-ae64-9d685bb2371b', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '329e72eb-d1c6-5977-a5eb-8e4a1b2c9595', 3, 34, 'ይዘብቱበትማል፤ ይተፉበትማል፤ ይገርፉትማል፤ ይገድሉትማል፤ በሦስተኛውም ቀን ይነሣል፤” አላቸው።'),
  ('8d4b3d71-5d40-5f36-aaf7-f66aee0c18a7', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 1, 35, 'የዘብዴዎስ ልጆች ያዕቆብና ዮሐንስም ወደ እርሱ ቀርበው “መምህር ሆይ! የምንለምንህን ሁሉ እንድታደርግልን እንወዳለን፤” አሉት።'),
  ('dd1de1b1-df2f-55de-a92c-18186726f7c6', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 2, 36, 'እርሱም “ምን ላደርግላችሁ ትወዳላችሁ?” አላቸው።'),
  ('7b8dc804-dc33-5fe3-a4a7-bde014e60268', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 3, 37, 'እነርሱም “በክብርህ ጊዜ አንዳችን በቀኝ አንዳችንም በግራህ መቀመጥን፤” ስጠን አሉት።'),
  ('8ff1abfa-3f82-55dd-a984-3beb815c2d81', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 4, 38, 'ኢየሱስ ግን “የምትለምኑትን አታውቁም። እኔ የምጠጣውን ጽዋ ልትጠጡ፥ እኔ የምጠመቀውንስ ጥምቀት ልትጠመቁ ትችላላችሁን?” አላቸው።'),
  ('cec3342d-145a-5f6a-a357-cd453bc45657', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 5, 39, 'እነርሱም “እንችላለን፤” አሉት። ኢየሱስም “እኔ የምጠጣውን ጽዋ ትጠጣላችሁ፤ እኔ የምጠመቀውንም ጥምቀት ትጠመቃላችሁ፤'),
  ('6c77eb98-62d1-5a22-a34e-b49d0428a57e', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 6, 40, 'በቀኛና በግራ መቀመጥ ግን ለተዘጋጀላቸው ነው እንጂ የምሰጥ እኔ አይደለሁም፤” አላቸው።'),
  ('c71eadcf-6663-52be-a35f-1008ab0dd7d6', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 7, 41, 'ዐሥሩም ሰምተው በያዕቆብና በዮሐንስ ይቈጡ ጀመር።'),
  ('af836d22-7618-5b4e-a1fa-d6f018ced688', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 8, 42, 'ኢየሱስም ወደ እርሱ ጠርቶ እንዲህ አላቸው “የአሕዛብ አለቆች ተብሎ የምታስቡት እንዲገዙአቸው ታላላቆቻቸውም በላያቸው እንዲሠለጥኑ ታውቃላችሁ።'),
  ('f889e8b3-3654-5160-ac48-91a0d933b025', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 9, 43, 'በእናንተስ እንዲህ አይደለም፤ ነገር ግን ማንም ከእናንተ ታላቅ ሊሆን የሚወድ የእናንተ አገልጋይ ይሁን፤'),
  ('005ffb64-8e3d-5df8-a1d0-d239d6028a3d', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 10, 44, 'ከእናንተም ማንም ፊተኛ ሊሆን የሚወድ የሁሉ ባሪያ ይሁን፤'),
  ('aeb238bb-ffed-5d3a-a6e8-665171a7b182', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', 'd0110764-5519-5fa3-ac49-d8cb9ca1e9d9', 11, 45, 'እንዲሁ የሰው ልጅም ሊያገለግልና ነፍሱን ለብዙዎች ቤዛ ሊሰጥ እንጂ እንዲያገለግሉት አልመጣም።”'),
  ('700da454-731d-5b69-a434-a9c4526f1245', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '80374eac-ccb7-5d28-a8b3-ce6be1c54f5d', 1, 46, 'ወደ ኢያሪኮም መጡ። ከደቀ መዛሙርቱና ከብዙ ሕዝብ ጋር ከኢያሪኮ ሲወጣ የጤሜዎስ ልጅ ዕውሩ በርጤሜዎስ እየለመነ በመንገድ ዳር ተቀምጦ ነበር።'),
  ('29e3762a-bbf3-549b-a15c-2b0d23b01592', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '80374eac-ccb7-5d28-a8b3-ce6be1c54f5d', 2, 47, 'የናዝሬቱ ኢየሱስም እንደ ሆነ በሰማ ጊዜ “የዳዊት ልጅ ኢየሱስ ሆይ!” ማረኝ እያለ ይጮኽ ጀመር።'),
  ('904fe6d1-9e21-5a64-a588-f43ec7c0418b', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '80374eac-ccb7-5d28-a8b3-ce6be1c54f5d', 3, 48, 'ብዙዎችም ዝም እንዲል ገሠጹት፤ እርሱ ግን “የዳዊት ልጅ ሆይ! ማረኝ” እያለ አብዝቶ ጮኸ።'),
  ('aa39fbd9-990c-5012-a29f-7d7b572841c1', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '80374eac-ccb7-5d28-a8b3-ce6be1c54f5d', 4, 49, 'ኢየሱስም ቆመና “ጥሩት” አለ። ዕውሩንም “አይዞህ፤ ተነሣ፤ ይጠራሃል፤” ብለው ጠሩት።'),
  ('20be451c-91e0-5246-a4e6-7d812d6eefc0', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '80374eac-ccb7-5d28-a8b3-ce6be1c54f5d', 5, 50, 'እርሱም እየዘለለ ተነሣና ልብሱን ጥሎ ወደ ኢየሱስ መጣ።'),
  ('78060828-e59e-5941-a64e-3aed47da2278', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '80374eac-ccb7-5d28-a8b3-ce6be1c54f5d', 6, 51, 'ኢየሱስም መልሶ “ምን ላደርግልህ ትወዳለህ?” አለው። ዕውሩም “መምህር ሆይ! አይ ዘንድ፤” አለው።'),
  ('9646aef8-266d-51d6-a9df-7504f0e55715', '6c63fa7d-f9f7-52e6-a7a2-89e1f0e9fbde', '80374eac-ccb7-5d28-a8b3-ce6be1c54f5d', 7, 52, 'ኢየሱስም “ሂድ፤ እምነትህ አድኖሃል፤” አለው። ወዲያውም አየ በመንገድም ተከተለው።'),
  ('fbb4ec10-ea6b-502d-a00e-2c04b7bef541', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 1, 1, 'ወደ ኢየሩሳሌምም ከደብረ ዘይት አጠገብ ወዳሉት ወደ ቤተ ፋጌና ወደ ቢታንያ በቀረቡ ጊዜ፥ ከደቀ መዛሙርቱ ሁለቱን ልኮ'),
  ('e78ba9ff-d2fd-530d-ab82-1f2e3aaf8b23', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 2, 2, '“በፊታችሁ ወዳለችው መንደር ሂዱ፤ ወዲያውም ወደ እርስዋ ገብታችሁ ከሰው ማንም ገና ያልተቀመጠበት ውርንጫ ታስሮ ታገኛላችሁ፤ ፈትታችሁ አምጡልኝ።'),
  ('7b9aeb92-0296-51a5-ad1b-25f5f5f83dd2', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 3, 3, 'ማንም ‘ስለ ምን እንዲህ ታደርጋላችሁ?’ ቢላችሁ ‘ለጌታ ያስፈልገዋል፤’ በሉት፤ ወዲያውም ደግሞ ወደዚህ ይሰደዋል፤” አላቸው።'),
  ('e81c5e78-87bd-5d8b-a56a-e49bf4c861dc', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 4, 4, 'ሄዱም፤ ውርንጫውንም በመንገድ መተላለፊያ በደጅ ውጭ ታስሮ አገኙት፤ ፈቱትም።'),
  ('c535e744-7da0-504b-a3cc-bf6a18a933a3', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 5, 5, 'በዚያም ከቆሙት አንዳንዶቹ “ውርንጫውን የምትፈቱት ምን ልታደርጉት ነው?” አሉአቸው።'),
  ('01648d29-0054-56a3-a424-97332e6203e1', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 6, 6, 'እነርሱም ኢየሱስ እንዳዘዘ አሉአቸው፤ ተዉአቸውም።'),
  ('9e878e02-b3d3-5e07-af08-3315c7ef4dc7', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 7, 7, 'ውርንጫውንም ወደ ኢየሱስ አመጡት፤ ልብሳቸውንም በላዩ ጣሉ፤ ተቀመጠበትም።'),
  ('94be8d28-024b-521d-ab43-0f477dc54f07', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 8, 8, 'ብዙ ሰዎችም ልብሳቸውን በመንገድ ላይ አነጠፉ፤ ሌሎችም ከዛፍ ቅጠሎችን እየቈረጡ ያነጥፉ ነበር።'),
  ('e9a1dfbc-748a-5a47-a18f-b27175b56c46', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 9, 9, 'የሚቀድሙትም የሚከተሉትም “ሆሣዕና! በጌታ ስም የሚመጣ የተባረከ ነው፤'),
  ('02958057-7121-525a-aad7-6756a9acbaa1', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 10, 10, 'በጌታ ስም የምትመጣ የአባታችን የዳዊት መንግሥት የተባረከች ናት፤ ሆሣዕና በአርያም!” እያሉ ይጮኹ ነበር።'),
  ('2bc405fa-b3b5-5425-a002-b6d62ac4a38b', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8ed7d42e-dfd7-56b1-aed6-442a14bc03e2', 11, 11, 'ኢየሱስም ወደ ኢየሩሳሌም ወደ መቅደስ ገባ፤ ዘወር ብሎም ሁሉን ከተመለከተ በኋላ፥ ጊዜው መሽቶ ስለ ነበረ ከዐሥራ ሁለቱ ጋር ወደ ቢታንያ ወጣ።'),
  ('2d993ee2-0678-5c06-aedc-cf3a5d8588e1', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '16572ceb-3316-5ecf-a4db-7b5a4719abe3', 1, 12, 'በማግሥቱም ከቢታንያ ሲወጡ ተራበ።'),
  ('d833c718-1345-5c29-aa60-5658434cb826', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '16572ceb-3316-5ecf-a4db-7b5a4719abe3', 2, 13, 'ቅጠልም ያላት በለስ ከሩቅ አይቶ ምናልባት አንዳች ይገኝባት እንደ ሆነ ብሎ መጣ፤ ነገር ግን የበለስ ወራት አልነበረምና መጥቶ ከቅጠል በቀር ምንም አላገኘባትም።'),
  ('00ef518f-3b06-5eb0-a63d-2fb1e22d8a6d', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '16572ceb-3316-5ecf-a4db-7b5a4719abe3', 3, 14, 'መልሶም “ከአሁን ጀምሮ ለዘላለም ማንም ከአንቺ ፍሬ አይብላ፤” አላት። ደቀ መዛሙርቱም ሰሙ።'),
  ('a9adf246-9240-547e-a55a-8cd7356ab653', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8151dd85-9319-5304-af56-510e71bd1d55', 1, 15, 'ወደ ኢየሩሳሌምም መጡ። ወደ መቅደስም ገብቶ በመቅደስ የሚሸጡትንና የሚገዙትን ያወጣ ጀመር፤ የገንዘብ ለዋጮችንም ገበታዎች የርግብ ሻጭዎችንም ወንበሮች ገለበጠ፤'),
  ('b1b53068-4cc3-5a62-ac5d-e389274bab8d', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8151dd85-9319-5304-af56-510e71bd1d55', 2, 16, 'ዕቃም ተሸክሞ ማንም በመቅደስ ሊያልፍ አልፈቀደም።'),
  ('01cf1b2d-556f-5e93-ac97-945afdfbca61', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8151dd85-9319-5304-af56-510e71bd1d55', 3, 17, 'አስተማራቸውም “‘ቤቴ ለአሕዛብ ሁሉ የጸሎት ቤት ትባላለች፤’ ተብሎ የተጻፈ አይደለምን? እናንተ ግን የወንበዶች ዋሻ አደረጋችኋት፤” አላቸው።'),
  ('84208edb-e429-544d-a611-083254ce2160', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8151dd85-9319-5304-af56-510e71bd1d55', 4, 18, 'የካህናት አለቆችም ጻፎችም ሰምተው፥ ሕዝቡ ሁሉ በትምህርቱ ይገረሙ ስለ ነበር ይፈሩት ነበርና እንዴት አድርገው እንዲያጠፉት ፈለጉ።'),
  ('0e2a944b-e10a-50c9-a93b-08f3bbe1e16d', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '8151dd85-9319-5304-af56-510e71bd1d55', 5, 19, 'ማታ ማታም ከከተማ ወደ ውጭ ይወጣ ነበር።'),
  ('bf636664-7990-5a6a-aceb-791bd08f9526', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', 'e0a89eff-beb5-53c9-abb7-48486048638f', 1, 20, 'ማለዳም ሲያልፉ በለሲቱን ከሥርዋ ደርቃ አዩአት።'),
  ('2c4210ac-6135-537e-a9c5-1533bb7ac838', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', 'e0a89eff-beb5-53c9-abb7-48486048638f', 2, 21, 'ጴጥሮስም ትዝ ብሎት “መምህር ሆይ! እነሆ፥ የረገምሃት በለስ ደርቃለች፤” አለው።'),
  ('1af8599d-5d61-5cc5-a58b-a6a852af2d8e', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', 'e0a89eff-beb5-53c9-abb7-48486048638f', 3, 22, 'ኢየሱስም መልሶ እንዲህ አላቸው “በእግዚአብሔር እመኑ።'),
  ('fff725bc-9d63-5234-aadd-e238521079ba', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', 'e0a89eff-beb5-53c9-abb7-48486048638f', 4, 23, 'እውነት እላችኋለሁ፤ ማንም ያለው ነገር እንዲደረግለት ቢያምን በልቡ ሳይጠራጠር፥ ይህን ተራራ ‘ተነቅለህ ወደ ባሕር ተወርወር፤’ ቢል ይሆንለታል።'),
  ('cdfbac2e-36e2-5a1d-a125-6f2a5e1c7155', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', 'e0a89eff-beb5-53c9-abb7-48486048638f', 5, 24, 'ስለዚህ እላችኋለሁ፤ የጸለያችሁትን የለመናችሁትንም ሁሉ እንዳገኛችሁት እመኑ፤ ይሆንላችሁማል።'),
  ('7b5c4709-4e0f-5f18-ad90-8731eaad7670', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', 'e0a89eff-beb5-53c9-abb7-48486048638f', 6, 25, 'ለጸሎትም በቆማችሁ ጊዜ፥ በሰማያት ያለው አባታችሁ ደግሞ ኀጢአታችሁን ይቅር እንዲላችሁ፥ በማንም ላይ አንዳች ቢኖርባችሁ ይቅር በሉት።'),
  ('4d781db6-101e-5416-a42b-63c7a8b2b097', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', 'e0a89eff-beb5-53c9-abb7-48486048638f', 7, 26, 'እናንተ ግን ይቅር ባትሉ በሰማያት ያለው አባታችሁም ኀጢአታችሁን ይቅር አይላችሁም።”'),
  ('b7c429eb-5c07-5552-accd-100fa56a4661', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '61e82e7d-7e0f-5ea0-a248-9f68455164c5', 1, 27, 'ደግሞም ወደ ኢየሩሳሌም መጡ። እርሱም በመቅደስ ሲመላለስ፥ የካህናት አለቆችና ጻፎች ሽማግሌዎችም ወደ እርሱ መጥተው'),
  ('b111d900-7f2e-5a61-af0a-0f56e67f49ec', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '61e82e7d-7e0f-5ea0-a248-9f68455164c5', 2, 28, '“እነዚህን በምን ሥልጣን ታደርጋለህ? ወይስ እነዚህን ለማድረግ ይህን ሥልጣን ማን ሰጠህ?” አሉት።'),
  ('3fa321c2-bd1e-5cdb-a0c0-c49fe0e4d724', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '61e82e7d-7e0f-5ea0-a248-9f68455164c5', 3, 29, 'ኢየሱስም “እኔም አንዲት ነገር እጠይቃችኋለሁ፤ እናንተም መልሱልኝ፤ እኔም በምን ሥልጣን እነዚህን እንዳደርግ እነግራችኋለሁ።'),
  ('4e3262cf-3817-5503-a40d-00b668a6485e', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '61e82e7d-7e0f-5ea0-a248-9f68455164c5', 4, 30, 'የዮሐንስ ጥምቀት ከሰማይ ነበረችን ወይስ ከሰው? መልሱልኝ፡” አላቸው።'),
  ('3101b966-3b70-536c-a996-39e91de62437', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '61e82e7d-7e0f-5ea0-a248-9f68455164c5', 5, 31, 'እርስ በርሳቸውም ሲነጋገሩ “‘ከሰማይ ነው፤’ ብንል ‘እንግዲያውስ ስለ ምን አላመናችሁበትም?’ ይለናል፤'),
  ('8e4194b4-4541-537a-acad-1d302612e996', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '61e82e7d-7e0f-5ea0-a248-9f68455164c5', 6, 32, 'ነገር ግን ‘ከሰው ነው’ እንበልን?” አሉ፤ ሁሉ ዮሐንስን በእውነት እንደ ነቢይ ያዩት ነበርና ሕዝቡን ፈሩ።'),
  ('2f09a362-f049-5294-a603-9c94ed1af2d3', 'dce93745-e0bb-5e70-a2d8-f13d49804e33', '61e82e7d-7e0f-5ea0-a248-9f68455164c5', 7, 33, 'ለኢየሱስም መልሰው “አናውቅም፤” አሉት ኢየሱስም “እኔም በምን ሥልጣን እነዚህን እንዳደርግ አልነግራችሁም፤” አላቸው።'),
  ('17db21ba-5434-5db1-ad21-2f3c1b210099', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 1, 1, 'በምሳሌም ይነግራቸው ጀመር። “አንድ ሰው የወይን አትክልት ተከለ፤ ቅጥርም ቀጠረለት፤ መጥመቂያም ማሰለት፥ ግንብም ሠራና ለገበሬዎች አከራይቶ ወደ ሌላ አገር ሄደ።'),
  ('0a089b06-8f80-5791-a974-b1dcb8280c0a', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 2, 2, 'በጊዜውም ከወይን አትክልት ፍሬ ከገበሬዎቹ እንዲቀበል አንድ ባሪያ ወደ ገበሬዎቹ ላከ፤'),
  ('9b44d52c-dd47-548d-abf7-9e6ac635d398', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 3, 3, 'ይዘውም ደበደቡት፤ ባዶውንም ሰደዱት።'),
  ('609433ed-1308-5275-a83c-252a3fa3690e', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 4, 4, 'ዳግመኛም ሌላውን ባሪያ ወደ እነርሱ ላከ፤ እርሱንም ወግረው ራሱን አቈሰሉት፤ አዋርደውም ሰደዱት።'),
  ('6e8796ff-859d-5d41-ad53-50a51d43962a', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 5, 5, 'ሌላውንም ላከ፤ እርሱንም ገደሉት፤ ከሌሎችም ከብዙዎች አንዳንዱን ደበደቡ፤ አንዳንዱንም ገደሉ።'),
  ('2459e7ab-b4b5-58c3-a253-1060f1ccf708', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 6, 6, 'የሚወደው አንድ ልጅ ገና ነበረው፤ ‘ልጄንስ ያፍሩታል፤’ ብሎ እርሱን ከሁሉ በኋላ ወደ እነርሱ ላከ።'),
  ('4e853a74-1673-5671-ab92-185cdab2fb57', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 7, 7, 'እነዚያ ገበሬዎች ግን እርስ በርሳቸው ‘ወራሹ ይህ ነው፤ ኑ፤ እንግደለው፤ ርስቱም ለኛ ይሆናል፤’ ተባባሉ።'),
  ('cefa3071-69d2-5dd9-a77b-b29d3e223d4b', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 8, 8, 'ይዘውም ገደሉት፤ ከወይኑም አትክልት ወደ ውጭ ጣሉት።'),
  ('5858759b-5bb4-597e-af90-68c4186f2786', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 9, 9, 'እንግዲህ የወይኑ አትክልት ጌታ ምን ያደርጋል? ይመጣል፤ ገበሬዎቹንም ያጠፋል፤ የወይኑንም አትክልት ለሌሎች ይሰጣል።'),
  ('192f1a6e-902d-531f-a067-6d2228a5c14b', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 10, 10, '‘ግንበኞች የናቁት ድንጋይ እርሱ የማዕዘን'),
  ('341280ea-c389-53de-abb1-ca1fe3925083', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86d0cb81-4677-54c4-a8ae-f7dbd77e87fa', 11, 12, 'ምሳሌውንም ስለ እነርሱ እንደ ተናገረ አውቀዋልና ሊይዙት ፈለጉ፤ ነገር ግን ሕዝቡን ፈሩ። ትተውትም ሄዱ።'),
  ('595103b2-dc37-508f-a912-6fad6e1ab2c7', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'd06ba0f7-686f-5f97-a1ea-0b5a83fed305', 1, 13, 'በንግግርም ሊያጠምዱት ከፈሪሳውያንና ከሄሮድስ ወገን የሆኑትን ወደ እርሱ ላኩ።'),
  ('2bea42fb-f604-5261-ae3e-a881b40a2918', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'd06ba0f7-686f-5f97-a1ea-0b5a83fed305', 2, 14, 'መጥተውም “መምህር ሆይ! የሰውን ፊት ሳትመለከት በእውነት የእግዚአብሔር መንገድ ታስተምራለህና እውነተኛ እንደ ሆንህ ለማንምም እንዳታደላ እናውቃለን፤ ለቄሳር ግብር መስጠት ተፈቅዶአልን ወይስ አልተፈቀደም? እንስጥን ወይስ አንስጥ?” አሉት።'),
  ('bd944f22-b62b-57b1-abe7-db412bd6b4a0', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'd06ba0f7-686f-5f97-a1ea-0b5a83fed305', 3, 15, 'እርሱ ግን ግብዝነታቸውን አውቆ “ለምን ትፈትኑኛላችሁ? አየው ዘንድ አንድ ዲናር አምጡልኝ፤” አላቸው።'),
  ('594b5d67-a416-5dcb-a831-7c371af9efa0', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'd06ba0f7-686f-5f97-a1ea-0b5a83fed305', 4, 16, 'እነርሱም አመጡለት። “ይህች መልክ ጽሕፈቲቱስ የማን ናት?” አላቸው፤ እነርሱም “የቄሳር ናት፤” አሉት።'),
  ('883ec0de-e099-561b-a7ae-58dd29332727', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'd06ba0f7-686f-5f97-a1ea-0b5a83fed305', 5, 17, 'ኢየሱስም መልሶ “የቄሳርን ለቄሳር የእግዚአብሔርንም ለእግዚአብሔር አስረክቡ፤” አላቸው። በእርሱም ተደነቁ።'),
  ('b9894cba-a85d-5662-a2c5-0f46dbaa561a', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'ded12ade-1959-576a-a840-ea2480db9db7', 1, 18, 'ትንሣኤ ሙታን የለም የሚሉ ሰዱቃውያን ወደ እርሱ መጥተው ጠየቁት እንዲህም አሉት'),
  ('1e14d493-59de-5f2b-afee-6c3b82e06d92', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'ded12ade-1959-576a-a840-ea2480db9db7', 2, 19, '“መምህር ሆይ! ሙሴ “የአንድ ሰው ወንድም ሚስቱን ትቶ ልጅ ሳያስቀር ቢሞት፥ ወንድሙ ሚስቱን አግብቶ ለወንድሙ ዘር ይተካ፤’ ብሎ ጻፈልን።'),
  ('8ace8efe-93fe-5d8f-a445-ee6122707ac6', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'ded12ade-1959-576a-a840-ea2480db9db7', 3, 20, 'ሰባት ወንድማማቾች ነበሩ፤ ፊተኛውም ሚስት አግብቶ ዘር ሳያስቀር ሞተ፤'),
  ('f21d6aa1-5943-581c-a7ad-7accd6fa98c2', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'ded12ade-1959-576a-a840-ea2480db9db7', 4, 21, 'ሁለተኛውም አገባት፤ ዘርም ሳይተው ሞተ፤ ሦስተኛውም እንዲሁ፤'),
  ('6f739f42-52d5-5388-a45e-eb68f2f2a165', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'ded12ade-1959-576a-a840-ea2480db9db7', 5, 22, 'ሰባቱም አገቡአት፤ ዘርም አላስቀሩም። ከሁሉም በኋላ ሴቲቱ ደግሞ ሞተች።'),
  ('48447e04-73dc-505d-a900-35ab7112749b', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'ded12ade-1959-576a-a840-ea2480db9db7', 6, 23, 'ሰባቱ አግብተዋታልና በትንሣኤ ቀን ሲነሡ ከእነርሱ ለማናቸው ሚስት ትሆናለች?”'),
  ('86bcdbfd-5222-59bb-aa42-96c4951d0363', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'ded12ade-1959-576a-a840-ea2480db9db7', 7, 24, 'ኢየሱስም መልሶ እንዲህ አላቸው “መጻሕፍትንና የእግዚአብሔርን ኀይል አታውቁምና ስለዚህ የምትስቱ አይደለምን?'),
  ('7e1cd7b4-7376-5c22-a03c-587cbb4c6a14', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'ded12ade-1959-576a-a840-ea2480db9db7', 8, 25, 'ከሙታንስ ሲነሡ በሰማያት እንዳሉ መላእክት ይሆናሉ እንጂ አያገቡም፤ አይጋቡምም።'),
  ('63319788-1c39-5c2f-ab71-b170cd820df8', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', 'ded12ade-1959-576a-a840-ea2480db9db7', 9, 26, 'ስለ ሙታን ግን እንዲነሡ እግዚአብሔር'),
  ('881e995b-30db-510f-aaf7-48f566040309', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '6ed9762a-9863-5c3e-ad88-ff6b4f7187aa', 1, 28, 'ከጻፎችም አንዱ ቀርቦ ሲከራከሩ ሰማና መልካም አድርጎ እንደ መለሰላቸው አስተውሎ “ከሁሉ ፊተኛይቱ ትእዛዝ ማናቸይቱ ናት?” ብሎ ጠየቀው።'),
  ('7969816d-8cce-5b4d-ab7b-216c5532c5e2', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '6ed9762a-9863-5c3e-ad88-ff6b4f7187aa', 2, 29, 'ኢየሱስም መልሶ እንዲህ አለው “ከትእዛዛቱ ሁሉ ፊተኛይቱ ‘እስራኤል ሆይ! ስማ፤ ጌታ አምላካችን አንድ ጌታ ነው፤'),
  ('bbf82811-f267-5552-a253-2b00cd2b2cb9', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '6ed9762a-9863-5c3e-ad88-ff6b4f7187aa', 3, 30, 'አንተም በፍጹም ልብህ በፍጹምም ነፍስህ በፍጹምም አሳብህ በፍጹምም ኀይልህ ጌታ አምላክህን ውደድ፤’ የምትል ናት። ፊተኛይቱ ትእዛዝ ይህች ናት።'),
  ('ca539881-0427-533a-ab39-c6ba1a34c608', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '6ed9762a-9863-5c3e-ad88-ff6b4f7187aa', 4, 31, 'ሁለተኛይቱም ‘ባልንጀራህን እንደ ራስህ ውደድ፤’ የምትል እርስዋን የምትመስል ይህች ናት። ከእነዚህ የምትበልጥ ሌላ ትእዛዝ የለችም።”'),
  ('a1b5a97e-748f-5491-a7fc-5c22f5820ce4', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '6ed9762a-9863-5c3e-ad88-ff6b4f7187aa', 5, 32, 'ጻፊውም “መልካም ነው፤ መምህር ሆይ! ‘አንድ ነው፤ ከእርሱም በቀር ሌላ የለም፤’ ብለህ በእውነት ተናገርህ፤'),
  ('934b8911-98f8-5485-ab6e-2465ff4cc6d4', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '6ed9762a-9863-5c3e-ad88-ff6b4f7187aa', 6, 33, 'በፍጹም ልብ በፍጹም አእምሮም በፍጹም ነፍስም በፍጹም ኀይልም እርሱን መውደድ፥ ባልንጀራንም እንደ ራስ መውደድ በሙሉ ከሚቃጠል መሥዋዕትና ከሌላው መሥዋዕት ሁሉ የሚበልጥ ነው፡” አለው።'),
  ('c77689b9-98b3-5c59-a32a-6e4e39effa48', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '6ed9762a-9863-5c3e-ad88-ff6b4f7187aa', 7, 34, 'ኢየሱስም በማስተዋል እንደ መለሰ አይቶ “አንተ ከእግዚአብሔር መንግሥት የራቅህ አይደለህም፤” አለው። ከዚህም በኋላ ማንም ሊጠይቀው አልደፈረም።'),
  ('d11169aa-3d6e-56a7-a9bb-c30c1e4f8387', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86ade5e5-3dcc-5539-a6f2-c4372a90f7ef', 1, 35, 'ኢየሱስም በመቅደስ ሲያስተምር መልሶ እንዲህ አለ “ጻፎች ‘ክርስቶስ የዳዊት ልጅ ነው፤’ እንዴት ይላሉ?'),
  ('b2a595e1-b577-5d90-aaf6-5131b9c3b12f', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '86ade5e5-3dcc-5539-a6f2-c4372a90f7ef', 2, 36, 'ዳዊት ራሱ በመንፈስ ቅዱስ'),
  ('7a065165-009a-55e6-a619-a4479f823bb4', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '60885a86-295a-5002-a9eb-a3e3fdb5ec3b', 1, 38, 'ሲያስተምርም እንዲህ አለ “ረጃጅም ልብስ ለብሰው መዞርን፥ በገበያም ሰላምታን፥ በምኵራብም የከበሬታን ወንበር፥ በግብዣም የከበሬታን ስፍራ ከሚወዱ ከጻፎች ተጠበቁ፤'),
  ('779d680c-6e68-5462-add4-a89891b79560', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '60885a86-295a-5002-a9eb-a3e3fdb5ec3b', 2, 40, 'የመበለቶችን ቤት የሚበሉ፤ ጸሎታቸውንም በማስረዘም የሚያመካኙ፤ እነዚህ የባሰ ፍርድ ይቀበላሉ።”')
